    "Donors who are currently eligible (exceeded the 90-day donation interval) and ready for matching.": "जो दाता वर्तमान में पात्र हैं (90-दिवसीय दान अंतराल से अधिक हो गए हैं) और मिलान के लिए तैयार हैं।",
