    "Every number below is a real, documented medical outcome.": "नीचे दी गई हर संख्या एक वास्तविक, प्रलेखित चिकित्सा परिणाम है।",
    "Every Thalassemia patient deserves a donor who keeps coming back.": "हर थैलेसीमिया रोगी एक ऐसे दाता का हकदार है जो बार-बार आता रहे।",
    "Everything you need to understand Thalassemia, blood compatibility, and what it means to be a donor or a family.": "थैलेसीमिया, रक्त अनुकूलता, और दाता या परिवार होने का क्या अर्थ है, यह समझने के लिए आपको जो कुछ भी चाहिए।",
    "Executing live routing. Please keep this overlay open...": "लाइव रूटिंग निष्पादित की जा रही है। कृपया इस ओवरले को खुला रखें...",
