    "Expand donor radius": "डोनर रेडियस बढ़ाएँ",
    "Extended Antigen Profile": "विस्तृत एंटीजन प्रोफाइल",
    "Extended phenotyping involves checking for minor antigens in other blood group systems, particularly the Rh subgroups (C, c, E, e) and the Kell system (K, k). Matching these antigens between the donor and recipient reduces the probability of the patient developing antibodies (alloimmunization) by more than 80%.": "विस्तृत फेनोटाइपिंग में अन्य रक्त समूह प्रणालियों में मामूली एंटीजन की जांच करना शामिल है, विशेष रूप से आरएच उपसमूहों (C, c, E, e) और केल प्रणाली (K, k) में। दाता और प्राप्तकर्ता के बीच इन एंटीजन का मिलान करने से रोगी में एंटीबॉडी विकसित होने (एलोइम्यूनाइजेशन) की संभावना 80% से अधिक कम हो जाती है।",
    "Extended Typing": "विस्तृत टाइपिंग",
    "Extended typing goes beyond standard ABO/Rh blood groups to check for minor antigens on your red blood cells (like Rh subgroups C, c, E, e and the Kell system). For Thalassemia patients who receive chronic transfusions, matching these minor antigens is critical to prevent alloimmunization and ensure transfusion safety.": "विस्तृत टाइपिंग मानक ABO/Rh रक्त समूहों से परे जाकर आपकी लाल रक्त कोशिकाओं पर मामूली एंटीजन (जैसे Rh उपसमूह C, c, E, e और केल प्रणाली) की जांच करती है। थैलेसीमिया के मरीज जो नियमित रक्त संक्रमण प्राप्त करते हैं, उनके लिए इन मामूली एंटीजन का मिलान एलोइम्यूनाइजेशन को रोकने और रक्त संक्रमण की सुरक्षा सुनिश्चित करने के लिए महत्वपूर्ण है।",
    "Failure Learning Loop": "विफलता लर्निंग लूप",
    "FAILURE LEARNING LOOP": "विफलता लर्निंग लूप",
    "Families spend hours on phone calls, WhatsApp groups, and hospital queues — hoping someone will show up. It's not a donor shortage. It's a coordination crisis.": "परिवार घंटों फोन कॉल, WhatsApp ग्रुप और अस्पताल की कतारों में बिताते हैं — बस यह उम्मीद करते हुए कि कोई आएगा। यह दाताओं की कमी नहीं है। यह समन्वय का संकट है।",
