    "Finding compatible blood becomes a search for a needle in a haystack, causing critical delays in treatment.": "संगत रक्त खोजना भूसे के ढेर में सुई खोजने जैसा हो जाता है, जिससे उपचार में गंभीर देरी होती है।",
