    "Have questions about blood donation? We've compiled the most common questions from first-time and recurring donors to help you understand the process and your impact.": "क्या आपके पास रक्तदान के बारे में प्रश्न हैं? हमने पहली बार रक्तदान करने वालों और नियमित रक्तदाताओं के सबसे सामान्य प्रश्नों को संकलित किया है ताकि आपको प्रक्रिया और अपने प्रभाव को समझने में मदद मिल सके।",
    "Hb After": "एचबी (Hb) के बाद",
