    "Healthy male donors can donate whole blood every 90 days (3 months), and female donors can donate every 120 days (4 months). This interval ensures that your body has fully replenished its red blood cells and iron stores before your next donation.": "स्वस्थ पुरुष दाता हर 90 दिनों (3 महीने) में रक्तदान कर सकते हैं, और महिला दाता हर 120 दिनों (4 महीने) में रक्तदान कर सकती हैं। यह अंतराल सुनिश्चित करता है कि आपके अगले रक्तदान से पहले आपके शरीर में लाल रक्त कोशिकाओं और आयरन का स्तर पूरी तरह से भर जाए।",
    "Help us ensure you're eligible and understand when you can donate.": "यह सुनिश्चित करने में हमारी सहायता करें कि आप पात्र हैं और समझें कि आप कब दान कर सकते हैं।",
