    "Hyperhemolysis Syndrome:": "हाइपरहेमोलिसिस सिंड्रोम:",
    "I am the patient, parent, or legal guardian authorised to provide this information.": "मैं रोगी, माता-पिता या कानूनी अभिभावक हूं जो यह जानकारी प्रदान करने के लिए अधिकृत हूं।",
    "I consent to Raksha AI storing and processing this patient": "मैं Raksha AI को इस रोगी की जानकारी संग्रहीत और संसाधित करने की सहमति देता हूं",
    "I consent to Raksha AI storing and using this information to coordinate blood donation.": "मैं रक्षा AI को रक्तदान के समन्वय के लिए इस जानकारी को संग्रहीत करने और उपयोग करने के लिए सहमति देता हूं।",
    "I Want to Donate Blood": "मैं रक्तदान करना चाहता हूँ",
    "Identify inactive donors or deferred status updates that require care coordinator intervention.": "उन निष्क्रिय दाताओं या स्थगित स्थिति अपडेट की पहचान करें जिनके लिए देखभाल समन्वयक के हस्तक्षेप की आवश्यकता है।",
    "If you receive mutated genes from both parents, you have thalassemia major (Transfusion-Dependent Thalassemia). Symptoms usually appear within the first two years of life, causing severe anemia, fatigue, pale skin, and slow growth.": "यदि आपको दोनों माता-पिता से उत्परिवर्तित जीन मिलते हैं, तो आपको थैलेसीमिया मेजर (ट्रांसफ्यूजन-निर्भर थैलेसीमिया) होता है। लक्षण आमतौर पर जीवन के पहले दो वर्षों के भीतर दिखाई देते हैं, जिससे गंभीर एनीमिया, थकान, पीली त्वचा और धीमी वृद्धि होती है।",
    "If you receive only one mutated gene from one parent, you have thalassemia minor. Carriers usually have no symptoms or very mild anemia and do not require treatment.": "यदि आपको एक माता-पिता से केवल एक उत्परिवर्तित जीन मिलता है, तो आपको थैलेसीमिया माइनर होता है। वाहकों में आमतौर पर कोई लक्षण या बहुत हल्का एनीमिया नहीं होता है और उन्हें उपचार की आवश्यकता नहीं होती है।",
    "Impact": "प्रभाव",
    "Impact Dashboard": "प्रभाव डैशबोर्ड",
    "Impact So Far": "अब तक का प्रभाव",
    "Impact Stories": "प्रभाव की कहानियाँ",
    "In India alone, over 1 lakh children are born with Thalassemia Major every year. Each patient needs 500-700 transfusions over their lifetime. That's not just 500 blood bags — it's 500 moments of uncertainty, coordination, and hope.": "अकेले भारत में हर साल 1 लाख से अधिक बच्चे थैलेसीमिया मेजर के साथ पैदा होते हैं। प्रत्येक रोगी को अपने जीवनकाल में 500-700 बार रक्त आधान की आवश्यकता होती है। यह सिर्फ 500 ब्लड बैग नहीं हैं — यह अनिश्चितता, समन्वय और आशा के 500 क्षण हैं।",
