    "Instant screening based on ABO/Rh history, location, and alloimmunization risk.": "ABO/Rh इतिहास, स्थान और एलोइम्युनाइजेशन जोखिम के आधार पर तत्काल स्क्रीनिंग।",
    "Interactive Directory Section": "इंटरैक्टिव निर्देशिका अनुभाग",
