    "It wasn't a statistic. It was a name. A face. A mother who spent 6 hours on the phone.": "यह कोई आंकड़ा नहीं था। यह एक नाम था। एक चेहरा। एक माँ जिसने फोन पर 6 घंटे बिताए।",
