    "Join the network of heroes who show up — not once, but every time. Your blood type could be someone's lifeline.": "उन नायकों के नेटवर्क में शामिल हों जो सामने आते हैं — एक बार नहीं, बल्कि हर बार। आपका रक्त प्रकार किसी की जीवन रेखा हो सकता है।",
