    "Most blood donation platforms treat every donation as a one-time transaction. For Thalassemia patients, that model is dangerous. Here's why recurring, compatible donation is a medical necessity.": "अधिकांश रक्त दान प्लेटफ़ॉर्म प्रत्येक दान को एकमुश्त लेनदेन के रूप में मानते हैं। थैलेसीमिया रोगियों के लिए, वह मॉडल खतरनाक है। यहाँ बताया गया है कि आवर्ती, संगत दान एक चिकित्सीय आवश्यकता क्यों है।",
    "Most donors feel fine after donation. Some may experience mild lightheadedness, which quickly resolves after resting for 10-15 minutes and having a light snack and water. We recommend avoiding strenuous physical activity or heavy lifting for the rest of the day.": "अधिकांश दाता दान के बाद ठीक महसूस करते हैं। कुछ को हल्का चक्कर आ सकता है, जो 10-15 मिनट आराम करने और हल्का नाश्ता और पानी लेने के बाद जल्दी ठीक हो जाता है। हम बाकी दिन ज़ोरदार शारीरिक गतिविधि या भारी सामान उठाने से बचने की सलाह देते हैं।",
