    "No more sporadic donations. No more wondering if your blood made a difference. Become a recurring hero for someone who needs you every 21 days.": "अब रुक-रुक कर दान करने की आवश्यकता नहीं। अब यह सोचने की ज़रूरत नहीं कि क्या आपके रक्त से कोई फर्क पड़ा। किसी ऐसे व्यक्ति के लिए बार-बार आने वाले नायक बनें जिसे हर 21 दिनों में आपकी आवश्यकता होती है।",
