    "Protecting lives, one match at a time.": "जीवन बचाना, एक समय में एक मिलान।",
    "Protecting lives, one match at a time. Raksha AI is transforming blood donation in India through intelligent matching and care coordination.": "जीवन की रक्षा, एक समय में एक मिलान। रक्षा AI बुद्धिमान मिलान और देखभाल समन्वय के माध्यम से भारत में रक्तदान को बदल रहा है।",
    "protects.": "सुरक्षा करता है।",
    "Proximity:": "निकटता:",
    "Questions? We're here to help.": "प्रश्न? हम मदद के लिए यहाँ हैं।",
    "Radical Transparency": "पूर्ण पारदर्शिता",
    "Raksha": "रक्षा",
    "Raksha AI": "रक्षा AI",
    "Raksha AI — Blood Intelligence & Care Coordination for Thalassemia Patients": "रक्षा AI — थैलेसीमिया रोगियों के लिए रक्त बुद्धिमत्ता और देखभाल समन्वय",
    "RAKSHA AI — DONOR INTELLIGENCE": "रक्षा AI — डोनर इंटेलिजेंस",
    "Raksha AI builds a dedicated donor circle around your patient. Smart reminders, compatibility matching, and predictive scheduling.": "रक्षा AI आपके रोगी के चारों ओर एक समर्पित दाता मंडल बनाता है। स्मार्ट अनुस्मारक, अनुकूलता मिलान, और भविष्य कहनेवाला शेड्यूलिंग।",
    "Raksha AI builds a permanent support system around your patient.": "रक्षा AI आपके मरीज के चारों ओर एक स्थायी सहायता प्रणाली बनाता है।",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "रक्षा AI पंजीकृत दाताओं के विस्तृत फेनोटाइपिक प्रोफाइल को सूचीबद्ध करता है और उन्हें रोगी प्रोफाइल के साथ मिलाता है। स्थानीय डेटाबेस में सटीक या अत्यधिक संगत एंटीजन मिलान ढूंढकर, हम प्रतिरक्षा प्रतिक्रियाओं को शुरू होने से पहले ही रोकते हैं, जिससे सुरक्षित, प्रभावी और टिकाऊ रक्ताधान सुनिश्चित होता है।",
    "Raksha AI communicates via app, SMS, and WhatsApp — in Hindi, Tamil, Marathi, Bengali, Telugu, and more.": "रक्षा AI ऐप, SMS और WhatsApp के माध्यम से हिंदी, तमिल, मराठी, बंगाली, तेलुगु और अन्य भाषाओं में संवाद करता है।",
    "Raksha AI compression: 85% time saved": "रक्षा AI संपीड़न: 85% समय की बचत",
    "Raksha AI connects voluntary blood donors with Thalassemia patients across India — through intelligent matching, automated scheduling, and care that never stops.": "रक्षा AI भारत भर में थैलेसीमिया रोगियों को स्वैच्छिक रक्तदाताओं से जोड़ता है — बुद्धिमान मिलान, स्वचालित शेड्यूलिंग और निरंतर देखभाल के माध्यम से।",
    "Raksha AI considers ABO compatibility, Rh phenotype, Kell antigen status, and alloimmunization history.": "रक्षा AI ABO अनुकूलता, Rh फिनोटाइप, Kell एंटीजन स्थिति और एलोइम्यूनाइजेशन इतिहास पर विचार करता है।",
    "Raksha AI matches you to a specific patient based on blood compatibility, location, and availability.": "रक्षा AI आपको रक्त अनुकूलता, स्थान और उपलब्धता के आधार पर एक विशिष्ट रोगी से मिलाता है।",
    "Raksha AI v0.1 Launches": "रक्षा AI v0.1 लॉन्च",
    "Raksha AI was built to be the infrastructure Blood Warriors never had — an intelligent, adaptive, multilingual platform that matches donors to patients.": "रक्षा AI का निर्माण उस बुनियादी ढांचे के रूप में किया गया था जो ब्लड वॉरियर्स के पास कभी नहीं था — एक बुद्धिमान, अनुकूली, बहुभाषी मंच जो दाताओं को रोगियों से मिलाता है।",
    "Raksha AI was built to eliminate that uncertainty. We match patients with committed donors, predict transfusion needs, and ensure no patient ever faces a shortage alone.": "रक्षा AI का निर्माण उसी अनिश्चितता को दूर करने के लिए किया गया था। हम रोगियों का प्रतिबद्ध दाताओं से मिलान करते हैं, आधान की आवश्यकताओं का पूर्वानुमान लगाते हैं, और यह सुनिश्चित करते हैं कि किसी भी रोगी को कभी भी अकेले कमी का सामना न करना पड़े।",
