    "We'll use this to build a personalised donor circle and care schedule.": "हम इसका उपयोग एक व्यक्तिगत दाता सर्कल और देखभाल कार्यक्रम बनाने के लिए करेंगे।",
    "We're building their donor circle now.": "हम अब उनका दाता चक्र बना रहे हैं।",
    "Weekly": "साप्ताहिक",
    "Weight (kg)": "वजन (किग्रा)",
    "Weight (kg) *": "वजन (किग्रा) *",
    "Weight: Minimum 50 kg": "वजन: न्यूनतम 50 किग्रा",
    "Welcome back,": "स्वागत है वापस,",
    "What happens next": "आगे क्या होता है",
    "WHAT HAPPENS NEXT": "आगे क्या होता है",
    "What is Alloimmunization?": "एलोइम्युनाइज़ेशन क्या है?",
    "What is Chelation Therapy?": "केलेशन थेरेपी क्या है?",
    "What is extended antigen typing?": "एक्सटेंडेड एंटीजन टाइपिंग क्या है?",
    "What Is Thalassemia?": "थैलेसीमिया क्या है?",
    "What We Stand For": "हमारे मूल्य",
    "What would you like to discuss?": "आप किस बारे में चर्चा करना चाहेंगे?",
    "WhatsApp available?": "क्या व्हाट्सएप उपलब्ध है?",
    "when a patient near me urgently needs my blood type. I can opt out in": "जब मेरे पास कोई मरीज़ तुरंत मेरे ब्लड टाइप की ज़रूरत में हो। मैं इसमें ऑप्ट-आउट कर सकता/सकती हूँ",
    "When there is a mismatch in these minor antigens, the recipient's immune system identifies them as foreign, triggering B-lymphocytes to produce specific alloantibodies. Upon subsequent transfusions with cells carrying the same antigens, the antibodies bind to the donor cells, leading to extravascular hemolysis (destruction of red cells in the spleen or liver).": "जब इन माइनर एंटीजन में बेमेल होता है, तो प्राप्तकर्ता की प्रतिरक्षा प्रणाली उन्हें बाहरी के रूप में पहचानती है, जिससे बी-लिम्फोसाइट्स विशिष्ट एलोएंटीबॉडी उत्पन्न करते हैं। एक ही एंटीजन वाली कोशिकाओं के साथ बाद के रक्ताधान पर, एंटीबॉडी दाता कोशिकाओं से बंध जाते हैं, जिससे एक्स्ट्रावास्कुलर हेमोलिसिस (तिल्ली या यकृत में लाल कोशिकाओं का विनाश) होता है।",
    "When you register as a recurring donor on Raksha AI, you aren't just giving a random unit of blood. You are committing to becoming a lifeline for a specific patient. Regular donations (every 3 months for men, every 4 months for women) provide stable, compatible blood and ensure the patient's hemoglobin levels remain in a safe, healthy zone.": "जब आप रक्षा AI पर एक आवर्ती दाता के रूप में पंजीकरण करते हैं, तो आप केवल रक्त की एक यादृच्छिक इकाई दान नहीं कर रहे होते हैं। आप एक विशिष्ट रोगी के लिए जीवन रेखा बनने के लिए प्रतिबद्ध होते हैं। नियमित दान (पुरुषों के लिए हर 3 महीने में, महिलाओं के लिए हर 4 महीने में) स्थिर, संगत रक्त प्रदान करते हैं और यह सुनिश्चित करते हैं कि रोगी के हीमोग्लोबिन का स्तर एक सुरक्षित, स्वस्थ क्षेत्र में बना रहे।",
    "Where do transfusions happen?": "ट्रांसफ्यूजन कहाँ होते हैं?",
    "Why Iron Overload Happens": "आयरन ओवरलोड क्यों होता है",
    "Why Thalassemia Patients Need the Same Donor to Come Back": "थैलेसीमिया रोगियों को उसी दाता के वापस आने की आवश्यकता क्यों होती है",
    "Why we need this": "हमें इसकी आवश्यकता क्यों है",
    "Why Your Commitment Matters": "आपकी प्रतिबद्धता क्यों मायने रखती है",
    "Window": "विंडो",
    "Window Opens": "विंडो खुलती है",
