    "XGBoost": "XGBoost",
    "Yes": "हाँ",
    "You are not just a blood type. You are someone's lifeline.": "आप सिर्फ एक रक्त प्रकार नहीं हैं। आप किसी की जीवन रेखा हैं।",
    "You donate once. Raksha makes sure you never stop mattering.": "आप एक बार दान करते हैं। रक्षा सुनिश्चित करता है कि आप हमेशा मायने रखें।",
    "You give blood once. Raksha AI turns that into a relationship. We remind you when you're eligible again, match you with patients who need your blood type, and show you the impact you're making — not in abstract numbers, but in real lives.": "आप एक बार रक्तदान करते हैं। रक्षा AI उसे एक रिश्ते में बदल देता. जब आप दोबारा पात्र होते हैं तो हम आपको याद दिलाते हैं, आपकी रक्त समूह की आवश्यकता वाले रोगियों से आपका मिलान करते हैं, और आपके द्वारा किए गए प्रभाव को दिखाते हैं — अमूर्त संख्या में नहीं, बल्कि वास्तविक जीवन में।",
    "You Save a Life": "आप एक जीवन बचाते हैं",
    "You will feel a quick pinch when the needle is inserted, which lasts only a second. During the actual donation, which takes about 8 to 10 minutes, you should feel no pain. Our trained medical staff monitor you throughout the process to ensure you are comfortable.": "सुई डालते समय आपको एक चुभन महसूस होगी, जो केवल एक सेकंड तक रहती है। वास्तविक दान के दौरान, जिसमें लगभग 8 से 10 मिनट लगते हैं, आपको कोई दर्द महसूस नहीं होना चाहिए। हमारे प्रशिक्षित चिकित्सा कर्मचारी यह सुनिश्चित करने के लिए पूरी प्रक्रिया के दौरान आपकी निगरानी करते हैं कि आप सहज महसूस करें।",
    "You're now a Raksha Donor.": "अब आप एक रक्षा दाता हैं।",
    "You're registered,": "आप पंजीकृत हैं,",
    "You're subscribed.": "आप सब्सक्राइब हो गए हैं।",
    "You've been fighting this alone. You don't have to anymore.": "आप अकेले इससे लड़ रहे हैं। अब आपको इसकी आवश्यकता नहीं है।",
    "You've spent years managing transfusion schedules, calling donors, and hoping someone answers. Raksha AI takes that burden off your shoulders. We predict when your child needs blood, find compatible donors, and coordinate everything — so you can focus on being a parent, not a logistics manager.": "आपने आधान के शेड्यूल को प्रबंधित करने, दाताओं को कॉल करने और किसी के जवाब देने की उम्मीद करने में वर्षों बिताए हैं। रक्षा AI उस बोझ को आपके कंधों से हटा देता है। हम भविष्यवाणी करते हैं कि आपके बच्चे को कब रक्त की आवश्यकता है, संगत दाताओं को खोजते हैं, और सब कुछ समन्वित करते हैं — ताकि आप एक रसद प्रबंधक के बजाय माता-पिता बनने पर ध्यान केंद्रित कर सकें।",
    "you@example.com": "you@example.com",
    "you@org.com": "you@org.com",
    "YOUR BADGE COLLECTION": "आपका बैज संग्रह",
    "Your blood has": "आपके रक्त में",
    "Your child's next transfusion is already being arranged.": "आपके बच्चे का अगला ट्रांसफ्यूज़न पहले से ही व्यवस्थित किया जा रहा है।",
    "Your child's next transfusion is already scheduled. Not because you spent all night calling numbers, but because Raksha AI coordinates the schedule. We build a donor circle of 5 committed donors specifically matched to your child.": "आपके बच्चे का अगला आधान पहले से ही निर्धारित है। इसलिए नहीं कि आपने पूरी रात नंबरों पर कॉल करने में बिताई, बल्कि इसलिए कि रक्षा AI शेड्यूल का समन्वय करता है। हम विशेष रूप से आपके बच्चे के लिए अनुकूलित 5 प्रतिबद्ध दाताओं का एक दाता मंडल बनाते हैं।",
    "your child&apos;s circle": "आपके बच्चे का सर्कल",
    "Your circle of donors and caregivers will receive coordinated alerts — so nobody misses a critical transfusion.": "आपके दाताओं और देखभाल करने वालों के समूह को समन्वित अलर्ट प्राप्त होंगे — ताकि कोई भी महत्वपूर्ण रक्ताधान से न चूके।",
