    "ALLOANTIBODIES DETECTED": "అల్లోయాంటీబాడీస్ గుర్తించబడ్డాయి",
    "Alloimmunization occurs when the patient's immune system recognizes minor antigens on the transfused red cells as foreign and produces antibodies against them. Once these antibodies are formed, finding compatible blood becomes extremely difficult. It can lead to acute or delayed hemolytic transfusion reactions, where the body destroys the transfused blood, rendering the treatment ineffective and causing severe clinical complications.": "అలోఇమ్యునైజేషన్ అనేది రోగి యొక్క రోగనిరోధక వ్యవస్థ ఎక్కిన ఎర్ర రక్త కణాలపై ఉండే చిన్న యాంటిజెన్‌లను పరాయివిగా గుర్తించి, వాటికి వ్యతిరేకంగా యాంటీబాడీలను ఉత్పత్తి చేసినప్పుడు జరుగుతుంది. ఈ యాంటీబాడీలు ఏర్పడిన తర్వాత, అనుకూలమైన రక్తాన్ని కనుగొనడం చాలా కష్టమవుతుంది. ఇది తీవ్రమైన లేదా ఆలస్యమైన హిమోలిటిక్ ట్రాన్స్‌ఫ్యూషన్ ప్రతిచర్యలకు దారితీస్తుంది, ఇక్కడ శరీరం ఎక్కిన రక్తాన్ని నాశనం చేస్తుంది, దీనివల్ల చికిత్స పనికిరాకుండా పోయి తీవ్రమైన వైద్య సమస్యలు ఏర్పడతాయి.",
    "Alloimmunization risk prediction model": "అలోఇమ్యునైజేషన్ ప్రమాద అంచనా నమూనా",
