    "At risk": "ప్రమాదంలో ఉంది",
    "At risk (>80% window used)": "ప్రమాదంలో ఉంది (>80% విండో ఉపయోగించబడింది)",
    "At the start of the school year, parents should meet with teachers and the school nurse. Explain Thalassemia in simple terms, detail the transfusion schedule, and discuss signs of low hemoglobin (such as pale skin, extreme fatigue, or shortness of breath). Provide emergency contact details and letters from your child's hematologist.": "విద్యా సంవత్సరం ప్రారంభంలో, తల్లిదండ్రులు ఉపాధ్యాయులను మరియు స్కూల్ నర్సును కలవాలి. థలసేమియా గురించి సరళమైన మాటలలో వివరించండి, రక్త మార్పిడి (ట్రాన్స్‌ఫ్యూషన్) షెడ్యూల్‌ను తెలియజేయండి మరియు తక్కువ హిమోగ్లోబిన్ సంకేతాల (పాలిపోయిన చర్మం, విపరీతమైన అలసట లేదా శ్వాస తీసుకోవడంలో ఇబ్బంది వంటివి) గురించి చర్చించండి. అత్యవసర సంప్రదింపు వివరాలను మరియు మీ బిడ్డ హెమటాలజిస్ట్ నుండి లేఖలను అందించండి.",
