    "Each time a patient receives blood with incompatible minor antigens, their immune system builds resistance. Over hundreds of transfusions, this becomes life-threatening.": "ప్రతిసారీ ఒక రోగి అననుకూలమైన మైనర్ యాంటిజెన్‌లతో కూడిన రక్తాన్ని పొందినప్పుడు, వారి రోగనిరోధక వ్యవస్థ నిరోధకతను పెంచుకుంటుంది. వందలాది ట్రాన్స్‌ఫ్యూజన్‌ల తర్వాత, ఇది ప్రాణాంతకం అవుతుంది.",
    "Each unit of transfused red blood cells contains approximately 200 mg of iron. Over a year of monthly transfusions, this amounts to a significant iron burden. If left untreated, the excess iron deposits in the liver, heart, and endocrine glands, leading to organ failure, heart disease, diabetes, and stunted growth.": "ట్రాన్స్‌ఫ్యూజ్ చేయబడిన ఎర్ర రక్త కణాల ప్రతి యూనిట్‌లో సుమారు 200 mg ఐరన్ ఉంటుంది. ఏడాది పాటు ప్రతి నెలా ట్రాన్స్‌ఫ్యూజన్‌లు చేయడం వల్ల, ఇది గణనీయమైన ఐరన్ భారాన్ని కలిగిస్తుంది. చికిత్స చేయకపోతే, అదనపు ఐరన్ కాలేయం, గుండె మరియు ఎండోక్రైన్ గ్రంథులలో పేరుకుపోయి, అవయవ వైఫల్యం, గుండె జబ్బులు, మధుమేహం మరియు ఎదుగుదల లోపాలకు దారితీస్తుంది.",
