    "Every drop counts. Every match matters.": "ప్రతి చుక్క విలువైనదే. ప్రతి సరిపోలిక ముఖ్యమైనదే.",
    "Every number below is a real, documented medical outcome.": "కింద ఉన్న ప్రతి సంఖ్య నిజమైన, ధృవీకరించబడిన వైద్య ఫలితం.",
    "Every Thalassemia patient deserves a donor who keeps coming back.": "ప్రతి థలసీమియా రోగికి తిరిగి వచ్చే దాత లభించాలి.",
    "Everything you need to understand Thalassemia, blood compatibility, and what it means to be a donor or a family.": "థలసీమియా, రక్త సరిపోలిಕ మరియు దాత లేదా కుటుంబం కావడమంటే ఏమిటో అర్థం చేసుకోవడానికి మీకు కావలసినవన్నీ ఇక్కడ ఉన్నాయి.",
    "Executing live routing. Please keep this overlay open...": "లైవ్ రూటింగ్‌ని అమలు చేస్తోంది. దయచేసి ఈ ఓవర్‌లేను తెరిచి ఉంచండి...",
    "Execution Console Logs": "ఎగ్జిక్యూషన్ కన్సోల్ లాగ్‌లు",
    "Expand donor radius": "దాత పరిధిని విస్తరించండి",
    "Extended Antigen Profile": "విస్తరించిన యాంటిజెన్ ప్రొఫైల్",
    "Extended phenotyping involves checking for minor antigens in other blood group systems, particularly the Rh subgroups (C, c, E, e) and the Kell system (K, k). Matching these antigens between the donor and recipient reduces the probability of the patient developing antibodies (alloimmunization) by more than 80%.": "విస్తరించిన ఫెనోటైపింగ్‌లో ఇతర రక్త సమూహ వ్యవస్థలలో, ముఖ్యంగా Rh ఉప సమూహాలు (C, c, E, e) మరియు కెల్ సిస్టమ్ (K, k) లోని చిన్న యాంటిజెన్‌ల కోసం తనిఖీ చేయడం ఉంటుంది. దాత మరియు గ్రహీత మధ్య ఈ యాంటిజెన్‌లను సరిపోల్చడం వల్ల రోగిలో ప్రతిరోధకాలు (అలో ఇమ్యునైజేషన్) అభివృద్ధి చెందే సంభావ్యత 80% కంటే ఎక్కువగా తగ్గుతుంది.",
    "Extended Typing": "విస్తరించిన టైపింగ్",
    "Extended typing goes beyond standard ABO/Rh blood groups to check for minor antigens on your red blood cells (like Rh subgroups C, c, E, e and the Kell system). For Thalassemia patients who receive chronic transfusions, matching these minor antigens is critical to prevent alloimmunization and ensure transfusion safety.": "విస్తరించిన టైపింగ్ ప్రామాణిక ABO/Rh రక్త సమూహాలకు మించి మీ ఎర్ర రక్త కణాలపై చిన్న యాంటిజెన్‌లను (Rh ఉప సమూహాలు C, c, E, e మరియు కెల్ సిస్టమ్ వంటివి) తనిఖీ చేస్తుంది. దీర్ఘకాలిక రక్తమార్పిడిని పొందే థలసేమియా రోగులకు, అలో ఇమ్యునైజేషన్‌ను నివారించడానికి మరియు రక్తమార్పిడి భద్రతను నిర్ధారించడానికి ఈ చిన్న యాంటిజెన్‌లను సరిపోల్చడం కీలకం.",
    "Failure Learning Loop": "ఫెయిల్యూర్ లెర్నింగ్ లూప్",
    "FAILURE LEARNING LOOP": "ఫెయిల్యూర్ లెర్నింగ్ లూప్",
    "Families spend hours on phone calls, WhatsApp groups, and hospital queues — hoping someone will show up. It's not a donor shortage. It's a coordination crisis.": "ఎవరైనా వస్తారని ఆశిస్తూ కుటుంబాలు ఫోన్ కాల్స్, వాట్సాప్ గ్రూపులు మరియు హాస్పిటల్ কியూలలో గంటల తరబడి గడుపుతారు. ఇది దాతల కొరత కాదు. ఇది సమన్వయ సంక్షోభం.",
