    "Have questions about blood donation? We've compiled the most common questions from first-time and recurring donors to help you understand the process and your impact.": "రక్తదానం గురించి ప్రశ్నలు ఉన్నాయా? మీరు ప్రక్రియను మరియు మీ ప్రభావాన్ని అర్థం చేసుకోవడానికి మొదటిసారి మరియు క్రమం తప్పకుండా రక్తదానం చేసే వారి నుండి అత్యంత సాధారణ ప్రశ్నలను మేము సంకలనం చేశాము.",
    "Hb After": "Hb తర్వాత",
