    "Healthy male donors can donate whole blood every 90 days (3 months), and female donors can donate every 120 days (4 months). This interval ensures that your body has fully replenished its red blood cells and iron stores before your next donation.": "ఆరోగ్యవంతులైన పురుష దాతలు ప్రతి 90 రోజులకు (3 నెలలు) ఒకసారి మరియు మహిళా దాతలు ప్రతి 120 రోజులకు (4 నెలలు) ఒకసారి రక్తదానం చేయవచ్చు. ఈ విరామం మీ తదుపరి రక్తదానానికి ముందు మీ శరీరం ఎర్ర రక్త కణాలను మరియు ఐరన్ నిల్వలను పూర్తిగా తిరిగి పొందేలా చేస్తుంది.",
    "Help us ensure you're eligible and understand when you can donate.": "మీరు అర్హులని నిర్ధారించుకోవడంలో మరియు మీరు ఎప్పుడు దానం చేయవచ్చో అర్థం చేసుకోవడంలో మాకు సహాయపడండి.",
