    "I am the patient, parent, or legal guardian authorised to provide this information.": "నేను ఈ సమాచారాన్ని అందించడానికి అధికారం కలిగిన రోగిని, తల్లిదండ్రులను లేదా చట్టపరమైన సంరక్షకుడిని.",
    "I consent to Raksha AI storing and processing this patient": "ఈ రోగి యొక్క సమాచారాన్ని నిల్వ చేయడానికి మరియు ప్రాసెస్ చేయడానికి నేను Raksha AIకి అంగీకరిస్తున్నాను",
    "I consent to Raksha AI storing and using this information to coordinate blood donation.": "రక్తదానాన్ని సమన్వయం చేయడానికి రక్షా AI ఈ సమాచారాన్ని నిల్వ చేయడానికి మరియు ఉపయోగించడానికి నేను అంగీకరిస్తున్నాను.",
    "I Want to Donate Blood": "నేను రక్తదానం చేయాలనుకుంటున్నాను",
    "Identify inactive donors or deferred status updates that require care coordinator intervention.": "కేర్ కోఆర్డినేటర్ జోక్యం అవసరమైన నిష్క్రియ దాతలు లేదా వాయిదా వేయబడిన స్థితి నవీకరణలను గుర్తించండి.",
    "If you receive mutated genes from both parents, you have thalassemia major (Transfusion-Dependent Thalassemia). Symptoms usually appear within the first two years of life, causing severe anemia, fatigue, pale skin, and slow growth.": "మీకు తల్లిదండ్రుల నుండి మార్పు చెందిన జన్యువులు వస్తే, మీకు థలసేమియా మేజర్ (రక్తమార్పిడి-ఆధారిత థలసేమియా) ఉంటుంది. లక్షణాలు సాధారణంగా జీవితంలోని మొదటి రెండు సంవత్సరాలలో కనిపిస్తాయి, ఇవి తీవ్రమైన రక్తహీనత, అలసట, పాలిపోయిన చర్మం మరియు నెమ్మదిగా పెరుగుదలకు కారణమవుతాయి.",
    "If you receive only one mutated gene from one parent, you have thalassemia minor. Carriers usually have no symptoms or very mild anemia and do not require treatment.": "మీకు తల్లిదండ్రులలో ఒకరి నుండి ఒక మార్పు చెందిన జన్యువు మాత్రమే వస్తే, మీకు థలసేమియా మైనర్ ఉంటుంది. వాహకులకు సాధారణంగా లక్షణాలు ఉండవు లేదా చాలా తేలికపాటి రక్తహీనత ఉంటుంది మరియు చికిత్స అవసరం లేదు.",
    "Impact": "ప్రభావం",
    "Impact Dashboard": "ప్రభావ డాష్‌బోర్డ్",
    "Impact So Far": "ఇప్పటివరకు ప్రభావం",
    "Impact Stories": "ప్రభావ కథలు",
    "In India alone, over 1 lakh children are born with Thalassemia Major every year. Each patient needs 500-700 transfusions over their lifetime. That's not just 500 blood bags — it's 500 moments of uncertainty, coordination, and hope.": "భారతదేశంలోనే ప్రతిసంవత్సరం 1 లక్షకు పైగా పిల్లలు థలసీమియా మేజర్‌తో జన్మిస్తున్నారు. ప్రతి రోగికి వారి జీవితకాలంలో 500-700 రక్త మార్పిడిలు అవసరం. అది కేవలం 500 బ్లడ్ బ్యాగ్‌లు మాత్రమే కాదు — ఇది అనిశ్చితి, సమన్వయం మరియు ఆశ యొక్క 500 క్షణాలు.",
    "In Your Language, On Your Device": "మీ భాషలో, మీ పరికరంలో",
