    "It wasn't a statistic. It was a name. A face. A mother who spent 6 hours on the phone.": "అది కేవలం ఒక గణాంకం కాదు. అది ఒక పేరు. ఒక ముఖం. ఫోన్‌లో 6 గంటలు గడిపిన ఒక తల్లి ఆవేదన.",
