    "Join the network of heroes who show up — not once, but every time. Your blood type could be someone's lifeline.": "ఒక్కసారి మాత్రమే కాదు, ప్రతిసారీ నిలబడే హీరోల నెట్‌వర్క్‌లో చేరండి. మీ బ్లడ్ గ్రూప్ ఒకరి ప్రాణాన్ని నిలబెట్టవచ్చు.",
