    "Managing Absenteeism": "గైర్హాజరీని నిర్వహించడం",
    "Managing TDT requires a multi-specialty medical team, including hematologists, cardiologists, and endocrinologists. Through Raksha AI, patient profiles are synchronized with compatible donor groups to ensure that every transfusion is matched for major and minor antigens, protecting patients from immunization risks over their lifetime.": "TDT నిర్వహణకు హెమటాలజిస్ట్‌లు, కార్డియాలజిస్ట్‌లు మరియు ఎండోక్రినాలజిస్ట్‌లతో కూడిన మల్టీ-స్పెషాలిటీ వైద్య బృందం అవసరం. రక్షా AI ద్వారా, పేషెంట్ ప్రొఫైల్‌లు అనుకూలమైన దాత సమూహాలతో సమకాలీకరించబడతాయి, తద్వారా ప్రతి రక్తదానం మేజర్ మరియు మైనర్ యాంటిజెన్‌లకు సరిపోలుతుందని నిర్ధారిస్తుంది, రోగులను వారి జీవితకాలంలో ఇమ్యునైజేషన్ ప్రమాదాల నుండి కాపాడుతుంది.",
    "Managing transfusion-dependent thalassemia requires meticulous planning, emotional resilience, and active coordination. This guide helps parents navigate the schedule and support their child effectively.": "రక్తమార్పిడి-ఆధారిత తలసేమియాను నిర్వహించడానికి నిశితమైన ప్రణాళిక, మానసిక దృఢత్వం మరియు క్రియాశీల సమన్వయం అవసరం. ఈ గైడ్ తల్లిదండ్రులు షెడ్యూల్‌ను నావిగేట్ చేయడానికి మరియు వారి బిడ్డకు సమర్థవంతంగా మద్దతు ఇవ్వడానికి సహాయపడుతుంది.",
    "Manual confirmation, check-in delays, and coordination gaps at the bedside.": "బెడ్‌సైడ్ వద్ద మాన్యువల్ ధృవీకరణ, చెక్-ఇన్ ఆలస్యం మరియు సమన్వయ అంతరాలు.",
    "Manual Coordination": "మాన్యువల్ సమన్వయం",
