    "Patients with Thalassemia Major require lifelong medical care, including regular blood transfusions (every few weeks) to maintain healthy hemoglobin levels, combined with iron chelation therapy to remove excess iron from the body. For some patients, a bone marrow transplant can offer a permanent cure.": "థలసేమియా మేజర్ ఉన్న రోగులకు జీవితకాల వైద్య సంరక్షణ అవసరం, ఇందులో ఆరోగ్యకరమైన హిమోగ్లోబిన్ స్థాయిలను నిర్వహించడానికి క్రమం తప్పకుండా రక్త మార్పిడి (ప్రతి కొన్ని వారాలకు) మరియు శరీరం నుండి అదనపు ఇనుమును తొలగించడానికి ఐరన్ చ్లెషన్ థెరపీ ఉంటుంది. కొంతమంది రోగులకు, ఎముక మజ్జ మార్పిడి శాశ్వత నివారణను అందించగలదు.",
