    "Post-donation impact stories, milestone badges, and personalized messages keep donors emotionally connected.": "దానం చేసిన తర్వాత ప్రభావ కథనాలు, మైలురాయి బ్యాడ్జ్‌ಗಳು మరియు వ్యక్తిగతీకరించిన సందೇಶాలు దాతలను మానసికంగా అనుసంధానిస్తాయి.",
    "Powered by Claude 3.5 Sonnet": "క్లాడ్ 3.5 సోనెట్ ద్వారా పనిచేస్తుంది",
