    "PRIMARY PATIENT": "ప్రైమరీ పేషెంట్",
    "Privacy": "గోప్యత",
    "Privacy Policy": "గోప్యతా విధానం",
    "Profile Review": "ప్రొఫైల్ సమీక్ష",
    "Profile verified": "ప్రొఫైల్ ధృవీకరించబడింది",
    "Protecting lives, one match at a time.": "ప్రాణాలను కాపాడటం, ఒకే ఒక సరిపోలికతో.",
    "Protecting lives, one match at a time. Raksha AI is transforming blood donation in India through intelligent matching and care coordination.": "ఒక్కో సరిపోలికతో ప్రాణాలను కాపాడుతోంది. రక్షా AI భారతదేశంలో రక్తదానాన్ని విప్లవాత్మకంగా మారుస్తోంది.",
    "protects.": "రక్షిస్తుంది.",
    "Proximity:": "సామీప్యం:",
    "Questions? We're here to help.": "ప్రశ్నలు ఉన్నాయా? మేము సహాయం చేయడానికి ఇక్కడ ఉన్నాము.",
    "Radical Transparency": "సంపూర్ణ పారదర్శకత",
    "Raksha": "రక్ష",
    "Raksha AI": "రక్ష AI",
    "Raksha AI — Blood Intelligence & Care Coordination for Thalassemia Patients": "రక్ష AI — థలసేమియా రోగులకు రక్త మేధస్సు & సంరక్షణ సమన్వయం",
    "RAKSHA AI — DONOR INTELLIGENCE": "రక్ష AI — డోనర్ ఇంటెలిజెన్స్",
    "Raksha AI builds a dedicated donor circle around your patient. Smart reminders, compatibility matching, and predictive scheduling.": "రక్షా AI మీ రోగి చుట్టూ ఒక ప్రత్యేక దాతల సమూహాన్ని నిర్మిస్తుంది. స్మార్ట్ రిమైండర్‌లు, సరిపోలిక మరియు ముందస్తు షెడ్యూలింగ్.",
    "Raksha AI builds a permanent support system around your patient.": "రక్షా AI మీ రోగి చుట్టూ శాಶ್ವత మద్దతు వ్యవస్థను నిర్మిస్తుంది.",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "రక్ష AI రిజిస్టర్డ్ డోనర్ల విస్తృత ఫెనోటైపికల్ ప్రొఫైల్‌లను కేటలాగ్ చేస్తుంది మరియు వాటిని పేషెంట్ ప్రొఫైల్‌లతో సరిపోలుస్తుంది. స్థానిక డేటాబేస్‌లలో ఖచ్చితమైన లేదా అత్యంత అనుకూలమైన యాంటిజెన్ సరిపోలికలను కనుగొనడం ద్వారా, మేము రోగనిరోధక ప్రతిచర్యలను ప్రారంభం కాకముందే నిరోధిస్తాము, సురక్షితమైన, ప్రభావవంతమైన మరియు స్థిరమైన రక్తమార్పిడిని నిర్ధారిస్తాము.",
    "Raksha AI communicates via app, SMS, and WhatsApp — in Hindi, Tamil, Marathi, Bengali, Telugu, and more.": "రక్షా AI యాప్, SMS మరియు వాట్సాప్ ద్వారా హిందీ, తమిళం, మరాఠీ, బెంగాలీ, తెలుగు మరియు మరిన్ని భాషలలో కమ్యూనికేట్ చేస్తుంది.",
    "Raksha AI compression: 85% time saved": "రక్ష AI కంప్రెషన్: 85% సమయం ఆదా చేయబడింది",
    "Raksha AI connects voluntary blood donors with Thalassemia patients across India — through intelligent matching, automated scheduling, and care that never stops.": "రక్షా AI భారతదేశంలోని థలసీమియా రోగులను స్వచ్ఛంద రక్తదాతలతో కలుపుతుంది — తెలివైన సరిపోలిక, ఆటోమేటిక్ షెడ్యూలింగ్ మరియు నిరంతర సంరక్షణ ద్వారా.",
    "Raksha AI considers ABO compatibility, Rh phenotype, Kell antigen status, and alloimmunization history.": "రక్షా AI ABO సరిపోలిక, Rh ఫినోటైప్, కెల్ యాంటిజెన్ స్థితి మరియు అలో ఇమ్యునైజేషన్ చరిత్రను పరిగణనలోకి తీసుకుంటుంది.",
    "Raksha AI matches you to a specific patient based on blood compatibility, location, and availability.": "ರಕ್ತದ ಹೊಂದಾಣಿಕೆ, ಸ್ಥಳ ಮತ್ತು ಲಭ್ಯತೆಯ ಆಧಾರದ ಮೇಲೆ ರಕ್ಷಾ AI ನಿಮ್ಮನ್ನು ನಿರ್ದಿಷ್ಟ ರೋಗಿಗೆ ಹೊಂದಿಸುತ್ತದೆ.",
    "Raksha AI v0.1 Launches": "రక్ష AI v0.1 లాంచ్‌లు",
    "Raksha AI was built to be the infrastructure Blood Warriors never had — an intelligent, adaptive, multilingual platform that matches donors to patients.": "బ్లడ్ వారియర్స్ ఫౌండేషన్‌కు ఎన్నడూ లేని మౌలిక సదుಪాయంగా ఉండటానికి రక్షా AI నిర్మించబడింది — ఇది దాతలను రోగులతో సరిపోల్చే ఒక తెలివైన, అనుకూలమైన, బహుభాషా వేదిక.",
    "Raksha AI was built to eliminate that uncertainty. We match patients with committed donors, predict transfusion needs, and ensure no patient ever faces a shortage alone.": "ఆ అనిశ్చితిని తొలగించడానికే రక్షా AI నిర్మించబడింది. మేము రోగులను నిబద్ధత గల దాతలతో సరిపోల్చుతాము, రక్త మార్పిడి అవసరాలను అంచనా వేస్తాము మరియు ఏ రోగి కూడా ఒంటరిగా కొరతను ఎదుర్కోకుండా చూస్తాము.",
