    "\"I donated for the first time last year. Raksha matched me in 22 minutes. The family called me. I cried.\"": "\"मी गेल्या वर्षी पहिल्यांदा रक्तदान केले. रक्षाने मला 22 मिनिटांत जुळवले. कुटुंबियांनी मला बोलावले. मी रडले.\"",
    "\"We did not build Raksha to be a startup. We built it because the alternative was watching children die waiting for a phone call that never came.\"": "\"आम्ही रक्षाला स्टार्टअप म्हणून तयार केले नाही. आम्ही ते तयार केले कारण पर्याय म्हणजे फोनची वाट पाहणाऱ्या मुलांचा मृत्यू पाहणे जो कधीच आला नाही.\"",
    "“When you save a life every 21 days, you don't just become a donor. You become family.”": "“जेव्हा तुम्ही दर २१ दिवसांनी एक जीव वाचवता, तेव्हा तुम्ही केवळ दाता राहत नाही. तुम्ही कुटुंबाचा भाग बनता.”",
