    "At the start of the school year, parents should meet with teachers and the school nurse. Explain Thalassemia in simple terms, detail the transfusion schedule, and discuss signs of low hemoglobin (such as pale skin, extreme fatigue, or shortness of breath). Provide emergency contact details and letters from your child's hematologist.": "शालेय वर्षाच्या सुरुवातीला पालकांनी शिक्षकांना आणि शाळेच्या नर्सला भेटले पाहिजे. थॅलेसेमिया सोप्या भाषेत समजावून सांगा, रक्त संक्रमणाचे (ट्रान्सफ्युजन) वेळापत्रक तपशीलवार सांगा आणि कमी हिमोग्लोबिनच्या लक्षणांवर (जसे की फिकट त्वचा, कमालीचा थकवा किंवा श्वास घेण्यास त्रास होणे) चर्चा करा. आपत्कालीन संपर्क तपशील आणि तुमच्या मुलाच्या हेमॅटोलॉजिस्टची पत्रे द्या.",
