    "Blood Warriors": "ब्लड वॉरियर्स",
    "BLOOD WARRIORS × RAKSHA AI": "ब्लड वॉरियर्स × रक्षा AI",
    "Blood Warriors Foundation": "ब्लड वॉरियर्स फाउंडेशन",
    "Blood Warriors Foundation has spent years building a donor community and Blood Bridge network across India. But the matching is manual. The engagement fades. The coordination is fragile.": "ब्लड वॉरियर्स फाउंडेशनने संपूर्ण भारतात रक्तदाता समुदाय आणि ब्लड ब्रिज नेटवर्क तयार करण्यासाठी वर्षे घालवली आहेत. परंतु जुळणी मॅन्युअल आहे. सहभाग कमी होतो. समन्वय नाजूक आहे.",
    "Blood Warriors Foundation, Mumbai, India": "ब्लड वॉरियर्स फाउंडेशन, मुंबई, भारत",
    "Blood Warriors Founded": "ब्लड वॉरियर्सची स्थापना",
