    "Finding a Matching Donor": "जुळणारा दाता शोधणे",
    "Finding compatible blood becomes a search for a needle in a haystack, causing critical delays in treatment.": "जुळणारे रक्त शोधणे हे गवताच्या गंजीत सुई शोधण्यासारखे होते, ज्यामुळे उपचारात गंभीर विलंब होतो.",
