    "For Donors": "दात्यांसाठी",
    "For Donors | Raksha AI": "दात्यांसाठी | रक्षा AI",
    "For individuals with TDT, red blood cells are fragile and break down rapidly. Standard therapy involves regular blood transfusions every 2 to 4 weeks. These transfusions supply the body with healthy donor red blood cells, enabling oxygen delivery and suppressing the body’s own overactive bone marrow, which prevents skeletal deformities and other severe complications.": "TDT असलेल्या व्यक्तींसाठी, लाल रक्तपेशी नाजूक असतात आणि लवकर तुटतात. मानक उपचारांमध्ये दर 2 ते 4 आठवड्यांनी नियमित रक्त संक्रमण (blood transfusions) समाविष्ट असते. हे संक्रमण शरीराला निरोगी दाता लाल रक्तपेशी पुरवतात, ज्यामुळे ऑक्सिजन पोहोचतो आणि शरीराच्या स्वतःच्या अतिसक्रिय अस्थिमज्जाला दाबले जाते, जे हाडांचे विकृतीकरण आणि इतर गंभीर गुंतागुंत टाळते.",
    "for notifications & reports": "सूचना आणि अहवालांसाठी",
    "For Patients": "रुग्णांसाठी",
    "For Patients & Families | Raksha AI": "रुग्ण आणि कुटुंबांसाठी | रक्षा AI",
    "For patients with Transfusion-Dependent Thalassemia, a Bone Marrow Transplant (BMT) — also known as a Hematopoietic Stem Cell Transplant — currently offers the only established, permanent cure.": "रक्तसंक्रमणावर अवलंबून असलेल्या थॅलेसेमिया (Transfusion-Dependent Thalassemia) रुग्णांसाठी, बोन मॅरो ट्रान्सप्लांट (BMT) — ज्याला हेमेटोपोएटिक स्टेम सेल ट्रान्सप्लांट (Hematopoietic Stem Cell Transplant) असेही म्हणतात — सध्या हा एकमेव स्थापित, कायमस्वरूपी उपचार आहे.",
    "FOR THALASSEMIA FAMILIES": "थॅलेसेमिया कुटुंबांसाठी",
