    "GOOD MORNING": "शुभ सकाळ",
    "Group": "गट",
    "Guardian Mobile *": "पालकांचा मोबाइल *",
    "Have questions about blood donation? We've compiled the most common questions from first-time and recurring donors to help you understand the process and your impact.": "रक्तदानाबद्दल काही प्रश्न आहेत का? पहिल्यांदा रक्तदान करणाऱ्या आणि नियमित रक्तदात्यांच्या सामान्य प्रश्नांचे संकलन आम्ही केले आहे, जेणेकरून तुम्हाला ही प्रक्रिया आणि तुमचा प्रभाव समजण्यास मदत होईल.",
    "Hb After": "Hb नंतर",
    "Hb Before": "Hb पूर्वी",
    "Health Insights": "आरोग्यविषयक माहिती",
    "Health Tracker": "आरोग्य ट्रॅकर",
    "Healthy male donors can donate whole blood every 90 days (3 months), and female donors can donate every 120 days (4 months). This interval ensures that your body has fully replenished its red blood cells and iron stores before your next donation.": "निरोगी पुरुष रक्तदाते दर 90 दिवसांनी (3 महिने) आणि महिला रक्तदाते दर 120 दिवसांनी (4 महिने) रक्तदान करू शकतात. हे अंतर तुमच्या पुढच्या रक्तदानापूर्वी शरीरातील तांबड्या रक्तपेशी आणि लोहाची पातळी पूर्णपणे भरून निघेल याची खात्री करते.",
    "Help us ensure you're eligible and understand when you can donate.": "तुम्ही पात्र आहात याची खात्री करण्यात आणि तुम्ही केव्हा दान करू शकता हे समजून घेण्यास आम्हाला मदत करा.",
