    "Hyperhemolysis Syndrome:": "हायपरहेमोलिसिस सिंड्रोम:",
    "I am the patient, parent, or legal guardian authorised to provide this information.": "मी रुग्ण, पालक किंवा कायदेशीर पालक आहे जो ही माहिती प्रदान करण्यासाठी अधिकृत आहे.",
    "I consent to Raksha AI storing and processing this patient": "मी या रुग्णाची माहिती साठवण्यासाठी आणि त्यावर प्रक्रिया करण्यासाठी Raksha AI ला संमती देतो",
    "I consent to Raksha AI storing and using this information to coordinate blood donation.": "रक्तदानाचा समन्वय साधण्यासाठी रक्षा AI ला ही माहिती साठवण्यास आणि वापरण्यास माझी संमती आहे.",
    "I Want to Donate Blood": "मला रक्तदान करायचे आहे",
    "Identify inactive donors or deferred status updates that require care coordinator intervention.": "निष्क्रिय दाते किंवा स्थगित स्थिती अद्यतने ओळखा ज्यांना केअर कोऑर्डिनेटर हस्तक्षेपाची आवश्यकता आहे.",
    "If you receive mutated genes from both parents, you have thalassemia major (Transfusion-Dependent Thalassemia). Symptoms usually appear within the first two years of life, causing severe anemia, fatigue, pale skin, and slow growth.": "जर तुम्हाला दोन्ही पालकांकडून उत्परिवर्तित जनुके मिळाली, तर तुम्हाला थॅलेसेमिया मेजर (रक्तसंक्रमण-अवलंबित थॅलेसेमिया) आहे. लक्षणे सामान्यतः आयुष्याच्या पहिल्या दोन वर्षांत दिसतात, ज्यामुळे तीव्र ॲनिमिया, थकवा, फिकट त्वचा आणि वाढ खुंटते.",
    "If you receive only one mutated gene from one parent, you have thalassemia minor. Carriers usually have no symptoms or very mild anemia and do not require treatment.": "जर तुम्हाला एका पालकाकडून फक्त एक उत्परिवर्तित जनुक मिळाले, तर तुम्हाला थॅलेसेमिया मायनर आहे. वाहकांना सहसा लक्षणे नसतात किंवा खूप सौम्य ॲनिमिया असतो आणि त्यांना उपचारांची आवश्यकता नसते.",
    "Impact": "प्रभाव",
    "Impact Dashboard": "प्रभाव डॅशबोर्ड",
    "Impact So Far": "आतापर्यंतचा प्रभाव",
    "Impact Stories": "प्रभाव कथा",
    "In India alone, over 1 lakh children are born with Thalassemia Major every year. Each patient needs 500-700 transfusions over their lifetime. That's not just 500 blood bags — it's 500 moments of uncertainty, coordination, and hope.": "एकट्या भारतात दरवर्षी १ लाखाहून अधिक मुले थॅलेसेमिया मेजरसह जन्माला येतात. प्रत्येक रुग्णाला त्यांच्या आयुष्यभरात ५००-७०० वेळा रक्तसंक्रमणाची गरज असते. त्या केवळ ५०० रक्ताच्या पिशव्या नाहीत — ते अनिश्चितता, समन्वय आणि आशेचे ५०० क्षण आहेत।",
