    "It wasn't a statistic. It was a name. A face. A mother who spent 6 hours on the phone.": "ती आकडेवारी नव्हती. ते नाव होते. एक चेहरा होता. फोनवर ६ तास घालवणारी एक आई होती.",
    "Join the Mission": "मिशनमध्ये सामील व्हा",
    "Join the network of heroes who show up — not once, but every time. Your blood type could be someone's lifeline.": "एकदा नव्हे तर प्रत्येक वेळी मदतीला धावून जाणाऱ्या नायकांच्या जाळ्यात सामील व्हा. तुमचा रक्तगट कोणासाठी तरी जीवनदायी ठरू शकतो.",
