    "Maintaining Target Hemoglobin Levels": "लक्ष्यित हिमोग्लोबिन पातळी राखणे",
    "Male": "पुरुष",
    "Managing Absenteeism": "गैरहजेरी व्यवस्थापित करणे",
    "Managing TDT requires a multi-specialty medical team, including hematologists, cardiologists, and endocrinologists. Through Raksha AI, patient profiles are synchronized with compatible donor groups to ensure that every transfusion is matched for major and minor antigens, protecting patients from immunization risks over their lifetime.": "TDT च्या व्यवस्थापनासाठी हेमेटोलॉजिस्ट, कार्डिओलॉजिस्ट आणि एंडोक्रिनोलॉजिस्टसह बहु-स्पेशालिटी वैद्यकीय टीमची आवश्यकता असते. रक्षा AI द्वारे, प्रत्येक रक्तसंक्रमण प्रमुख आणि किरकोळ प्रतिजनांसाठी (antigens) जुळले आहे याची खात्री करण्यासाठी पेशंट प्रोफाइल सुसंगत डोनर गटांसह सिंक्रोनाइझ केले जातात, ज्यामुळे रुग्णांचे त्यांच्या आयुष्यात इम्युनायझेशनच्या जोखमींपासून संरक्षण होते.",
    "Managing transfusion-dependent thalassemia requires meticulous planning, emotional resilience, and active coordination. This guide helps parents navigate the schedule and support their child effectively.": "रक्तसंक्रमणावर अवलंबून असलेल्या थॅलेसेमियाचे व्यवस्थापन करण्यासाठी सूक्ष्म नियोजन, भावनिक लवचिकता आणि सक्रिय समन्वयाची आवश्यकता असते. हे मार्गदर्शक पालकांना वेळापत्रकानुसार चालण्यास आणि त्यांच्या मुलास प्रभावीपणे मदत करण्यास मदत करते.",
    "Manual confirmation, check-in delays, and coordination gaps at the bedside.": "बेडसाईडवर मॅन्युअल पुष्टीकरण, चेक-इन विलंब आणि समन्वयातील त्रुटी.",
    "Manual Coordination": "मॅन्युअल समन्वय",
