    "No more sporadic donations. No more wondering if your blood made a difference. Become a recurring hero for someone who needs you every 21 days.": "आता तुरळक मतदानाची गरज नाही. तुमच्या रक्ताने काही फरक पडला का, असा विचार करण्याची गरज नाही. दर २१ दिवसांनी तुमची गरज असलेल्या कोणासाठी तरी वारंवार येणारे नायक बना।",
