    "Protecting lives, one match at a time.": "जीव वाचवणे, एका वेळी एक जुळणी.",
    "Protecting lives, one match at a time. Raksha AI is transforming blood donation in India through intelligent matching and care coordination.": "प्रत्येक जुळणीसह जीव वाचवणे. रक्षा AI भारतातील रक्तादान पद्धतीमध्ये बुद्धिमान जुळणी आणि काळजी समन्वयाद्वारे बदल घडवत आहे.",
    "protects.": "संरक्षण करते.",
    "Proximity:": "समीपता:",
    "Questions? We're here to help.": "प्रश्न आहेत? आम्ही मदतीसाठी येथे आहोत.",
    "Radical Transparency": "आमूलाग्र पारदर्शकता",
    "Raksha": "रक्षा",
    "Raksha AI": "रक्षा AI",
    "Raksha AI — Blood Intelligence & Care Coordination for Thalassemia Patients": "रक्षा AI — थॅलेसेमिया रुग्णांसाठी रक्त बुद्धिमत्ता आणि काळजी समन्वय",
    "RAKSHA AI — DONOR INTELLIGENCE": "रक्षा AI — डोनर इंटेलिजेंस",
    "Raksha AI builds a dedicated donor circle around your patient. Smart reminders, compatibility matching, and predictive scheduling.": "रक्षा AI तुमच्या रुग्णासाठी एक समर्पित रक्तदाता वर्तुळ तयार करते. स्मार्ट स्मरणपत्रे, सुसंगतता जुळणी आणि अंदाजपत्रकीय वेळापत्रक.",
    "Raksha AI builds a permanent support system around your patient.": "रक्षा AI तुमच्या रुग्णासाठी एक कायमस्वरूपी आधार प्रणाली तयार करते.",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "रक्षा AI नोंदणीकृत रक्तदात्यांच्या विस्तारित फेनोटाइपिक प्रोफाईलची सूची तयार करते आणि त्यांना रुग्णांच्या प्रोफाईलशी जुळवते. स्थानिक डेटाबेसमध्ये अचूक किंवा अत्यंत सुसंगत अँटीजेन जुळणी शोधून, आम्ही रोगप्रतिकारक प्रतिक्रिया सुरू होण्यापूर्वीच रोखतो, ज्यामुळे सुरक्षित, प्रभावी आणि शाश्वत रक्तसंक्रमण सुनिश्चित होते.",
    "Raksha AI communicates via app, SMS, and WhatsApp — in Hindi, Tamil, Marathi, Bengali, Telugu, and more.": "रक्षा AI ॲप, एसएमएस आणि व्हॉट्सॲपद्वारे हिंदी, तमिळ, मराठी, बंगाली, तेलगू आणि इतर भाषांमध्ये संवाद साधते.",
    "Raksha AI compression: 85% time saved": "रक्षा AI कॉम्प्रेशन: ८५% वेळेची बचत",
    "Raksha AI connects voluntary blood donors with Thalassemia patients across India — through intelligent matching, automated scheduling, and care that never stops.": "रक्षा AI भारतभर थॅलेसेमिया रुग्णांना स्वयंसेवी रक्तदात्यांशी जोडते — बुद्धिमान जुळणी, स्वयंचलित नियोजन आणि सतत काळजी याद्वारे.",
    "Raksha AI considers ABO compatibility, Rh phenotype, Kell antigen status, and alloimmunization history.": "रक्षा AI एबीओ सुसंगतता, आरएच फेनोटाइप, केल प्रतिपिंड स्थिती आणि ॲलोइम्युनायझेशन इतिहास विचारात घेते.",
    "Raksha AI matches you to a specific patient based on blood compatibility, location, and availability.": "रक्ताची सुसंगतता, स्थान आणि उपलब्धता यावर आधारित रक्षा AI तुमची एका विशिष्ट रुग्णाशी जुळणी करते.",
    "Raksha AI v0.1 Launches": "रक्षा AI v0.1 लाँच",
    "Raksha AI was built to be the infrastructure Blood Warriors never had — an intelligent, adaptive, multilingual platform that matches donors to patients.": "ब्लड वॉरियर्सकडे कधीही नसलेली पायाभूत सुविधा म्हणून रक्षा AI ची निर्मिती करण्यात आली — ही रक्तदात्यांना रुग्णांशी जोडणारी एक बुद्धिमान, लवचिक, बहुभाषिक प्रणाली आहे.",
    "Raksha AI was built to eliminate that uncertainty. We match patients with committed donors, predict transfusion needs, and ensure no patient ever faces a shortage alone.": "ती अनिश्चितता दूर करण्यासाठी रक्षा AI ची निर्मिती करण्यात आली. आम्ही रुग्णांना वचनबद्ध दात्यांशी जोडतो, रक्तसंक्रमणाच्या गरजेचा अंदाज लावतो आणि कोणत्याही रुग्णाला कधीही रक्ताच्या टंचाईचा एकट्याने सामना करावा लागणार नाही याची खात्री करतो।",
