    "Twitter": "ट्विटर",
    "Two People. One Mission.": "दोन व्यक्ती. एक ध्येय.",
    "TWO PEOPLE. ONE MISSION.": "दोन व्यक्ती. एक ध्येय.",
    "UNAUTHORIZED CLINICAL ACCESS": "अनधिकृत क्लिनिकल प्रवेश",
    "Understanding Blood Compatibility": "रक्त सुसंगतता समजून घेणे",
    "Units": "युनिट्स",
    "UPCOMING DRIVES": "आगामी ड्राईव्हज",
