    "ALLOANTIBODIES DETECTED": "அலோஆன்டிபாடிகள் கண்டறியப்பட்டன",
    "Alloimmunization occurs when the patient's immune system recognizes minor antigens on the transfused red cells as foreign and produces antibodies against them. Once these antibodies are formed, finding compatible blood becomes extremely difficult. It can lead to acute or delayed hemolytic transfusion reactions, where the body destroys the transfused blood, rendering the treatment ineffective and causing severe clinical complications.": "நோயாளிக்கு ஏற்றப்படும் சிவப்பு இரத்த அணுக்களில் உள்ள சிறிய ஆன்டிஜென்களை நோயாளியின் நோய் எதிர்ப்பு மண்டலம் அந்நியமானவை என அடையாளம் கண்டு, அவற்றுக்கு எதிராக ஆன்டிபாடிகளை உருவாக்கும்போது 'அலோஇம்யூனைசேஷன்' (Alloimmunization) ஏற்படுகிறது. இந்த ஆன்டிபாடிகள் உருவானவுடன், பொருத்தமான இரத்தத்தைக் கண்டறிவது மிகவும் கடினமாகிறது. இது தீவிரமான அல்லது தாமதமான ஹீமோலிடிக் இரத்தமாற்ற எதிர்வினைகளுக்கு வழிவகுக்கும், இதில் உடல் ஏற்றப்பட்ட இரத்தத்தை அழித்துவிடுகிறது, இதனால் சிகிச்சை பலனளிக்காமல் போகிறது மற்றும் கடுமையான மருத்துவ சிக்கல்களை ஏற்படுத்துகிறது.",
    "Alloimmunization risk prediction model": "அலோஇம்யூனைசேஷன் அபாயத்தைக் கணிக்கும் மாதிரி",
    "Alloimmunization: The Hidden Risk in Unmatched Transfusions": "அலோஇம்யூனைசேஷன்: பொருந்தாத இரத்தமாற்றங்களில் மறைந்திருக்கும் ஆபத்து",
