    "Donors who are currently eligible (exceeded the 90-day donation interval) and ready for matching.": "தற்போது தகுதியுடையவர்கள் (90 நாள் கொடை இடைவெளியை தாண்டியவர்கள்) மற்றும் பொருத்துதலுக்கு தயாராக இருப்பவர்கள்.",
