    "Have questions about blood donation? We've compiled the most common questions from first-time and recurring donors to help you understand the process and your impact.": "இரத்த தானம் பற்றி கேள்விகள் உள்ளதா? முதல்முறை மற்றும் வழக்கமாக இரத்த தானம் செய்பவர்களிடம் கேட்கப்படும் பொதுவான கேள்விகளைத் தொகுத்துள்ளோம், இது செயல்முறையை மற்றும் உங்கள் பங்களிப்பை புரிந்துகொள்ள உதவும்.",
