    "Healthy male donors can donate whole blood every 90 days (3 months), and female donors can donate every 120 days (4 months). This interval ensures that your body has fully replenished its red blood cells and iron stores before your next donation.": "ஆரோக்கியமான ஆண் கொடையாளர்கள் ஒவ்வொரு 90 நாட்களுக்கும் (3 மாதங்கள்) மற்றும் பெண் கொடையாளர்கள் ஒவ்வொரு 120 நாட்களுக்கும் (4 மாதங்கள்) ஒருமுறை இரத்த தானம் செய்யலாம். இந்த இடைவெளி உங்கள் அடுத்த இரத்த தானத்திற்கு முன்பு, உங்கள் உடல் சிவப்பு இரத்த அணுக்கள் மற்றும் இரும்புச் சத்துகளை முழுமையாக மீண்டும் பெற்றுக்கொள்வதை உறுதி செய்கிறது.",
    "Help us ensure you're eligible and understand when you can donate.": "நீங்கள் தகுதியுடையவரா என்பதை உறுதிப்படுத்தவும், நீங்கள் எப்போது தானம் செய்யலாம் என்பதைப் புரிந்துகொள்ளவும் எங்களுக்கு உதவுங்கள்.",
