    "Hyperhemolysis Syndrome:": "ஹைப்பர்ஹீமோலிசிஸ் நோய்க்குறி:",
    "I am the patient, parent, or legal guardian authorised to provide this information.": "இந்தத் தகவலை வழங்க அங்கீகரிக்கப்பட்ட நோயாளி, பெற்றோர் அல்லது சட்டப்பூர்வ பாதுகாவலர் நான்.",
    "I consent to Raksha AI storing and processing this patient": "இந்த நோயாளியின் தகவலைச் சேமிக்கவும் செயலாக்கவும் Raksha AI-க்கு நான் ஒப்புதல் அளிக்கிறேன்",
    "I consent to Raksha AI storing and using this information to coordinate blood donation.": "இரத்த தானத்தை ஒருங்கிணைக்க ரக்ஷா AI இந்தத் தகவலைச் சேமிப்பதற்கும் பயன்படுத்துவதற்கும் நான் ஒப்புக்கொள்கிறேன்.",
    "I Want to Donate Blood": "நான் இரத்த தானம் செய்ய விரும்புகிறேன்",
    "Identify inactive donors or deferred status updates that require care coordinator intervention.": "பராமரிப்பு ஒருங்கிணைப்பாளரின் தலையீடு தேவைப்படும் செயலற்ற நன்கொடையாளர்கள் அல்லது தாமதமான நிலை புதுப்பிப்புகளை அடையாளம் காணவும்.",
    "If you receive mutated genes from both parents, you have thalassemia major (Transfusion-Dependent Thalassemia). Symptoms usually appear within the first two years of life, causing severe anemia, fatigue, pale skin, and slow growth.": "உங்களுக்கு இரண்டு பெற்றோரிடமிருந்தும் பிறழ்ந்த மரபணுக்கள் வந்தால், உங்களுக்கு தலசீமியா மேஜர் (ரத்தமாற்றம்-சார்ந்த தலசீமியா) உள்ளது. அறிகுறிகள் பொதுவாக வாழ்வின் முதல் இரண்டு ஆண்டுகளுக்குள் தோன்றும், கடுமையான இரத்த சோகை, சோர்வு, வெளிறிய தோல் மற்றும் மெதுவான வளர்ச்சியை ஏற்படுத்தும்.",
    "If you receive only one mutated gene from one parent, you have thalassemia minor. Carriers usually have no symptoms or very mild anemia and do not require treatment.": "உங்களுக்கு ஒரு பெற்றோர் அல்லது ஒரே ஒரு பெற்றோரிடமிருந்து பிறழ்ந்த மரபணு வந்தால், உங்களுக்கு தலசீமியா மைனர் உள்ளது. கடத்திகள் பொதுவாக அறிகுறிகள் இல்லாமல் அல்லது மிக லேசான இரத்த சோகையுடன் இருப்பார்கள், மேலும் சிகிச்சையும் தேவையில்லை.",
    "Impact": "தாக்கம்",
    "Impact Dashboard": "தாக்க டாஷ்போர்டு",
    "Impact So Far": "இதுவரை தாக்கம்",
    "Impact Stories": "தாக்கக் கதைகள்",
    "In India alone, over 1 lakh children are born with Thalassemia Major every year. Each patient needs 500-700 transfusions over their lifetime. That's not just 500 blood bags — it's 500 moments of uncertainty, coordination, and hope.": "இந்தியாவில் மட்டும் ஒவ்வொரு ஆண்டும் 1 லட்சத்திற்கும் அதிகமான குழந்தைகள் தலசீமியா மேஜருடன் பிறக்கின்றனர். ஒவ்வொரு நோயாளிக்கும் அவர்களின் வாழ்நாளில் 500-700 இரத்தமாற்றங்கள் தேவைப்படுகின்றன. அது வெறும் 500 இரத்தப் பைகள் மட்டுமல்ல — அது நிச்சயமற்ற தன்மை, ஒருங்கிணைப்பு மற்றும் நம்பிக்கையின் 500 தருணங்கள்.",
