    "Instant screening based on ABO/Rh history, location, and alloimmunization risk.": "ABO/Rh வரலாறு, இருப்பிடம் மற்றும் அல்லோஇம்யூனைசேஷன் அபாயத்தின் அடிப்படையில் உடனடி ஸ்கிரீனிங்.",
    "Interactive Directory Section": "ஊடாடும் அடைவுப் பிரிவு",
