    "It wasn't a statistic. It was a name. A face. A mother who spent 6 hours on the phone.": "அது ஒரு புள்ளிவிவரம் அல்ல. அது ஒரு பெயர். ஒரு முகம். தொலைபேசியில் 6 மணி நேரம் அழுத ஒரு தாய்.",
    "Join the Mission": "பணியில் சேருங்கள்",
    "Join the network of heroes who show up — not once, but every time. Your blood type could be someone's lifeline.": "ஒரு முறை அல்ல, ஒவ்வொரு முறையும் கை கொடுக்கும் ஹீரோக்களின் நெட்வொர்க்கில் இணையுங்கள். உங்கள் இரத்த வகை ஒருவரின் உயிர்நாடியாக இருக்கலாம்.",
