    "Morning (6am–12pm)": "காலை (6am–12pm)",
    "Most blood donation platforms treat every donation as a one-time transaction. For Thalassemia patients, that model is dangerous. Here's why recurring, compatible donation is a medical necessity.": "பெரும்பாலான இரத்த தான தளங்கள் ஒவ்வொரு தானத்தையும் ஒரு முறை பரிவர்த்தனையாகக் கருதுகின்றன. தலசீமியா நோயாளிகளுக்கு, அந்த மாதிரி ஆபத்தானது. தொடர்ச்சியான, இணக்கமான தானம் ஏன் ஒரு மருத்துவத் தேவை என்பதை இங்கே காண்பிக்கிறோம்.",
    "Most donors feel fine after donation. Some may experience mild lightheadedness, which quickly resolves after resting for 10-15 minutes and having a light snack and water. We recommend avoiding strenuous physical activity or heavy lifting for the rest of the day.": "பெரும்பாலான கொடையாளர்கள் தானம் செய்த பிறகு நன்றாக உணர்கிறார்கள். சிலர் லேசான தலைச்சுற்றலை அனுபவிக்கலாம், இது 10-15 நிமிடங்கள் ஓய்வெடுத்த பிறகு மற்றும் லேசான சிற்றுண்டி மற்றும் தண்ணீர் குடித்த பிறகு விரைவில் சரியாகிவிடும். அன்றைய தினம் கடினமான உடல் செயல்பாடுகள் அல்லது கனமான பொருட்களை தூக்குவதைத் தவிர்க்க நாங்கள் பரிந்துரைக்கிறோம்.",
