    "No more sporadic donations. No more wondering if your blood made a difference. Become a recurring hero for someone who needs you every 21 days.": "இனி எப்போதாவது இரத்தம் கொடுப்பது இல்லை. உங்கள் இரத்தம் மாற்றத்தை ஏற்படுத்தியதா என்று யோசிக்கத் தேவையல்லை. ஒவ்வொரு 21 நாட்களுக்கும் உங்களை எதிர்பார்க்கும் ஒருவருக்கு தொடர்ச்சியான ஹீரோவாக மாறுங்கள்.",
