    "Patients with Thalassemia Major require lifelong medical care, including regular blood transfusions (every few weeks) to maintain healthy hemoglobin levels, combined with iron chelation therapy to remove excess iron from the body. For some patients, a bone marrow transplant can offer a permanent cure.": "தலசீமியா மேஜர் உள்ள நோயாளிகளுக்கு, ஆரோக்கியமான ஹீமோகுளோபின் அளவைப் பராமரிக்க வழக்கமான இரத்தமாற்றங்கள் (சில வாரங்களுக்கு ஒருமுறை) மற்றும் உடலில் இருந்து அதிகப்படியான இரும்பை அகற்ற இரும்பு செலேஷன் சிகிச்சை உள்ளிட்ட வாழ்நாள் முழுவதும் மருத்துவ பராமரிப்பு தேவைப்படுகிறது. சில நோயாளிகளுக்கு, எலும்பு மஜ்ஜை மாற்று அறுவை சிகிச்சை நிரந்தரமான குணத்தை அளிக்கக்கூடும்.",
