    "Protecting lives, one match at a time.": "உயிர்களைக் காப்போம், ஒரு நேரத்தில் ஒரு பொருத்தம்.",
    "Protecting lives, one match at a time. Raksha AI is transforming blood donation in India through intelligent matching and care coordination.": "ஒவ்வொரு பொருத்தத்தின் மூலமும் உயிர்களைக் காக்கிறது. ரக்ஷா AI இந்தியாவில் இரத்த தானத்தை ஒருங்கிணைப்பு மூலம் மாற்றியமைக்கிறது.",
    "protects.": "பாதுகாக்கிறது.",
    "Proximity:": "அருகாமை:",
    "Questions? We're here to help.": "கேள்விகள் உள்ளதா? உங்களுக்கு உதவ நாங்கள் இங்கே இருக்கிறோம்.",
    "Radical Transparency": "தீவிர வெளிப்படைத்தன்மை",
    "Raksha": "ரக்ஷா",
    "Raksha AI": "ரக்ஷா AI",
    "Raksha AI — Blood Intelligence & Care Coordination for Thalassemia Patients": "Raksha AI — தலசீமியா நோயாளிகளுக்கான இரத்த நுண்ணறிவு & பராமரிப்பு ஒருங்கிணைப்பு",
    "RAKSHA AI — DONOR INTELLIGENCE": "ரக்ஷா AI — நன்கொடையாளர் நுண்ணறிவு",
    "Raksha AI builds a dedicated donor circle around your patient. Smart reminders, compatibility matching, and predictive scheduling.": "ரக்ஷா AI உங்கள் நோயாளிக்காக அர்ப்பணிக்கப்பட்ட தானியாளர் வட்டத்தை உருவாக்குகிறது. ஸ்மார்ட் நினைவூட்டல்கள், இணக்கத்தன்மை பொருத்தம் மற்றும் முன்கணிப்பு திட்டமிடல்.",
    "Raksha AI builds a permanent support system around your patient.": "ரக்ஷா AI உங்கள் நோயாளியைச் சுற்றி ஒரு நிரந்தர ஆதரவு அமைப்பை உருவாக்குகிறது.",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "ரக்ஷா AI பதிவுசெய்யப்பட்ட நன்கொடையாளர்களின் விரிவான பினோடைபிகல் சுயவிவரங்களை அட்டவணைப்படுத்துகிறது மற்றும் நோயாளியின் சுயவிவரங்களுடன் அவற்றை ஒப்பிடுகிறது. உள்ளூர் தரவுத்தளங்களில் துல்லியமான அல்லது மிகவும் இணக்கமான ஆன்டிஜென் பொருத்தங்களைக் கண்டறிவதன் மூலம், நோயெதிர்ப்பு எதிர்வினைகளைத் தொடங்குவதற்கு முன்பே நாங்கள் தடுக்கிறோம், பாதுகாப்பான, பயனுள்ள மற்றும் நிலையான இரத்தமாற்றங்களை உறுதிசெய்கிறோம்.",
    "Raksha AI communicates via app, SMS, and WhatsApp — in Hindi, Tamil, Marathi, Bengali, Telugu, and more.": "ரக்ஷா AI ஆப், எஸ்எம்எஸ் மற்றும் வாட்ஸ்அப் மூலம் இந்தி, தமிழ், மராத்தி, பெங்காலி, தெலுங்கு மற்றும் பல மொழிகளில் தொடர்பு கொள்கிறது.",
    "Raksha AI compression: 85% time saved": "ரக்ஷா AI சுருக்கம்: 85% நேரம் மிச்சமானது",
    "Raksha AI connects voluntary blood donors with Thalassemia patients across India — through intelligent matching, automated scheduling, and care that never stops.": "ரக்ஷா AI இந்தியா முழுவதும் தலசீமியா நோயாளிகளை தன்னார்வ இரத்த தானியாளர்களுடன் இணைக்கிறது — புத்திசாலித்தனமான பொருத்தம், தானியங்கி திட்டமிடல் மற்றும் தொடர்ச்சியான கவனிப்பு மூலம்.",
    "Raksha AI considers ABO compatibility, Rh phenotype, Kell antigen status, and alloimmunization history.": "ரக்ஷா AI ஆனது ABO இணக்கத்தன்மை, Rh பினோடைப், கெல் ஆன்டிஜென் நிலை மற்றும் அலோ இம்யூனிசேஷன் வரலாறு ஆகியவற்றைக் கருதுகிறது.",
    "Raksha AI matches you to a specific patient based on blood compatibility, location, and availability.": "இரத்தப் பொருத்தம், இருப்பிடம் மற்றும் கிடைக்கும் தன்மை ஆகியவற்றின் அடிப்படையில் ரக்ஷா AI உங்களை ஒரு குறிப்பிட்ட நோயாளிக்கு பொருத்துகிறது.",
    "Raksha AI v0.1 Launches": "ரக்ஷா AI v0.1 அறிமுகம்",
    "Raksha AI was built to be the infrastructure Blood Warriors never had — an intelligent, adaptive, multilingual platform that matches donors to patients.": "பிளட் வாரியர்ஸ் அமைப்பிற்கு இதுவரை இல்லாத ஒரு மும்முனை உள்கட்டமைப்பாக இருக்கவே ரக்ஷா AI உருவாக்கப்பட்டது — இது தானியாளர்களை நோயாளிகளுடன் இணைக்கும் ஒரு புத்திசாலித்தனமான, மாற்றியமைக்கக்கூடிய, பன்மொழி தளமாகும்.",
    "Raksha AI was built to eliminate that uncertainty. We match patients with committed donors, predict transfusion needs, and ensure no patient ever faces a shortage alone.": "அந்த நிச்சயமற்ற தன்மையை போக்கவே ரக்ஷா AI உருவாக்கப்பட்டது. நோயாளிகளை அர்ப்பணிப்புள்ள தானியாளர்களுடன் ஒப்பிடுகிறோம், இரத்தமாற்றத் தேவைகளை கணிப்போம், மேலும் எந்தவொரு நோயாளியும் ஒருபோதும் பற்றாக்குறையை தனியாக enfrentar செய்யாமல் இருப்பதை உறுதிசெய்கிறோம்.",
