    "Scroll down to see how patient families coordinate care with Raksha AI": "ரக்ஷா AI (Raksha AI) மூலம் நோயாளிகளின் குடும்பத்தினர் எவ்வாறு சிகிச்சையை ஒருங்கிணைக்கிறார்கள் என்பதைக் காண கீழே உருட்டவும்",
