    "Smarter matching. Proactive scheduling. Zero guesswork.": "புத்திசாலித்தனமான பொருத்தம். முன்கூட்டியே திட்டமிடல். யூகம் எதுவும் தேவையில்லை.",
    "SMS alerts for upcoming transfusions": "வரவிருக்கும் இரத்தமாற்றங்களுக்கான SMS விழிப்பூட்டல்கள்",
    "SNS outreach to top 3 donors": "முதல் 3 நன்கொடையாளர்களுக்கான SNS அவுட்ரீச்",
    "Social media": "சமூக ஊடகம்",
    "Something went wrong. Please try again.": "ஏதோ தவறு நடந்துவிட்டது. தயவுசெய்து மீண்டும் முயற்சிக்கவும்.",
