    "YOUR BADGE COLLECTION": "உங்கள் பேட்ஜ் சேகரிப்பு",
    "Your blood has": "உங்கள் இரத்தத்தில் உள்ளது",
    "Your child's next transfusion is already being arranged.": "உங்கள் குழந்தையின் அடுத்த இரத்தமாற்றத்திற்கான ஏற்பாடுகள் ஏற்கனவே செய்யப்பட்டு வருகின்றன.",
    "Your child's next transfusion is already scheduled. Not because you spent all night calling numbers, but because Raksha AI coordinates the schedule. We build a donor circle of 5 committed donors specifically matched to your child.": "உங்கள் குழந்தையின் அடுத்த இரத்தமாற்றம் ஏற்கனவே திட்டமிடப்பட்டுள்ளது. நீங்கள் இரவு முழுவதும் எண்களை அழைத்ததால் அல்ல, ரக்ஷா AI இந்த அட்டவணையை ஒருங்கிணைப்பதால். உங்கள் குழந்தைக்கு குறிப்பாகப் பொருந்தக்கூடிய 5 அர்ப்பணிப்புள்ள தானியாளர்களைக் கொண்ட தானியாளர் வட்டத்தை நாங்கள் உருவாக்குகிறோம்.",
    "your child&apos;s circle": "உங்கள் குழந்தையின் வட்டம்",
    "Your circle of donors and caregivers will receive coordinated alerts — so nobody misses a critical transfusion.": "உங்கள் இரத்த தானம் செய்பவர்கள் மற்றும் பராமரிப்பாளர்கள் ஒருங்கிணைந்த எச்சரிக்கைகளைப் பெறுவார்கள் — அதனால் யாரும் முக்கியமான இரத்த மாற்றத்தைத் தவறவிட மாட்டார்கள்.",
