    ". Next expected drop to threshold in ~": ". থ্রেশহোল্ডে পরবর্তী প্রত্যাশিত পতন ~",
    ". Pre-emptive scheduling reduces risk by": ". পূর্ব-প্রস্তুতিমূলক সময়সূচী ঝুঁকি কমায়",
    ". Trough reached at day ~": ". দিন ~ এ সর্বনিম্ন স্তরে পৌঁছেছে",
    "\"I donated for the first time last year. Raksha matched me in 22 minutes. The family called me. I cried.\"": "\"আমি গত বছর প্রথমবার রক্তদান করেছিলাম। রক্ষা আমাকে ২২ মিনিটের মধ্যে খুঁজে দিয়েছিল। পরিবার আমাকে ডেকেছিল। আমি কেঁদেছিলাম।\"",
    "\"We did not build Raksha to be a startup. We built it because the alternative was watching children die waiting for a phone call that never came.\"": "\"আমরা রক্ষা-কে একটি স্টার্টআপ হিসেবে তৈরি করিনি। আমরা এটি তৈরি করেছি কারণ বিকল্পটি ছিল ফোন কলের অপেক্ষায় থাকা শিশুদের মৃত্যু দেখা, যা কখনও আসেনি।\"",
    "“When you save a life every 21 days, you don't just become a donor. You become family.”": "“আপনি যখন প্রতি ২১ দিনে একটি জীবন বাঁচান, আপনি কেবল একজন দাতাই থাকেন না। আপনি পরিবারের একজন হয়ে যান।”",
    "••••••••••••": "••••••••••••",
    "© 2025 Blood Warriors Foundation. Built for patients, powered by community.": "© 2025 ব্লাড ওয়ারিয়র্স ফাউন্ডেশন। রোগীদের জন্য নির্মিত, সম্প্রদায় দ্বারা চালিত।",
