    "Blood Warriors": "ব্লাড ওয়ারিয়র্স",
    "BLOOD WARRIORS × RAKSHA AI": "ব্লাড ওয়ারিয়র্স × রক্ষা AI",
    "Blood Warriors Foundation": "ব্লাড ওয়ারিয়র্স ফাউন্ডেশন",
    "Blood Warriors Foundation has spent years building a donor community and Blood Bridge network across India. But the matching is manual. The engagement fades. The coordination is fragile.": "ব্লাড ওয়ারিয়র্স ফাউন্ডেশন ভারতজুড়ে রক্তদাতা সম্প্রদায় এবং ব্লাড ব্রিজ নেটওয়ার্ক গড়ে তুলতে বছরের পর বছর সময় ব্যয় করেছে। কিন্তু মিল নির্ধারণের কাজ সম্পূর্ণ ম্যানুয়াল। সম্পৃক্ততা ক্রমশ হ্রাস পায়। সমন্বয় প্রক্রিয়া দুর্বল।",
    "Blood Warriors Foundation, Mumbai, India": "ব্লাড ওয়ারিয়র্স ফাউন্ডেশন, মুম্বাই, ভারত",
    "Blood Warriors Founded": "ব্লাড ওয়ারিয়র্স প্রতিষ্ঠিত",
    "blood_requests": "blood_requests",
    "Bone Marrow Transplant": "বোন ম্যারো ট্রান্সপ্ল্যান্ট (অস্থিমজ্জা প্রতিস্থাপন)",
    "Breached": "লঙ্ঘিত",
    "Bridge Match": "ব্রিজ ম্যাচ",
    "Bridge Reliability:": "ব্রিজ নির্ভরযোগ্যতা:",
    "Bridges": "ব্রিজেস",
    "Bridges pair chronic transfusion patients with recurring, antigen-compatible donors.": "ব্রিজেস দীর্ঘস্থায়ী রক্ত সঞ্চালন রোগীদের নিয়মিত, অ্যান্টিজেন-সামঞ্জস্যপূর্ণ দাতাদের সাথে যুক্ত করে।",
    "Broadcasting SLA breach details...": "SLA লঙ্ঘনের বিবরণ সম্প্রচার করা হচ্ছে...",
    "BROWSE BY TOPIC": "বিষয়ভিত্তিক ব্রাউজ করুন",
    "Build your care network": "আপনার কেয়ার নেটওয়ার্ক তৈরি করুন",
    "By pairing a patient with a small, dedicated pool of recurring donors who have matching minor antigens (Rh phenotype, Kell, etc.), we can minimize the variety of foreign antigens the patient's immune system encounters. This dramatically reduces the risk of alloimmunization, ensures the longevity of transfused cells, and protects the patient from life-threatening immune responses.": "একজন রোগীকে অল্প কিছু নিয়মিত রক্তদাতার সাথে যুক্ত করে যাদের মাইনর অ্যান্টিজেন (Rh ফিনোটাইপ, কেল ইত্যাদি) মিল আছে, আমরা রোগীর ইমিউন সিস্টেমের সম্মুখীন হওয়া বহিরাগত অ্যান্টিজেনের বৈচিত্র্য কমিয়ে আনতে পারি। এটি অ্যালোইমিউনাইজেশনের ঝুঁকি নাটকীয়ভাবে কমায়, সঞ্চালিত কোষগুলোর দীর্ঘায়ু নিশ্চিত করে এবং রোগীকে জীবনঘাতী ইমিউন প্রতিক্রিয়া থেকে রক্ষা করে।",
    "By the time she is 18, she will need 210 more transfusions.": "১৮ বছর বয়স হওয়ার মধ্যে তার আরও ২১০ বার রক্ত সঞ্চালনের প্রয়োজন হবে।",
    "Calendar": "ক্যালেন্ডার",
    "Calling Inactive Lists (~120 mins)": "নিষ্ক্রিয় তালিকাগুলোতে কল করা হচ্ছে (~১২০ মিনিট)",
    "Can cause fever, chills, jaundice, renal failure, and severe chest or back pain.": "এর ফলে জ্বর, কাঁপুনি, জন্ডিস, কিডনি ফেইলিউর এবং বুকে বা পিঠে তীব্র ব্যথা হতে পারে।",
