    "Cardiac complications": "হৃদরোগ সংক্রান্ত জটিলতা",
    "Care Memory": "কেয়ার মেমোরি",
    "CARE MEMORY": "কেয়ার মেমোরি",
    "Careers": "ক্যারিয়ার",
    "Channel:": "চ্যানেল:",
    "Chat Sessions Table": "চ্যাট সেশন টেবিল",
    "chat_sessions": "chat_sessions",
    "Chelation therapy uses specialized medications (chelators) that bind to free iron in the bloodstream and tissues, allowing it to be excreted safely through urine or stool. The three commonly used chelators are Deferasirox (oral tablets), Deferiprone (oral liquid or tablets), and Desferrioxamine (subcutaneous infusion via a pump).": "চিলেশন থেরাপিতে বিশেষ ওষুধ (চিলেটর) ব্যবহার করা হয় যা রক্তপ্রবাহ এবং টিস্যুতে থাকা মুক্ত আয়রনের সাথে আবদ্ধ হয়, ফলে এটি প্রস্রাব বা মলের মাধ্যমে নিরাপদে নির্গত হতে পারে। সাধারণত ব্যবহৃত তিনটি চিলেটর হলো ডিফেরাসিরক্স (ওরাল ট্যাবলেট), ডিফেরিপ্লোন (ওরাল লিকুইড বা ট্যাবলেট) এবং ডেসফেরিওক্সামিন (পাম্পের মাধ্যমে সাবকিউটেনিয়াস ইনফিউশন)।",
    "Children with Thalassemia can participate in physical education, but teachers should allow them to rest when fatigued. Because their oxygen-carrying capacity is lower, especially in the week leading up to a transfusion, they may need frequent breaks. Proper hydration during school hours is also essential to manage fatigue.": "থ্যালাসেমিয়া আক্রান্ত শিশুরা শারীরিক শিক্ষায় অংশগ্রহণ করতে পারে, তবে ক্লান্ত হলে শিক্ষকদের উচিত তাদের বিশ্রাম নিতে দেওয়া। যেহেতু তাদের অক্সিজেন বহন করার ক্ষমতা কম থাকে, বিশেষ করে রক্ত সঞ্চালনের আগের সপ্তাহে, তাই তাদের ঘন ঘন বিরতির প্রয়োজন হতে পারে। ক্লান্তি দূর করতে স্কুলের সময় পর্যাপ্ত জল পান করাও জরুরি।",
    "Children with Transfusion-Dependent Thalassemia can and should participate fully in school life. Simple adjustments, open communication, and supportive peer environments make all the difference.": "রক্ত সঞ্চালনের ওপর নির্ভরশীল থ্যালাসেমিয়া আক্রান্ত শিশুরা স্কুল জীবনে পুরোপুরি অংশগ্রহণ করতে পারে এবং করা উচিত। সামান্য সমন্বয়, খোলামেলা যোগাযোগ এবং সহমর্মী সহপাঠী পরিবেশ সবকিছু বদলে দিতে পারে।",
    "Chronic blood transfusions introduce massive amounts of iron into the patient’s body. Because the human body lacks a natural mechanism to excrete excess iron, it accumulates in vital organs, requiring proactive chelation therapy.": "দীর্ঘদিন ধরে রক্ত সঞ্চালনের ফলে রোগীর শরীরে প্রচুর পরিমাণে আয়রন জমা হয়। যেহেতু মানুষের শরীরে অতিরিক্ত আয়রন বের করে দেওয়ার কোনো প্রাকৃতিক ব্যবস্থা নেই, তাই এটি গুরুত্বপূর্ণ অঙ্গগুলোতে জমা হতে থাকে, যার জন্য নিয়মিত চিলেশন থেরাপি প্রয়োজন।",
