    "Each time a patient receives blood with incompatible minor antigens, their immune system builds resistance. Over hundreds of transfusions, this becomes life-threatening.": "প্রতিবার যখন একজন রোগী বেমানান মাইনর অ্যান্টিজেন যুক্ত রক্ত গ্রহণ করেন, তখন তাদের ইমিউন সিস্টেম প্রতিরোধ ক্ষমতা গড়ে তোলে। শত শত ট্রান্সফিউশনের পর, এটি জীবনহুমকির কারণ হয়ে দাঁড়ায়।",
    "Each unit of transfused red blood cells contains approximately 200 mg of iron. Over a year of monthly transfusions, this amounts to a significant iron burden. If left untreated, the excess iron deposits in the liver, heart, and endocrine glands, leading to organ failure, heart disease, diabetes, and stunted growth.": "ট্রান্সফিউজ করা লোহিত রক্তকণিকার প্রতিটি ইউনিটে প্রায় ২০০ মিলিগ্রাম আয়রন থাকে। এক বছর ধরে মাসিক ট্রান্সফিউশনের ফলে, এটি আয়রনের একটি উল্লেখযোগ্য বোঝা তৈরি করে। যদি চিকিৎসা না করা হয়, তবে অতিরিক্ত আয়রন লিভার, হার্ট এবং এন্ডোক্রাইন গ্রন্থিতে জমা হয়ে অঙ্গ অকার্যকর হওয়া, হৃদরোগ, ডায়াবেটিস এবং শারীরিক বৃদ্ধি ব্যাহত হওয়ার মতো সমস্যার সৃষ্টি করে।",
