    "Every drop counts. Every match matters.": "প্রতিটি ফোঁটা মূল্যবান। প্রতিটি মিল গুরুত্বপূর্ণ।",
    "Every number below is a real, documented medical outcome.": "নীচের প্রতিটি সংখ্যা একটি বাস্তব, নথিভুক্ত চিকিৎসা ফলাফল।",
    "Every Thalassemia patient deserves a donor who keeps coming back.": "প্রতিটি থ্যালাসেমিয়া রোগী এমন একজন দাতার দাবিদার যিনি বারবার ফিরে আসেন।",
    "Everything you need to understand Thalassemia, blood compatibility, and what it means to be a donor or a family.": "থ্যালাসেমিয়া, রক্তের সামঞ্জস্যতা এবং একজন দাতা বা পরিবারের সদস্য হওয়ার অর্থ বোঝার জন্য আপনার যা কিছু প্রয়োজন।",
    "Executing live routing. Please keep this overlay open...": "লাইভ রাউটিং কার্যকর করা হচ্ছে। অনুগ্রহ করে এই ওভারলেটি খোলা রাখুন...",
    "Execution Console Logs": "এক্সিকিউশন কনসোল লগ",
    "Expand donor radius": "দাতার ব্যাসার্ধ বাড়ান",
    "Extended Antigen Profile": "বর্ধিত অ্যান্টিজেন প্রোফাইল",
    "Extended phenotyping involves checking for minor antigens in other blood group systems, particularly the Rh subgroups (C, c, E, e) and the Kell system (K, k). Matching these antigens between the donor and recipient reduces the probability of the patient developing antibodies (alloimmunization) by more than 80%.": "বর্ধিত ফেনোটাইপিং-এর মধ্যে অন্যান্য রক্ত গ্রুপ সিস্টেমের ছোট অ্যান্টিজেনগুলি পরীক্ষা করা অন্তর্ভুক্ত, বিশেষ করে আরএইচ (Rh) উপগোষ্ঠী (C, c, E, e) এবং কেল সিস্টেম (K, k)। দাতা এবং গ্রহীতার মধ্যে এই অ্যান্টিজেনগুলির মিল থাকলে রোগীর অ্যান্টিবডি তৈরির (অ্যালোইমিউনাইজেশন) সম্ভাবনা ৮০%-এর বেশি কমে যায়।",
    "Extended Typing": "বর্ধিত টাইপিং",
    "Extended typing goes beyond standard ABO/Rh blood groups to check for minor antigens on your red blood cells (like Rh subgroups C, c, E, e and the Kell system). For Thalassemia patients who receive chronic transfusions, matching these minor antigens is critical to prevent alloimmunization and ensure transfusion safety.": "বর্ধিত টাইপিং আপনার লোহিত রক্তকণিকায় থাকা ছোট অ্যান্টিজেনগুলি (যেমন Rh উপগোষ্ঠী C, c, E, e এবং কেল সিস্টেম) পরীক্ষা করতে সাধারণ ABO/Rh রক্ত গ্রুপের ঊর্ধ্বে যায়। থ্যালাসেমিয়া রোগীদের জন্য যারা নিয়মিত রক্ত গ্রহণ করেন, অ্যালোইমিউনাইজেশন প্রতিরোধ করতে এবং রক্ত পরিবর্তনের নিরাপত্তা নিশ্চিত করতে এই ছোট অ্যান্টিজেনগুলির মিল থাকা অত্যন্ত গুরুত্বপূর্ণ।",
    "Failure Learning Loop": "ব্যর্থতা শেখার লুপ",
    "FAILURE LEARNING LOOP": "ব্যর্থতা শেখার লুপ",
    "Families spend hours on phone calls, WhatsApp groups, and hospital queues — hoping someone will show up. It's not a donor shortage. It's a coordination crisis.": "পরিবারগুলো ঘণ্টার পর ঘণ্টা ফোন কল, হোয়াটসঅ্যাপ গ্রুপ এবং হাসপাতালের লাইনে ব্যয় করে — এই আশায় যে কেউ একজন আসবে। এটি দাতার ঘাটতি নয়। এটি সমন্বয়ের সংকট।",
