    "Finding compatible blood becomes a search for a needle in a haystack, causing critical delays in treatment.": "উপযুক্ত রক্ত ​​খুঁজে বের করা খড়ের গাদায় সুঁচ খোঁজার মতো হয়ে যায়, যা চিকিৎসায় গুরুতর বিলম্ব ঘটায়।",
