    "Have questions about blood donation? We've compiled the most common questions from first-time and recurring donors to help you understand the process and your impact.": "রক্তদান সম্পর্কে প্রশ্ন আছে? প্রথমবার এবং নিয়মিত রক্তদাতাদের কাছ থেকে সবচেয়ে সাধারণ প্রশ্নগুলো আমরা সংকলন করেছি, যাতে আপনি প্রক্রিয়াটি এবং আপনার প্রভাব বুঝতে পারেন।",
    "Hb After": "Hb-এর পরে",
    "Hb Before": "Hb-এর আগে",
    "Health Insights": "স্বাস্থ্য সংক্রান্ত অন্তর্দৃষ্টি",
    "Health Tracker": "হেলথ ট্র্যাকার",
    "Healthy male donors can donate whole blood every 90 days (3 months), and female donors can donate every 120 days (4 months). This interval ensures that your body has fully replenished its red blood cells and iron stores before your next donation.": "সুস্থ পুরুষ দাতা প্রতি ৯০ দিনে (৩ মাস) এবং নারী দাতা প্রতি ১২০ দিনে (৪ মাস) রক্তদান করতে পারেন। এই বিরতি নিশ্চিত করে যে আপনার পরবর্তী রক্তদানের আগে আপনার শরীরে লোহিত রক্তকণিকা এবং আয়রনের মাত্রা সম্পূর্ণরূপে পুনরুদ্ধার হয়েছে।",
    "Help us ensure you're eligible and understand when you can donate.": "আপনি যোগ্য কিনা তা নিশ্চিত করতে এবং আপনি কখন দান করতে পারেন তা বুঝতে আমাদের সাহায্য করুন।",
