    "I am the patient, parent, or legal guardian authorised to provide this information.": "আমি একজন রোগী, অভিভাবক বা আইনি অভিভাবক যে এই তথ্য প্রদানের জন্য অনুমোদিত।",
    "I consent to Raksha AI storing and processing this patient": "আমি এই রোগীর তথ্য সংরক্ষণ এবং প্রক্রিয়াকরণ করতে Raksha AI-কে সম্মতি দিচ্ছি",
    "I consent to Raksha AI storing and using this information to coordinate blood donation.": "আমি রক্তদানের সমন্বয় সাধনের জন্য রক্ষা AI-কে এই তথ্য সংরক্ষণ ও ব্যবহার করার অনুমতি দিচ্ছি।",
    "I Want to Donate Blood": "আমি রক্তদান করতে চাই",
    "Identify inactive donors or deferred status updates that require care coordinator intervention.": "নিষ্ক্রিয় দাতাদের বা স্থগিত স্ট্যাটাস আপডেটগুলি সনাক্ত করুন যেগুলির জন্য কেয়ার কোঅর্ডিনেটরের হস্তক্ষেপ প্রয়োজন।",
    "If you receive mutated genes from both parents, you have thalassemia major (Transfusion-Dependent Thalassemia). Symptoms usually appear within the first two years of life, causing severe anemia, fatigue, pale skin, and slow growth.": "যদি আপনি উভয় পিতামাতার কাছ থেকে পরিবর্তিত জিন পান, তবে আপনার থ্যালাসেমিয়া মেজর (ট্রান্সফিউশন-নির্ভর থ্যালাসেমিয়া) রয়েছে। লক্ষণগুলি সাধারণত জীবনের প্রথম দুই বছরের মধ্যে দেখা যায়, যার ফলে গুরুতর রক্তাল্পতা, ক্লান্তি, ফ্যাকাশে ত্বক এবং ধীর বৃদ্ধি ঘটে।",
    "If you receive only one mutated gene from one parent, you have thalassemia minor. Carriers usually have no symptoms or very mild anemia and do not require treatment.": "যদি আপনি একজন পিতামাতার কাছ থেকে কেবল একটি পরিবর্তিত জিন পান, তবে আপনার থ্যালাসেমিয়া মাইনর রয়েছে। বাহকদের সাধারণত কোনো উপসর্গ থাকে না বা খুব হালকা রক্তাল্পতা থাকে এবং তাদের চিকিৎসার প্রয়োজন হয় না।",
    "Impact": "প্রভাব",
    "Impact Dashboard": "প্রভাব ড্যাশবোর্ড",
    "Impact So Far": "এখনও পর্যন্ত প্রভাব",
    "Impact Stories": "প্রভাবের গল্প",
    "In India alone, over 1 lakh children are born with Thalassemia Major every year. Each patient needs 500-700 transfusions over their lifetime. That's not just 500 blood bags — it's 500 moments of uncertainty, coordination, and hope.": "শুধু ভারতেই প্রতি বছর ১ লাখেরও বেশি শিশু থ্যালাসেমিয়া মেজর নিয়ে জন্মায়। প্রতিটি রোগীর তাদের জীবনকালে ৫০০-৭০০ বার রক্ত সঞ্চালনের প্রয়োজন হয়। এটি কেবল ৫০০টি রক্তের ব্যাগ নয় — এটি অনিশ্চয়তা, সমন্বয় এবং আশার ৫০০টি মুহূর্ত।",
    "In Your Language, On Your Device": "আপনার নিজের ভাষায়, আপনার নিজের ডিভাইসে",
