    "It wasn't a statistic. It was a name. A face. A mother who spent 6 hours on the phone.": "এটি কোনও পরিসংখ্যান ছিল না। এটি ছিল একটি নাম। একটি মুখ। একজন মা যিনি ফোনে ৬ ঘণ্টা কাটিয়েছিলেন।",
