    "Join the network of heroes who show up — not once, but every time. Your blood type could be someone's lifeline.": "সেই সমস্ত বীরদের নেটওয়ার্কে যোগ দিন যারা একবার নয়, প্রতিবার পাশে দাঁড়ায়। আপনার রক্তের গ্রুপ কারও জীবন বাঁচানোর অবলম্বন হতে পারে।",
