    "Maintaining Target Hemoglobin Levels": "হিমোগ্লোবিনের লক্ষ্যমাত্রা বজায় রাখা",
    "Male": "পুরুষ",
    "Managing Absenteeism": "অনুপস্থিতি ব্যবস্থাপনা",
    "Managing TDT requires a multi-specialty medical team, including hematologists, cardiologists, and endocrinologists. Through Raksha AI, patient profiles are synchronized with compatible donor groups to ensure that every transfusion is matched for major and minor antigens, protecting patients from immunization risks over their lifetime.": "TDT ব্যবস্থাপনার জন্য হেমাটোলজিস্ট, কার্ডিওলজিস্ট এবং এন্ডোক্রিনোলজিস্ট সহ একটি বহু-স্পেশালিটি মেডিকেল টিমের প্রয়োজন। রক্ষা এআই (Raksha AI)-এর মাধ্যমে, পেশেন্ট প্রোফাইলগুলি সামঞ্জস্যপূর্ণ ডোনার গ্রুপের সাথে সিঙ্ক্রোনাইজ করা হয় যাতে প্রতিটি রক্ত সঞ্চালন প্রধান এবং গৌণ অ্যান্টিজেনের জন্য মিলে যায় তা নিশ্চিত করা যায়, যা রোগীদের আজীবন ইমিউনাইজেশন ঝুঁকি থেকে রক্ষা করে।",
    "Managing transfusion-dependent thalassemia requires meticulous planning, emotional resilience, and active coordination. This guide helps parents navigate the schedule and support their child effectively.": "ট্রান্সফিউশন-নির্ভর থ্যালাসেমিয়া ব্যবস্থাপনার জন্য সূক্ষ্ম পরিকল্পনা, মানসিক স্থিতিস্থাপকতা এবং সক্রিয় সমন্বয় প্রয়োজন। এই নির্দেশিকাটি অভিভাবকদের সময়সূচী পরিচালনা করতে এবং তাদের সন্তানকে কার্যকরভাবে সহায়তা করতে সাহায্য করে।",
    "Manual confirmation, check-in delays, and coordination gaps at the bedside.": "বেডসাইডে ম্যানুয়াল নিশ্চিতকরণ, চেক-ইন বিলম্ব এবং সমন্বয়ের অভাব।",
