    "Most blood donation platforms treat every donation as a one-time transaction. For Thalassemia patients, that model is dangerous. Here's why recurring, compatible donation is a medical necessity.": "বেশিরভাগ রক্তদান প্ল্যাটফর্ম প্রতিটি দানকে এককালীন লেনদেন হিসাবে গণ্য করে। থ্যালাসেমিয়া রোগীদের জন্য, সেই মডেলটি বিপজ্জনক। এখানে বলা হল কেন পুনরাবৃত্ত, সামঞ্জস্যপূর্ণ দান একটি চিকিৎসার প্রয়োজনীয়তা।",
    "Most donors feel fine after donation. Some may experience mild lightheadedness, which quickly resolves after resting for 10-15 minutes and having a light snack and water. We recommend avoiding strenuous physical activity or heavy lifting for the rest of the day.": "বেশিরভাগ দাতারা দানের পরে সুস্থ বোধ করেন। কেউ কেউ হালকা মাথা ঘোরা অনুভব করতে পারেন, যা ১০-১৫ মিনিট বিশ্রাম নেওয়ার পরে এবং হালকা নাস্তা ও জল খাওয়ার পরে দ্রুত ঠিক হয়ে যায়। আমরা দিনের বাকি সময়ের জন্য কঠোর শারীরিক কার্যকলাপ বা ভারী জিনিস উত্তোলন এড়িয়ে চলার পরামর্শ দিই।",
