    "No more sporadic donations. No more wondering if your blood made a difference. Become a recurring hero for someone who needs you every 21 days.": "আর বিক্ষিপ্তভাবে রক্তদান নয়। আপনার রক্তে কোনো উপকার হলো কিনা তা নিয়ে আর কোনো সংশয় নয়। এমন কারো জন্য একজন নিয়মিত বীর হয়ে উঠুন যার প্রতি ২১ দিনে আপনাকে প্রয়োজন।",
