    "Protecting lives, one match at a time.": "জীবন রক্ষা করছি, প্রতিটি সঠিক মিলের মাধ্যমে।",
    "Protecting lives, one match at a time. Raksha AI is transforming blood donation in India through intelligent matching and care coordination.": "প্রতিটি মিলের সাথে জীবন রক্ষা। রক্ষা AI বুদ্ধিমান মিল এবং যত্ন সমন্বয়ের মাধ্যমে ভারতে রক্তদান প্রক্রিয়াকে রূপান্তরিত করছে।",
    "protects.": "রক্ষা করে।",
    "Proximity:": "প্রক্সিমিটি:",
    "Questions? We're here to help.": "প্রশ্ন আছে? আমরা সাহায্য করতে এখানে আছি।",
    "Radical Transparency": "আমূল স্বচ্ছতা",
    "Raksha": "রক্ষা",
    "Raksha AI": "রক্ষা AI",
    "Raksha AI — Blood Intelligence & Care Coordination for Thalassemia Patients": "रक्षा AI — থ্যালাসেমিয়া রোগীদের জন্য রক্ত ​​বুদ্ধিমত্তা এবং যত্ন সমন্বয়",
    "RAKSHA AI — DONOR INTELLIGENCE": "রক্ষা AI — ডোনার ইন্টেলিজেন্স",
    "Raksha AI builds a dedicated donor circle around your patient. Smart reminders, compatibility matching, and predictive scheduling.": "রক্ষা AI আপনার রোগীর চারপাশে একটি নিবেদিত রক্তদাতা চক্র তৈরি করে। স্মার্ট অনুস্মারক, সামঞ্জস্যপূর্ণ মিল এবং দূরদর্শী সময়সূচী নির্ধারণ।",
    "Raksha AI builds a permanent support system around your patient.": "রক্ষা AI আপনার রোগীর চারপাশে একটি স্থায়ী সহায়তা ব্যবস্থা তৈরি করে।",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "রক্ষা AI নিবন্ধিত দাতাদের বর্ধিত ফেনোটাইপিক প্রোফাইলগুলিকে তালিকাভুক্ত করে এবং রোগীর প্রোফাইলের সাথে তাদের মিলিয়ে দেখে। স্থানীয় ডেটাবেসে সঠিক বা অত্যন্ত সামঞ্জস্যপূর্ণ অ্যান্টিজেন মিল খুঁজে বের করার মাধ্যমে, আমরা রোগ প্রতিরোধক প্রতিক্রিয়া শুরু হওয়ার আগেই প্রতিরোধ করি, যা নিরাপদ, কার্যকর এবং টেকসই রক্ত সঞ্চালন নিশ্চিত করে।",
    "Raksha AI communicates via app, SMS, and WhatsApp — in Hindi, Tamil, Marathi, Bengali, Telugu, and more.": "রক্ষা AI অ্যাপ, এসএমএস এবং হোয়াটসঅ্যাপের মাধ্যমে হিন্দি, তামিল, মারাঠি, বাংলা, তেলুগু এবং অন্যান্য ভাষায় যোগাযোগ করে।",
    "Raksha AI compression: 85% time saved": "রক্ষা AI কম্প্রেশন: ৮৫% সময় সাশ্রয়",
    "Raksha AI connects voluntary blood donors with Thalassemia patients across India — through intelligent matching, automated scheduling, and care that never stops.": "রক্ষা AI ভারত জুড়ে থ্যালাসেমিয়ারোগীদের স্বেচ্ছাসেবী রক্তদাতাদের সাথে সংযুক্ত করে — বুদ্ধিমান মিল, স্বয়ংক্রিয় সময়সূচী এবং অবিরাম যত্নের মাধ্যমে।",
    "Raksha AI considers ABO compatibility, Rh phenotype, Kell antigen status, and alloimmunization history.": "رक्षा AI ABO अनुकूलता, Rh फिनोटाइप, Kell एंटीजन स्थिति और एलोइम्यूनाइजेशन इतिहास पर विचार करता है।",
    "Raksha AI matches you to a specific patient based on blood compatibility, location, and availability.": "রক্তের সামঞ্জস্য, অবস্থান এবং প্রাপ্যতার ভিত্তিতে রক্ষা AI আপনাকে একটি নির্দিষ্ট রোগীর সাথে মেলায়।",
    "Raksha AI v0.1 Launches": "রক্ষা AI v0.1 লঞ্চ",
    "Raksha AI was built to be the infrastructure Blood Warriors never had — an intelligent, adaptive, multilingual platform that matches donors to patients.": "ব্লাড ওয়ারিয়র্সের কাছে আগে কখনও ছিল না এমন একটি অবকাঠামো হিসেবেই রক্ষা AI তৈরি করা হয়েছে — এটি একটি ও বুদ্ধিমান, মানানসই এবং বহুভাষিক প্ল্যাটফর্ম যা দাতাদের রোগীদের সাথে মেলায়।",
    "Raksha AI was built to eliminate that uncertainty. We match patients with committed donors, predict transfusion needs, and ensure no patient ever faces a shortage alone.": "সেই অনিশ্চয়তা দূর করার জন্যই রক্ষা AI তৈরি করা হয়েছে। আমরা রোগীদের প্রতিশ্রুতিবদ্ধ দাতাদের সাথে মেলাই, রক্ত সঞ্চালনের প্রয়োজনীয়তা পূর্বাভাস করি এবং নিশ্চিত করি যে কোনও রোগীকে কখনই একা ঘাটতির মুখোমুখি হতে না হয়।",
