    "What would you like to discuss?": "আপনি কী নিয়ে আলোচনা করতে চান?",
    "WhatsApp available?": "হোয়াটসঅ্যাপ আছে কি?",
    "when a patient near me urgently needs my blood type. I can opt out in": "যখন আমার কাছাকাছি কোনো রোগীর জরুরিভাবে আমার রক্তের গ্রুপের প্রয়োজন হয়। আমি এতে অপ্ট আউট করতে পারি",
    "When there is a mismatch in these minor antigens, the recipient's immune system identifies them as foreign, triggering B-lymphocytes to produce specific alloantibodies. Upon subsequent transfusions with cells carrying the same antigens, the antibodies bind to the donor cells, leading to extravascular hemolysis (destruction of red cells in the spleen or liver).": "যখন এই গৌণ অ্যান্টিজেনগুলির মধ্যে একটি অমিল থাকে, তখন প্রাপকের ইমিউন সিস্টেম সেগুলিকে বহিরাগত হিসাবে শনাক্ত করে, যা বি-লিম্ফোসাইটগুলিকে নির্দিষ্ট অ্যালোঅ্যান্টিবডি তৈরি করতে প্ররোচিত করে। একই অ্যান্টিজেন বহনকারী কোষের সাথে পরবর্তী রক্ত সঞ্চালনের পরে, অ্যান্টিবডিগুলি দাতা কোষের সাথে আবদ্ধ হয়, যার ফলে এক্সট্রাভাসকুলার হেমোলাইসিস (প্লীহা বা লিভারে লাল রক্তকণিকার ধ্বংস) ঘটে।",
    "When you register as a recurring donor on Raksha AI, you aren't just giving a random unit of blood. You are committing to becoming a lifeline for a specific patient. Regular donations (every 3 months for men, every 4 months for women) provide stable, compatible blood and ensure the patient's hemoglobin levels remain in a safe, healthy zone.": "যখন আপনি Raksha AI-তে একজন পুনরাবৃত্ত দাতা হিসাবে নিবন্ধন করেন, তখন আপনি কেবল রক্তের একটি এলোমেলো ইউনিট দিচ্ছেন না। আপনি একজন নির্দিষ্ট রোগীর জন্য জীবনরেখা হয়ে উঠতে প্রতিশ্রুতিবদ্ধ হচ্ছেন। নিয়মিত দান (পুরুষদের জন্য প্রতি 3 মাস অন্তর, মহিলাদের জন্য প্রতি 4 মাস অন্তর) স্থিতিশীল, সামঞ্জস্যপূর্ণ রক্ত সরবরাহ করে এবং রোগীর হিমোগ্লোবিনের মাত্রা একটি নিরাপদ, স্বাস্থ্যকর অঞ্চলে বজায় রাখে তা নিশ্চিত করে।",
    "Where do transfusions happen?": "ট্রান্সফিউশন কোথায় ঘটে?",
