    "Yes": "হ্যাঁ",
    "You are not just a blood type. You are someone's lifeline.": "আপনি কেবল একটি রক্তের গ্রুপ নন। আপনি কারও জীবন বাঁচানোর অবলম্বন।",
    "You donate once. Raksha makes sure you never stop mattering.": "আপনি একবার দান করেন। রক্ষা নিশ্চিত করে যে আপনার গুরুত্ব যেন কখনও শেষ না হয়।",
    "You give blood once. Raksha AI turns that into a relationship. We remind you when you're eligible again, match you with patients who need your blood type, and show you the impact you're making — not in abstract numbers, but in real lives.": "আপনি একবার রক্ত দেন। রক্ষা AI সেটিকে একটি সম্পর্কে রূপান্তর করে। আপনি যখন আবার রক্ত দেওয়ার যোগ্য হবেন তখন আমরা আপনাকে মনে করিয়ে দেব, আপনার রক্তের গ্রুপের প্রয়োজন এমন রোগীদের সাথে আপনাকে মেলাব এবং আপনার অবদানকে তুলে ধরব — কোনো সংখ্যায় নয়, বরং বাস্তব জীবনে।",
    "You Save a Life": "আপনি একটি জীবন বাঁচান",
    "You will feel a quick pinch when the needle is inserted, which lasts only a second. During the actual donation, which takes about 8 to 10 minutes, you should feel no pain. Our trained medical staff monitor you throughout the process to ensure you are comfortable.": "যখন সূঁচ ঢোকানো হয় তখন আপনি একটি দ্রুত চিমটি অনুভব করবেন, যা মাত্র এক সেকেন্ড স্থায়ী হয়। প্রকৃত রক্তদানের সময়, যার জন্য প্রায় 8 থেকে 10 মিনিট সময় লাগে, আপনার কোনও ব্যথা অনুভব করা উচিত নয়। আমাদের প্রশিক্ষিত চিকিৎসা কর্মীরা পুরো প্রক্রিয়া জুড়ে আপনাকে পর্যবেক্ষণ করেন যাতে আপনি স্বাচ্ছন্দ্য বোধ করেন।",
    "You're now a Raksha Donor.": "আপনি এখন একজন রক্ষা দাতা।",
    "You're registered,": "আপনি নিবন্ধিত,",
    "You're subscribed.": "আপনি সাবস্ক্রাইব করেছেন।",
    "You've been fighting this alone. You don't have to anymore.": "আপনি এতদিন একা লড়াই করছিলেন। আর আপনাকে একা লড়াই করতে হবে না।",
    "You've spent years managing transfusion schedules, calling donors, and hoping someone answers. Raksha AI takes that burden off your shoulders. We predict when your child needs blood, find compatible donors, and coordinate everything — so you can focus on being a parent, not a logistics manager.": "আপনি বছরের পর বছর ধরে রক্ত সঞ্চালনের সময়সূচী পরিচালনা করেছেন, দাতাদের কল করেছেন এবং কেউ সাড়া দেবে এই আশায় বুক বেঁধেছেন। রক্ষা AI আপনার কাঁধ থেকে সেই বোঝা নামিয়ে দিচ্ছে। আমরা অনুমান করি যে আপনার সন্তানের কখন রক্ত প্রয়োজন, উপযুক্ত দাতা খুঁজে বের করি এবং সমস্ত কিছু সমন্বয় করি — যাতে আপনি একজন লজিস্টিক ম্যানেজারের পরিবর্তে বাবা-মা হওয়ার দিকে মনোযোগ দিতে পারেন।",
    "you@example.com": "you@example.com",
    "you@org.com": "you@org.com",
    "YOUR BADGE COLLECTION": "আপনার ব্যাজ সংগ্রহ",
    "Your blood has": "আপনার রক্তে আছে",
    "Your child's next transfusion is already being arranged.": "আপনার সন্তানের পরবর্তী রক্ত সঞ্চালনের ব্যবস্থা ইতিমধ্যেই করা হচ্ছে।",
    "Your child's next transfusion is already scheduled. Not because you spent all night calling numbers, but because Raksha AI coordinates the schedule. We build a donor circle of 5 committed donors specifically matched to your child.": " his আপনার সন্তানের পরবর্তী রক্ত সঞ্চালন ইতিমধ্যেই নির্ধারিত হয়ে গেছে। এজন্য নয় যে আপনি সারা রাত বিভিন্ন নম্বরে কল করেছেন, বরং এজন্য যে রক্ষা AI এই সময়সূচী সমন্বয় করে। আমরা বিশেষ করে আপনার সন্তানের সাথে মানানসই ৫ জন প্রতিশ্রুতিবদ্ধ দাতার একটি দাতা চক্র গড়ে তুলি।",
    "your child&apos;s circle": "আপনার সন্তানের বৃত্ত",
    "Your circle of donors and caregivers will receive coordinated alerts — so nobody misses a critical transfusion.": "আপনার দাতা এবং যত্নশীলদের বৃত্ত সমন্বিত সতর্কতা পাবে — যাতে কেউ গুরুত্বপূর্ণ রক্ত সঞ্চালন মিস না করে।",
