    "At the start of the school year, parents should meet with teachers and the school nurse. Explain Thalassemia in simple terms, detail the transfusion schedule, and discuss signs of low hemoglobin (such as pale skin, extreme fatigue, or shortness of breath). Provide emergency contact details and letters from your child's hematologist.": "શૈક્ષણિક વર્ષની શરૂઆતમાં, વાલીઓએ શિક્ષકો અને શાળાના નર્સને મળવું જોઈએ. થેલેસેમિયા વિશે સરળ શબ્દોમાં સમજાવો, ટ્રાન્સફ્યુઝન શેડ્યૂલની વિગત આપો અને ઓછા હિમોગ્લોબિનના ચિહ્નો (જેમ કે ફિક્કી ત્વચા, અતિશય થાક અથવા શ્વાસ લેવામાં તકલીફ) વિશે ચર્ચા કરો. ઇમરજન્સી સંપર્ક વિગતો અને તમારા બાળકના હેમેટોલોજિસ્ટના પત્રો પ્રદાન કરો.",
