    "I am the patient, parent, or legal guardian authorised to provide this information.": "હું દર્દી, માતા-પિતા અથવા કાયદેસરનો વાલી છું જે આ માહિતી આપવા માટે અધિકૃત છે.",
    "I consent to Raksha AI storing and processing this patient": "હું Raksha AI ને આ દર્દીની માહિતી સંગ્રહિત અને પ્રોસેસ કરવા માટે સંમતિ આપું છું",
    "I consent to Raksha AI storing and using this information to coordinate blood donation.": "રક્તદાનના સંકલન માટે રક્ષા AI આ માહિતીનો સંગ્રહ અને ઉપયોગ કરે તે માટે હું સંમતિ આપું છું.",
    "I Want to Donate Blood": "હું રક્તદાન કરવા માંગુ છું",
    "Identify inactive donors or deferred status updates that require care coordinator intervention.": "નિષ્ક્રિય દાતાઓ અથવા મુલતવી રાખવામાં આવેલી સ્ટેટસ અપડેટ્સ ઓળખો કે જેને કેર કોઓર્ડિનેટરના હસ્તક્ષેપની જરૂર છે.",
    "If you receive mutated genes from both parents, you have thalassemia major (Transfusion-Dependent Thalassemia). Symptoms usually appear within the first two years of life, causing severe anemia, fatigue, pale skin, and slow growth.": "જો તમને બંને માતાપિતા પાસેથી પરિવર્તિત જનીનો મળે, તો તમને થેલેસેમિયા મેજર (ટ્રાન્સફ્યુઝન-ડિપેન્ડન્ટ થેલેસેમિયા) છે. લક્ષણો સામાન્ય રીતે જીવનના પ્રથમ બે વર્ષમાં દેખાય છે, જેના કારણે ગંભીર એનિમિયા, થાક, નિસ્તેજ ત્વચા અને ધીમી વૃદ્ધિ થાય છે.",
    "If you receive only one mutated gene from one parent, you have thalassemia minor. Carriers usually have no symptoms or very mild anemia and do not require treatment.": "જો તમને એક માતાપિતા પાસેથી ફક્ત એક પરિવર્તિત જનીન મળે, તો તમને થેલેસેમિયા માઇનોર છે. વાહકોમાં સામાન્ય રીતે કોઈ લક્ષણો હોતા નથી અથવા ખૂબ હળવો એનિમિયા હોય છે અને તેમને સારવારની જરૂર હોતી નથી.",
    "Impact": "અસર",
    "Impact Dashboard": "અસર ડેશબોર્ડ",
    "Impact So Far": "અત્યાર સુધીની અસર",
    "Impact Stories": "અસરની વાર્તાઓ",
    "In India alone, over 1 lakh children are born with Thalassemia Major every year. Each patient needs 500-700 transfusions over their lifetime. That's not just 500 blood bags — it's 500 moments of uncertainty, coordination, and hope.": "એકલા ભારતમાં જ દર વર્ષે ૧ લાખથી વધુ બાળકો થૅલેસેમિયા મેજર સાથે જન્મે છે. દરેક દર્દીને તેમના આયુષ્ય દરમિયાન ૫૦૦-૭૦૦ રુધિરાધાનની જરૂર પડે છે. તે માત્ર ૫૦૦ બ્લડ બેગ નથી — તે અનિશ્ચિતતા, સમન્વય અને આશાની ૫૦૦ ક્ષણો છે.",
