    "It wasn't a statistic. It was a name. A face. A mother who spent 6 hours on the phone.": "તે કોઈ આંકડો ન હતો. તે એક નામ હતું. એક ચહેરો હતું. એક માતા જેણે ફોન પર ૬ કલાક વિતાવ્યા હતા.",
    "Join the Mission": "મિશનમાં જોડાઓ",
    "Join the network of heroes who show up — not once, but every time. Your blood type could be someone's lifeline.": "એવા હીરો નેટવર્કમાં જોડાઓ જે માત્ર એક વાર નહીં, પણ દરેક વખતે હાજર રહે છે. તમારું બ્લડ ગ્રૂપ કોઈની જીવાદોરી બની શકે છે.",
