    "Most blood donation platforms treat every donation as a one-time transaction. For Thalassemia patients, that model is dangerous. Here's why recurring, compatible donation is a medical necessity.": "મોટાભાગના રક્તદાન પ્લેટફોર્મ દરેક દાનને એક વખતની લેવડદેવડ તરીકે ગણે છે. થેલેસેમિયાના દર્દીઓ માટે, તે મોડેલ જોખમી છે. અહીં જણાવ્યું છે કે શા માટે પુનરાવર્તિત, સુસંગત દાન એ એક તબીબી આવશ્યકતા છે.",
    "Most donors feel fine after donation. Some may experience mild lightheadedness, which quickly resolves after resting for 10-15 minutes and having a light snack and water. We recommend avoiding strenuous physical activity or heavy lifting for the rest of the day.": "મોટાભાગના દાતાઓ દાન કર્યા પછી સારું અનુભવે છે. કેટલાકને હળવી ચક્કર આવી શકે છે, જે 10-15 મિનિટ આરામ કર્યા પછી અને હળવો નાસ્તો અને પાણી લીધા પછી ઝડપથી દૂર થઈ જાય છે. અમે બાકીના દિવસ માટે સખત શારીરિક પ્રવૃત્તિ અથવા ભારે વસ્તુઓ ઉપાડવાનું ટાળવાની ભલામણ કરીએ છીએ.",
