    "No more sporadic donations. No more wondering if your blood made a difference. Become a recurring hero for someone who needs you every 21 days.": "હવે ક્યારેક-ક્યારેક રક્તદાન કરવાની જરૂર નથી. તમારા રક્તથી કોઈ ફરક પડ્યો કે નહીં તે વિચારવાની જરૂર નથી. દર ૨૧ દિવસે તમારી જરૂરિયાતવાળા કોઈ માટે વારંવાર આવતા હીરો બનો.",
