    "Raksha AI — Blood Intelligence & Care Coordination for Thalassemia Patients": "Raksha AI — થેલેસેમિયા દર્દીઓ માટે இரத்த બુદ્ધિ અને સંભાળ સંકલન",
    "RAKSHA AI — DONOR INTELLIGENCE": "રક્ષા AI — ડોનર ઇન્ટેલિજન્સ",
    "Raksha AI builds a dedicated donor circle around your patient. Smart reminders, compatibility matching, and predictive scheduling.": "રક્ષા AI તમારા દર્દીની આસપાસ એક સમર્પિત દાતા મંડળ બનાવે છે. સ્માર્ટ રીમાઇન્ડર્સ, સુસંગતતા મેચિંગ અને આગાહી શેડ્યુલિંગ.",
    "Raksha AI builds a permanent support system around your patient.": "રક્ષા AI તમારા દર્દીની આસપાસ કાયમી સપોર્ટ સિસ્ટમ બનાવે છે.",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "રક્ષા AI નોંધાયેલા દાતાઓની વિસ્તૃત ફેનોટાઇપિકલ પ્રોફાઇલ્સને સૂચિબદ્ધ કરે છે અને તેને દર્દીની પ્રોફાઇલ્સ સાથે મેચ કરે છે. સ્થાનિક ડેટાબેઝમાં ચોક્કસ અથવા અત્યંત સુસંગત એન્ટિજેન મેચો શોધીને, અમે રોગપ્રતિકારક પ્રતિક્રિયાઓને શરૂ થતા પહેલા જ અટકાવીએ છીએ, જે સુરક્ષિત, અસરકારક અને ટકાઉ રક્તદાન સુનિશ્ચિત કરે છે.",
    "Raksha AI communicates via app, SMS, and WhatsApp — in Hindi, Tamil, Marathi, Bengali, Telugu, and more.": "રક્ષા AI એપ, એસએમએસ અને વોટ્સએપ દ્વારા હિન્દી, તમિલ, મરાઠી, બંગાળી, તેલુગુ અને અન્ય ભાષાઓમાં સંવાદ કરે છે.",
    "Raksha AI compression: 85% time saved": "રક્ષા AI કમ્પ્રેસન: 85% સમય બચાવ્યો",
    "Raksha AI connects voluntary blood donors with Thalassemia patients across India — through intelligent matching, automated scheduling, and care that never stops.": "રક્ષા AI ભારત ભરમાં થૅલેસેમિયા દર્દીઓને સ્વૈચ્છિક રક્ત દાતાઓ સાથે જોડે છે — બુદ્ધિશાળી મેળ, સ્વયંચાલિત આયોજન અને અવિરત કાળજી દ્વારા.",
    "Raksha AI considers ABO compatibility, Rh phenotype, Kell antigen status, and alloimmunization history.": "રક્ષા AI ABO સુસંગતતા, Rh ફેનોટાઇપ, કેલ એન્ટિજેન સ્થિતિ અને એલોઇમ્યુનાઇઝેશન ઇતિહાસને ધ્યાનમાં લે છે.",
    "Raksha AI matches you to a specific patient based on blood compatibility, location, and availability.": "રક્ષા AI રક્તની સુસંગતતા, સ્થાન અને ઉપલબ્ધતાના આધારે દર્દી સાથે મેળ કરે છે.",
    "Raksha AI v0.1 Launches": "રક્ષા AI v0.1 લોન્ચ",
    "Raksha AI was built to be the infrastructure Blood Warriors never had — an intelligent, adaptive, multilingual platform that matches donors to patients.": "બ્લડ વોરિયર્સ પાસે ક્યારેય નહોતું તેવું ઇન્ફ્રાસ્ટ્રક્ચર બનવા માટે રક્ષા AI બનાવવામાં આવ્યું છે — એક બુદ્ધિશાળી, અનુકૂલનશીલ અને બહુભાષી પ્લેટફોર્મ જે દાતાઓને દર્દીઓ સાથે મેળ ખવડાવે છે.",
    "Raksha AI was built to eliminate that uncertainty. We match patients with committed donors, predict transfusion needs, and ensure no patient ever faces a shortage alone.": "તે અનિશ્ચિતતાને દૂર કરવા માટે જ રક્ષા AI બનાવવામાં આવ્યું છે. અમે દર્દીઓને પ્રતિબદ્ધ દાતાઓ સાથે જોડીએ છીએ, રુધિરાધાનની જરૂરિયાતોનું પૂર્વાનુમાન કરીએ છીએ અને ખાતરી કરીએ છીએ કે કોઈ દર્દીએ ક્યારેય એકલા અછતનો સામનો ન કરવો પડે.",
