    "Your state": "તમારું રાજ્ય",
    "your@email.com": "your@email.com",
    "बांला (Bengali)": "બંગાળી (Bengali)",
    "मराठी (Marathi)": "મરાઠી (Marathi)",
    "हिन्दी (Hindi)": "હિન્દી (Hindi)",
    "ਪੰਜਾਬੀ (Punjabi)": "પંજાબી (Punjabi)",
