    "At risk (>80% window used)": "ਖਤਰੇ ਵਿੱਚ (>80% ਵਿੰਡੋ ਵਰਤੀ ਗਈ)",
    "At the start of the school year, parents should meet with teachers and the school nurse. Explain Thalassemia in simple terms, detail the transfusion schedule, and discuss signs of low hemoglobin (such as pale skin, extreme fatigue, or shortness of breath). Provide emergency contact details and letters from your child's hematologist.": "ਸਕੂਲੀ ਸਾਲ ਦੀ ਸ਼ੁਰੂਆਤ ਵਿੱਚ, ਮਾਪਿਆਂ ਨੂੰ ਅਧਿਆਪਕਾਂ ਅਤੇ ਸਕੂਲ ਦੀ ਨਰਸ ਨਾਲ ਮਿਲਣਾ ਚਾਹੀਦਾ ਹੈ। ਥੈਲੇਸੀਮੀਆ ਬਾਰੇ ਸਰਲ ਸ਼ਬਦਾਂ ਵਿੱਚ ਸਮਝਾਓ, ਟ੍ਰਾਂਸਫਿਊਜ਼ਨ ਸ਼ਡਿਊਲ ਬਾਰੇ ਵਿਸਥਾਰ ਨਾਲ ਦੱਸੋ ਅਤੇ ਘੱਟ ਹੀਮੋਗਲੋਬਿਨ ਦੇ ਲੱਛਣਾਂ (ਜਿਵੇਂ ਕਿ ਫਿੱਕੀ ਚਮੜੀ, ਬਹੁਤ ਜ਼ਿਆਦਾ ਥਕਾਵਟ, ਜਾਂ ਸਾਹ ਚੜ੍ਹਨਾ) ਬਾਰੇ ਚਰਚਾ ਕਰੋ। ਐਮਰਜੈਂਸੀ ਸੰਪਰਕ ਵੇਰਵੇ ਅਤੇ ਆਪਣੇ ਬੱਚੇ ਦੇ ਹੇਮਾਟੋਲੋਜਿਸਟ ਦੇ ਪੱਤਰ ਪ੍ਰਦਾਨ ਕਰੋ।",
