    "Donors who are currently eligible (exceeded the 90-day donation interval) and ready for matching.": "ਜਿਹੜੇ ਦਾਨੀ ਇਸ ਸਮੇਂ ਯੋਗ ਹਨ (90-ਦਿਨਾਂ ਦੇ ਦਾਨ ਅੰਤਰਾਲ ਤੋਂ ਵੱਧ ਗਏ ਹਨ) ਅਤੇ ਮੈਚਿੰਗ ਲਈ ਤਿਆਰ ਹਨ।",
