    "e.g. Nizam": "ਉਦਾਹਰਨ ਵਜੋਂ ਨਿਜ਼ਾਮ",
    "Each time a patient receives blood with incompatible minor antigens, their immune system builds resistance. Over hundreds of transfusions, this becomes life-threatening.": "ਹਰ ਵਾਰ ਜਦੋਂ ਕੋਈ ਮਰੀਜ਼ ਅਸੰਗਤ ਮਾਈਨਰ ਐਂਟੀਜੇਨ ਵਾਲਾ ਖੂਨ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ, ਤਾਂ ਉਸਦੀ ਇਮਿਊਨ ਸਿਸਟਮ ਪ੍ਰਤੀਰੋਧਕ ਸ਼ਕਤੀ ਪੈਦਾ ਕਰ ਲੈਂਦੀ ਹੈ। ਸੈਂਕੜੇ ਵਾਰ ਖੂਨ ਚੜ੍ਹਾਉਣ ਤੋਂ ਬਾਅਦ, ਇਹ ਜੀਵਨ ਲਈ ਖਤਰਾ ਬਣ ਜਾਂਦਾ ਹੈ।",
    "Each unit of transfused red blood cells contains approximately 200 mg of iron. Over a year of monthly transfusions, this amounts to a significant iron burden. If left untreated, the excess iron deposits in the liver, heart, and endocrine glands, leading to organ failure, heart disease, diabetes, and stunted growth.": "ਟ੍ਰਾਂਸਫਿਊਜ਼ ਕੀਤੀਆਂ ਗਈਆਂ ਲਾਲ ਰਕਤ ਕੋਸ਼ਿਕਾਵਾਂ ਦੀ ਹਰੇਕ ਯੂਨਿਟ ਵਿੱਚ ਲਗਭਗ 200 ਮਿਲੀਗ੍ਰਾਮ ਆਇਰਨ ਹੁੰਦਾ ਹੈ। ਇੱਕ ਸਾਲ ਦੇ ਮਾਸਿਕ ਟ੍ਰਾਂਸਫਿਊਜ਼ਨ ਤੋਂ ਬਾਅਦ, ਇਹ ਆਇਰਨ ਦਾ ਇੱਕ ਮਹੱਤਵਪੂਰਨ ਬੋਝ ਬਣ ਜਾਂਦਾ ਹੈ। ਜੇਕਰ ਇਲਾਜ ਨਾ ਕੀਤਾ ਜਾਵੇ, ਤਾਂ ਵਾਧੂ ਆਇਰਨ ਜਿਗਰ, ਦਿਲ ਅਤੇ ਐਂਡੋਕ੍ਰਾਈਨ ਗ੍ਰੰਥੀਆਂ ਵਿੱਚ ਜਮ੍ਹਾਂ ਹੋ ਜਾਂਦਾ ਹੈ, ਜਿਸ ਨਾਲ ਅੰਗ ਫੇਲ੍ਹ ਹੋਣਾ, ਦਿਲ ਦੀ ਬਿਮਾਰੀ, ਸ਼ੂਗਰ ਅਤੇ ਵਿਕਾਸ ਵਿੱਚ ਰੁਕਾਵਟ ਆ ਸਕਦੀ ਹੈ।",
