    "Finding compatible blood becomes a search for a needle in a haystack, causing critical delays in treatment.": "ਅਨੁਕੂਲ ਲਹੂ ਲੱਭਣਾ ਇੱਕ ਤੂੜੀ ਦੇ ਢੇਰ ਵਿੱਚ ਸੂਈ ਲੱਭਣ ਵਰਗਾ ਹੋ ਜਾਂਦਾ ਹੈ, ਜਿਸ ਨਾਲ ਇਲਾਜ ਵਿੱਚ ਗੰਭੀਰ ਦੇਰੀ ਹੁੰਦੀ ਹੈ।",
