    "First update coming next month.": "ਪਹਿਲਾ ਅਪਡੇਟ ਅਗਲੇ ਮਹੀਨੇ ਆ ਰਿਹਾ ਹੈ।",
    "Flexible Scheduling": "ਲਚਕਦਾਰ ਸਮਾਂ-ਸੂਚੀ",
    "FOR BLOOD DONORS": "ਖੂਨ ਦਾਨੀਆਂ ਲਈ",
