    "For Donors | Raksha AI": "ਦਾਨੀਆਂ ਲਈ | ਰਕਸ਼ਾ AI",
    "For individuals with TDT, red blood cells are fragile and break down rapidly. Standard therapy involves regular blood transfusions every 2 to 4 weeks. These transfusions supply the body with healthy donor red blood cells, enabling oxygen delivery and suppressing the body’s own overactive bone marrow, which prevents skeletal deformities and other severe complications.": "TDT ਵਾਲੇ ਵਿਅਕਤੀਆਂ ਲਈ, ਲਾਲ ਰਕਤ ਪੇਸ਼ੀ (red blood cells) ਨਾਜ਼ੁਕ ਹੁੰਦੀਆਂ ਹਨ ਅਤੇ ਤੇਜ਼ੀ ਨਾਲ ਟੁੱਟ ਜਾਂਦੀਆਂ ਹਨ। ਸਟੈਂਡਰਡ ਥੈਰੇਪੀ ਵਿੱਚ ਹਰ 2 ਤੋਂ 4 ਹਫ਼ਤਿਆਂ ਵਿੱਚ ਨਿਯਮਤ ਖੂਨ ਚੜ੍ਹਾਉਣਾ ਸ਼ਾਮਲ ਹੁੰਦਾ ਹੈ। ਇਹ ਟ੍ਰਾਂਸਫਿਊਜ਼ਨ ਸਰੀਰ ਨੂੰ ਸਿਹਤਮੰਦ ਦਾਨੀ ਲਾਲ ਰਕਤ ਪੇਸ਼ੀ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ, ਆਕਸੀਜਨ ਦੀ ਸਪਲਾਈ ਨੂੰ ਸਮਰੱਥ ਬਣਾਉਂਦੇ ਹਨ ਅਤੇ ਸਰੀਰ ਦੇ ਆਪਣੇ ਜ਼ਿਆਦਾ ਸਰਗਰਮ ਬੋਨ ਮੈਰੋ ਨੂੰ ਦਬਾਉਂਦੇ ਹਨ, ਜੋ ਪਿੰਜਰ ਦੇ ਵਿਗਾੜ ਅਤੇ ਹੋਰ ਗੰਭੀਰ ਜਟਿਲਤਾਵਾਂ ਨੂੰ ਰੋਕਦਾ ਹੈ।",
    "for notifications & reports": "ਸੂਚਨਾਵਾਂ ਅਤੇ ਰਿਪੋਰਟਾਂ ਲਈ",
    "For Patients": "ਮਰੀਜ਼ਾਂ ਲਈ",
    "For Patients & Families | Raksha AI": "ਮਰੀਜ਼ਾਂ ਅਤੇ ਪਰਿਵਾਰਾਂ ਲਈ | ਰਕਸ਼ਾ AI",
    "For patients with Transfusion-Dependent Thalassemia, a Bone Marrow Transplant (BMT) — also known as a Hematopoietic Stem Cell Transplant — currently offers the only established, permanent cure.": "ਖੂਨ ਚੜ੍ਹਾਉਣ-ਨਿਰਭਰ ਥੈਲੇਸੀਮੀਆ (Transfusion-Dependent Thalassemia) ਦੇ ਮਰੀਜ਼ਾਂ ਲਈ, ਬੋਨ ਮੈਰੋ ਟ੍ਰਾਂਸਪਲਾਂਟ (Bone Marrow Transplant - BMT) — ਜਿਸਨੂੰ ਹੈਮੇਟੋਪੋਏਟਿਕ ਸਟੈਮ ਸੈੱਲ ਟ੍ਰਾਂਸਪਲਾਂਟ (Hematopoietic Stem Cell Transplant) ਵੀ ਕਿਹਾ ਜਾਂਦਾ ਹੈ — ਵਰਤਮਾਨ ਵਿੱਚ ਇੱਕੋ-ਇਕ ਸਥਾਪਿਤ, ਪੱਕਾ ਇਲਾਜ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ।",
    "FOR THALASSEMIA FAMILIES": "ਥੈਲੇਸੀਮੀਆ ਪਰਿਵਾਰਾਂ ਲਈ",
