    "Geographic distribution of blood requests versus registered active donor matching pools.": "ਬਲੱਡ ਦੀਆਂ ਬੇਨਤੀਆਂ ਬਨਾਮ ਰਜਿਸਟਰਡ ਸਰਗਰਮ ਦਾਨੀ ਮੈਚਿੰਗ ਪੂਲ ਦੀ ਭੂਗੋਲਿਕ ਵੰਡ।",
