    "Have questions about blood donation? We've compiled the most common questions from first-time and recurring donors to help you understand the process and your impact.": "ਕੀ ਖੂਨਦਾਨ ਬਾਰੇ ਤੁਹਾਡੇ ਕੋਈ ਸਵਾਲ ਹਨ? ਅਸੀਂ ਪਹਿਲੀ ਵਾਰ ਅਤੇ ਨਿਯਮਿਤ ਦਾਨੀਆਂ ਦੇ ਸਭ ਤੋਂ ਆਮ ਸਵਾਲ ਇਕੱਠੇ ਕੀਤੇ ਹਨ ਤਾਂ ਜੋ ਤੁਹਾਨੂੰ ਪ੍ਰਕਿਰਿਆ ਅਤੇ ਤੁਹਾਡੇ ਪ੍ਰਭਾਵ ਨੂੰ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਮਿਲ ਸਕੇ।",
    "Hb After": "Hb ਤੋਂ ਬਾਅਦ",
    "Hb Before": "Hb ਤੋਂ ਪਹਿਲਾਂ",
    "Health Insights": "ਸਿਹਤ ਸੰਬੰਧੀ ਜਾਣਕਾਰੀ",
    "Health Tracker": "ਹੈਲਥ ਟ੍ਰੈਕਰ",
    "Healthy male donors can donate whole blood every 90 days (3 months), and female donors can donate every 120 days (4 months). This interval ensures that your body has fully replenished its red blood cells and iron stores before your next donation.": "ਤੰਦਰੁਸਤ ਪੁਰਸ਼ ਦਾਨੀ ਹਰ 90 ਦਿਨਾਂ (3 ਮਹੀਨੇ) ਵਿੱਚ ਅਤੇ ਮਹਿਲਾ ਦਾਨੀ ਹਰ 120 ਦਿਨਾਂ (4 ਮਹੀਨੇ) ਵਿੱਚ ਖੂਨਦਾਨ ਕਰ ਸਕਦੇ ਹਨ। ਇਹ ਅੰਤਰਾਲ ਇਹ ਯਕੀਨੀ ਬਣਾਉਂਦਾ ਹੈ ਕਿ ਤੁਹਾਡੇ ਅਗਲੇ ਖੂਨਦਾਨ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਡੇ ਸਰੀਰ ਵਿੱਚ ਲਾਲ ਰਕਤਾਣੂਆਂ ਅਤੇ ਆਇਰਨ ਦਾ ਪੱਧਰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਭਰ ਜਾਵੇ।",
    "Help us ensure you're eligible and understand when you can donate.": "ਇਹ ਯਕੀਨੀ ਬਣਾਉਣ ਵਿੱਚ ਸਾਡੀ ਮਦਦ ਕਰੋ ਕਿ ਤੁਸੀਂ ਯੋਗ ਹੋ ਅਤੇ ਸਮਝੋ ਕਿ ਤੁਸੀਂ ਕਦੋਂ ਦਾਨ ਕਰ ਸਕਦੇ ਹੋ।",
