    "Instant screening based on ABO/Rh history, location, and alloimmunization risk.": "ABO/Rh ਇਤਿਹਾਸ, ਸਥਾਨ ਅਤੇ ਐਲੋਇਮਯੂਨਾਈਜ਼ੇਸ਼ਨ ਜੋਖਮ ਦੇ ਆਧਾਰ 'ਤੇ ਤੁਰੰਤ ਸਕ੍ਰੀਨਿੰਗ।",
