    "Iron Overload & Chelation Therapy": "ਆਇਰਨ ਓਵਰਲੋਡ ਅਤੇ ਕਿਊਲੇਸ਼ਨ ਥੈਰੇਪੀ",
    "It wasn't a statistic. It was a name. A face. A mother who spent 6 hours on the phone.": "ਇਹ ਕੋਈ ਅੰਕੜਾ ਨਹੀਂ ਸੀ। ਇਹ ਇੱਕ ਨਾਮ ਸੀ। ਇੱਕ ਚਿਹਰਾ। ਇੱਕ ਮਾਂ ਜਿਸਨੇ ਫ਼ੋਨ 'ਤੇ 6 ਘੰਟੇ ਬਿਤਾਏ।",
    "Join the Mission": "ਮਿਸ਼ਨ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ",
    "Join the network of heroes who show up — not once, but every time. Your blood type could be someone's lifeline.": "ਉਹਨਾਂ ਨਾਇਕਾਂ ਦੇ ਨੈੱਟਵਰਕ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ ਜੋ ਸਾਹਮਣੇ ਆਉਂਦੇ ਹਨ — ਇੱਕ ਵਾਰ ਨਹੀਂ, ਬਲਕਿ ਹਰ ਵਾਰ। ਤੁਹਾਡਾ ਖੂਨ ਦਾ ਗਰੁੱਪ ਕਿਸੇ ਦੀ ਜੀਵਨ ਰੇਖਾ ਹੋ ਸਕਦਾ ਹੈ।",
