    "Morning (6am–12pm)": "ਸਵੇਰ (6am–12pm)",
    "Most blood donation platforms treat every donation as a one-time transaction. For Thalassemia patients, that model is dangerous. Here's why recurring, compatible donation is a medical necessity.": "ਜ਼ਿਆਦਾਤਰ ਖੂਨਦਾਨ ਪਲੇਟਫਾਰਮ ਹਰ ਦਾਨ ਨੂੰ ਇੱਕ-ਵਾਰੀ ਲੈਣ-ਦੇਣ ਵਜੋਂ ਮੰਨਦੇ ਹਨ। ਥੈਲੇਸੀਮੀਆ ਦੇ ਮਰੀਜ਼ਾਂ ਲਈ, ਉਹ ਮਾਡਲ ਖਤਰਨਾਕ ਹੈ। ਇੱਥੇ ਦੱਸਿਆ ਗਿਆ ਹੈ ਕਿ ਕਿਉਂ ਵਾਰ-ਵਾਰ, ਅਨੁਕੂਲ ਦਾਨ ਇੱਕ ਡਾਕਟਰੀ ਲੋੜ ਹੈ।",
    "Most donors feel fine after donation. Some may experience mild lightheadedness, which quickly resolves after resting for 10-15 minutes and having a light snack and water. We recommend avoiding strenuous physical activity or heavy lifting for the rest of the day.": "ਜ਼ਿਆਦਾਤਰ ਦਾਨੀ ਦਾਨ ਤੋਂ ਬਾਅਦ ਠੀਕ ਮਹਿਸੂਸ ਕਰਦੇ ਹਨ। ਕੁਝ ਨੂੰ ਹਲਕਾ ਚੱਕਰ ਆ ਸਕਦਾ ਹੈ, ਜੋ 10-15 ਮਿੰਟ ਆਰਾਮ ਕਰਨ ਅਤੇ ਹਲਕਾ ਸਨੈਕ ਅਤੇ ਪਾਣੀ ਪੀਣ ਤੋਂ ਬਾਅਦ ਜਲਦੀ ਠੀਕ ਹੋ ਜਾਂਦਾ ਹੈ। ਅਸੀਂ ਦਿਨ ਦੇ ਬਾਕੀ ਸਮੇਂ ਲਈ ਸਖ਼ਤ ਸਰੀਰਕ ਗਤੀਵਿਧੀ ਜਾਂ ਭਾਰੀ ਚੀਜ਼ਾਂ ਚੁੱਕਣ ਤੋਂ ਪਰਹੇਜ਼ ਕਰਨ ਦੀ ਸਿਫਾਰਸ਼ ਕਰਦੇ ਹਾਂ।",
