    "No more sporadic donations. No more wondering if your blood made a difference. Become a recurring hero for someone who needs you every 21 days.": "ਹੁਣ ਕਦੇ-ਕਦਾਈਂ ਖੂਨ ਦਾਨ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ। ਹੁਣ ਇਹ ਸੋਚਣ ਦੀ ਲੋੜ ਨਹੀਂ ਕਿ ਕੀ ਤੁਹਾਡੇ ਖੂਨ ਨਾਲ ਕੋਈ ਫਰਕ ਪਿਆ। ਕਿਸੇ ਅਜਿਹੇ ਵਿਅਕਤੀ ਲਈ ਬਾਰ-ਬਾਰ ਆਉਣ ਵਾਲੇ ਨਾਇਕ ਬਣੋ ਜਿਸਨੂੰ ਹਰ 21 ਦਿਨਾਂ ਬਾਅਦ ਤੁਹਾਡੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।",
