    "Please describe your conditions": "ਕਿਰਪਾ ਕਰਕੇ ਆਪਣੀਆਂ ਸਥਿਤੀਆਂ ਦਾ ਵਰਣਨ ਕਰੋ",
    "POOL SIZE": "ਪੂਲ ਦਾ ਆਕਾਰ",
    "Post-donation impact stories, milestone badges, and personalized messages keep donors emotionally connected.": "ਖੂਨ ਦਾਨ ਤੋਂ ਬਾਅਦ ਪ੍ਰਭਾਵ ਵਾਲੀਆਂ ਕਹਾਣੀਆਂ, ਮੀਲ ਪੱਥਰ ਦੇ ਬੈਜ ਅਤੇ ਵਿਅਕਤੀਗਤ ਸੰਦੇਸ਼ ਦਾਨੀਆਂ ਨੂੰ ਭਾਵਨਾਤਮਕ ਤੌਰ 'ਤੇ ਜੋੜਦੇ ਹਨ।",
