    "Prathama Blood Centre (Ahmedabad, Gujarat)": "ਪ੍ਰਥਮਾ ਬਲੱਡ ਸੈਂਟਰ (ਅਹਿਮਦਾਬਾਦ, ਗੁਜਰਾਤ)",
    "Pre-Coordinated Delivery (~36 mins)": "ਪੂਰਵ-ਤਾਲਮੇਲ ਵਾਲੀ ਡਿਲਿਵਰੀ (~36 ਮਿੰਟ)",
