    "Primary Donor:": "ਪ੍ਰਾਇਮਰੀ ਦਾਨੀ:",
    "PRIMARY PATIENT": "ਪ੍ਰਾਇਮਰੀ ਮਰੀਜ਼",
    "Privacy": "ਗੋਪਨੀਯਤਾ",
    "Privacy Policy": "ਪਰਦੇਦਾਰੀ ਨੀਤੀ",
    "Profile Review": "ਪ੍ਰੋਫਾਈਲ ਸਮੀਖਿਆ",
    "Profile verified": "ਪ੍ਰੋਫਾਈਲ ਦੀ ਪੁਸ਼ਟੀ ਕੀਤੀ ਗਈ",
    "Protecting lives, one match at a time.": "ਜਾਨਾਂ ਬਚਾਉਣਾ, ਇੱਕ ਸਮੇਂ ਵਿੱਚ ਇੱਕ ਮੇਲ।",
    "Protecting lives, one match at a time. Raksha AI is transforming blood donation in India through intelligent matching and care coordination.": "ਜੀਵਨ ਦੀ ਰੱਖਿਆ, ਇੱਕ ਸਮੇਂ ਵਿੱਚ ਇੱਕ ਮੇਲ। ਰਕਸ਼ਾ AI ਬੁੱਧੀਮਾਨ ਮੇਲ ਅਤੇ ਦੇਖਭਾਲ ਦੇ ਤਾਲਮੇਲ ਰਾਹੀਂ ਭਾਰਤ ਵਿੱਚ ਖੂਨ ਦਾਨ ਵਿੱਚ ਕ੍ਰਾਂਤੀ ਲਿਆ ਰਿਹਾ ਹੈ।",
    "protects.": "ਸੁਰੱਖਿਆ ਕਰਦਾ ਹੈ।",
    "Proximity:": "ਨੇੜਤਾ:",
    "Questions? We're here to help.": "ਕੋਈ ਸਵਾਲ ਹਨ? ਅਸੀਂ ਇੱਥੇ ਤੁਹਾਡੀ ਮਦਦ ਲਈ ਹਾਂ।",
    "Radical Transparency": "ਮੂਲ ਪਾਰਦਰਸ਼ਤਾ",
    "Raksha": "ਰਕਸ਼ਾ",
    "Raksha AI": "ਰਕਸ਼ਾ AI",
    "Raksha AI — Blood Intelligence & Care Coordination for Thalassemia Patients": "Raksha AI — ਥੈਲੇਸੀਮੀਆ ਮਰੀਜ਼ਾਂ ਲਈ ਬਲੱਡ ਇੰਟੈਲੀਜੈਂਸ ਅਤੇ ਦੇਖਭਾਲ ਤਾਲਮੇਲ",
    "RAKSHA AI — DONOR INTELLIGENCE": "ਰਕਸ਼ਾ AI — ਡੋਨਰ ਇੰਟੈਲੀਜੈਂਸ",
    "Raksha AI builds a dedicated donor circle around your patient. Smart reminders, compatibility matching, and predictive scheduling.": "ਰਕਸ਼ਾ AI ਤੁਹਾਡੇ ਮਰੀਜ਼ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਇੱਕ ਸਮਰਪਿਤ ਦਾਨੀ ਚੱਕਰ ਬਣਾਉਂਦਾ ਹੈ। ਸਮਾਰਟ ਰੀਮਾਈਂਡਰ, ਅਨੁਕੂਲਤਾ ਮੇਲ, ਅਤੇ ਅਨੁਮਾਨਿਤ ਸਮਾਂ-ਸਾਰਣੀ।",
    "Raksha AI builds a permanent support system around your patient.": "ਰਕਸ਼ਾ AI ਤੁਹਾਡੇ ਮਰੀਜ਼ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਇੱਕ ਸਥਾਈ ਸਹਾਇਤਾ ਪ੍ਰਣਾਲੀ ਬਣਾਉਂਦਾ ਹੈ।",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "ਰਕਸ਼ਾ AI ਰਜਿਸਟਰਡ ਦਾਨੀਆਂ ਦੇ ਵਿਸਤ੍ਰਿਤ ਫੇਨੋਟਾਈਪੀਕਲ ਪ੍ਰੋਫਾਈਲਾਂ ਨੂੰ ਸੂਚੀਬੱਧ ਕਰਦਾ ਹੈ ਅਤੇ ਮਰੀਜ਼ ਦੇ ਪ੍ਰੋਫਾਈਲਾਂ ਨਾਲ ਉਹਨਾਂ ਦਾ ਮੇਲ ਕਰਦਾ ਹੈ। ਸਥਾਨਕ ਡੇਟਾਬੇਸ ਵਿੱਚ ਸਹੀ ਜਾਂ ਬਹੁਤ ਜ਼ਿਆਦਾ ਅਨੁਕੂਲ ਐਂਟੀਜੇਨ ਮੇਲ ਲੱਭ ਕੇ, ਅਸੀਂ ਇਮਿਊਨ ਪ੍ਰਤੀਕਿਰਿਆਵਾਂ ਨੂੰ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਰੋਕਦੇ ਹਾਂ, ਸੁਰੱਖਿਅਤ, ਪ੍ਰਭਾਵਸ਼ਾਲੀ ਅਤੇ ਟਿਕਾਊ ਖੂਨ ਚੜ੍ਹਾਉਣ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਂਦੇ ਹਾਂ।",
    "Raksha AI communicates via app, SMS, and WhatsApp — in Hindi, Tamil, Marathi, Bengali, Telugu, and more.": "ਰਕਸ਼ਾ AI ਐਪ, ਐਸਐਮਐਸ ਅਤੇ ਵਟਸਐਪ ਰਾਹੀਂ ਹਿੰਦੀ, ਤਮਿਲ, ਮਰਾਠੀ, ਬੰਗਾਲੀ, ਤੇਲਗੂ ਅਤੇ ਹੋਰ ਭਾਸ਼ਾਵਾਂ ਵਿੱਚ ਗੱਲਬਾਤ ਕਰਦਾ ਹੈ।",
    "Raksha AI compression: 85% time saved": "ਰਕਸ਼ਾ AI ਕੰਪਰੈਸ਼ਨ: 85% ਸਮੇਂ ਦੀ ਬਚਤ",
    "Raksha AI connects voluntary blood donors with Thalassemia patients across India — through intelligent matching, automated scheduling, and care that never stops.": "ਰਕਸ਼ਾ AI ਪੂਰੇ ਭਾਰਤ ਵਿੱਚ ਥੈਲੇਸੀਮੀਆ ਮਰੀਜ਼ਾਂ ਨੂੰ ਸਵੈਇੱਛਤ ਖੂਨ ਦਾਨੀਆਂ ਨਾਲ ਜੋੜਦਾ ਹੈ — ਬੁੱਧੀਮਾਨ ਮੇਲ, ਸਵੈਚਾਲਿਤ ਯੋਜਨਾਬੰਦੀ ਅਤੇ ਨਿਰੰਤਰ ਦੇਖਭਾਲ ਦੁਆਰਾ।",
    "Raksha AI considers ABO compatibility, Rh phenotype, Kell antigen status, and alloimmunization history.": "ਰਕਸ਼ਾ AI ਏਬੀਓ ਅਨੁਕੂਲਤਾ, ਆਰਐਚ ਫੀਨੋਟਾਈਪ, ਕੈਲ ਐਂਟੀਜੇਨ ਸਥਿਤੀ, ਅਤੇ ਐਲੋਇਮਯੂਨਾਈਜ਼ੇਸ਼ਨ ਇਤਿਹਾਸ 'ਤੇ ਵਿਚਾਰ ਕਰਦਾ ਹੈ।",
    "Raksha AI matches you to a specific patient based on blood compatibility, location, and availability.": "ਰਕਸ਼ਾ AI ਖੂਨ ਦੀ ਅਨੁਕੂਲਤਾ, ਸਥਾਨ ਅਤੇ ਉਪਲਬਧਤਾ ਦੇ ਅਧਾਰ 'ਤੇ ਤੁਹਾਨੂੰ ਇੱਕ ਖਾਸ ਮਰੀਜ਼ ਨਾਲ ਮਿਲਾਉਂਦਾ ਹੈ।",
    "Raksha AI v0.1 Launches": "ਰਕਸ਼ਾ AI v0.1 ਲਾਂਚ",
    "Raksha AI was built to be the infrastructure Blood Warriors never had — an intelligent, adaptive, multilingual platform that matches donors to patients.": "ਰਕਸ਼ਾ AI ਨੂੰ ਉਸ ਬੁਨਿਆਦੀ ਢਾਂਚੇ ਦੇ ਰੂਪ ਵਿੱਚ ਬਣਾਇਆ ਗਿਆ ਸੀ ਜੋ ਬਲੱਡ ਵਾਰੀਅਰਜ਼ ਕੋਲ ਕਦੇ ਨਹੀਂ ਸੀ — ਇੱਕ ਬੁੱਧੀਮਾਨ, ਲਚਕਦਾਰ, ਬਹੁ-ਭਾਸ਼ਾਈ ਪਲੇਟਫਾਰਮ ਜੋ ਦਾਨੀਆਂ ਨੂੰ ਮਰੀਜ਼ਾਂ ਨਾਲ ਮਿਲਾਉਂਦਾ ਹੈ।",
    "Raksha AI was built to eliminate that uncertainty. We match patients with committed donors, predict transfusion needs, and ensure no patient ever faces a shortage alone.": "ਰਕਸ਼ਾ AI ਨੂੰ ਉਸੇ ਅਨਿਸ਼ਚਿਤਤਾ ਨੂੰ ਖਤਮ ਕਰਨ ਲਈ ਬਣਾਇਆ ਗਿਆ ਸੀ। ਅਸੀਂ ਮਰੀਜ਼ਾਂ ਨੂੰ ਵਚਨਬੱਧ ਦਾਨੀਆਂ ਨਾਲ ਮਿਲਾਉਂਦੇ ਹਾਂ, ਖੂਨ ਚੜ੍ਹਾਉਣ ਦੀਆਂ ਜ਼ਰੂਰਤਾਂ ਦਾ ਅੰਦਾਜ਼ਾ ਲਗਾਉਂਦੇ ਹਾਂ, ਅਤੇ ਇਹ ਯਕੀਨੀ ਬਣਾਉਂਦੇ ਹਾਂ ਕਿ ਕੋਈ ਵੀ ਮਰੀਜ਼ ਕਦੇ ਵੀ ਇਕੱਲੇ ਖੂਨ ਦੀ ਘਾਟ ਦਾ ਸਾਹਮਣਾ ਨਾ ਕਰੇ।",
