    "What happens next": "ਅੱਗੇ ਕੀ ਹੁੰਦਾ ਹੈ",
    "WHAT HAPPENS NEXT": "ਅੱਗੇ ਕੀ ਹੁੰਦਾ ਹੈ",
    "What is Alloimmunization?": "ਐਲੋਇਮਿਊਨਾਈਜ਼ੇਸ਼ਨ ਕੀ ਹੈ?",
    "What is Chelation Therapy?": "ਚੀਲੇਸ਼ਨ ਥੈਰੇਪੀ ਕੀ ਹੈ?",
    "What is extended antigen typing?": "ਐਕਸਟੈਂਡਡ ਐਂਟੀਜਨ ਟਾਈਪਿੰਗ ਕੀ ਹੈ?",
    "What Is Thalassemia?": "ਥੈਲੇਸੀਮੀਆ ਕੀ ਹੈ?",
    "What We Stand For": "ਸਾਡੇ ਆਦਰਸ਼",
    "What would you like to discuss?": "ਤੁਸੀਂ ਕਿਸ ਬਾਰੇ ਚਰਚਾ ਕਰਨਾ ਚਾਹੋਗੇ?",
    "WhatsApp available?": "ਕੀ ਵਟਸਐਪ ਉਪਲਬਧ ਹੈ?",
    "when a patient near me urgently needs my blood type. I can opt out in": "ਜਦੋਂ ਮੇਰੇ ਨੇੜੇ ਕੋਈ ਮਰੀਜ਼ ਨੂੰ ਤੁਰੰਤ ਮੇਰੇ ਬਲੱਡ ਗਰੁੱਪ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਮੈਂ ਇਸ ਵਿੱਚੋਂ ਬਾਹਰ ਨਿਕਲ ਸਕਦਾ ਹਾਂ",
    "When there is a mismatch in these minor antigens, the recipient's immune system identifies them as foreign, triggering B-lymphocytes to produce specific alloantibodies. Upon subsequent transfusions with cells carrying the same antigens, the antibodies bind to the donor cells, leading to extravascular hemolysis (destruction of red cells in the spleen or liver).": "ਜਦੋਂ ਇਹਨਾਂ ਮਾਮੂਲੀ ਐਂਟੀਜਨਾਂ ਵਿੱਚ ਕੋਈ ਮੇਲ ਨਹੀਂ ਹੁੰਦਾ, ਤਾਂ ਪ੍ਰਾਪਤਕਰਤਾ ਦੀ ਇਮਿਊਨ ਸਿਸਟਮ ਉਹਨਾਂ ਨੂੰ ਬਾਹਰੀ ਵਜੋਂ ਪਛਾਣਦੀ ਹੈ, ਜੋ ਬੀ-ਲਿੰਫੋਸਾਈਟਸ ਨੂੰ ਖਾਸ ਐਲੋਐਂਟੀਬਾਡੀਜ਼ ਪੈਦਾ ਕਰਨ ਲਈ ਉਤੇਜਿਤ ਕਰਦੀ ਹੈ। ਉਸੇ ਐਂਟੀਜਨਾਂ ਵਾਲੇ ਸੈੱਲਾਂ ਦੇ ਨਾਲ ਅਗਲੇ ਖੂਨ ਚੜ੍ਹਾਉਣ 'ਤੇ, ਐਂਟੀਬਾਡੀਜ਼ ਦਾਨੀ ਸੈੱਲਾਂ ਨਾਲ ਜੁੜ ਜਾਂਦੇ ਹਨ, ਜਿਸ ਨਾਲ ਐਕਸਟਰਾਵੈਸਕੁਲਰ ਹੀਮੋਲਿਸਿਸ (ਤਿੱਲੀ ਜਾਂ ਜਿਗਰ ਵਿੱਚ ਲਾਲ ਸੈੱਲਾਂ ਦਾ ਵਿਨਾਸ਼) ਹੁੰਦਾ ਹੈ।",
    "When you register as a recurring donor on Raksha AI, you aren't just giving a random unit of blood. You are committing to becoming a lifeline for a specific patient. Regular donations (every 3 months for men, every 4 months for women) provide stable, compatible blood and ensure the patient's hemoglobin levels remain in a safe, healthy zone.": "ਜਦੋਂ ਤੁਸੀਂ Raksha AI 'ਤੇ ਇੱਕ પુનરાવર્ਤਿਤ દાਤਾ તરીકે ਰਜਿਸਟਰ ਕਰਦੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਸਿਰਫ਼ ਖੂਨ ਦੀ ਇੱਕ ਰਲਵੀਂ ਯੂਨਿਟ ਨਹੀਂ ਦੇ ਰਹੇ ਹੁੰਦੇ। ਤੁਸੀਂ ਇੱਕ ਖਾਸ ਮਰੀਜ਼ ਲਈ ਜੀਵਨ-ਰੇਖਾ ਬਣਨ ਲਈ ਵਚਨਬੱਧ ਹੋ ਰਹੇ ਹੋ। ਨਿਯਮਤ ਦਾਨ (ਪੁਰਸ਼ਾਂ ਲਈ ਹਰ 3 ਮਹੀਨੇ, ਔਰਤਾਂ ਲਈ ਹਰ 4 ਮਹੀਨੇ) ਸਥਿਰ, ਅਨੁਕੂਲ ਖੂਨ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ ਅਤੇ ਇਹ ਯਕੀਨੀ ਬਣਾਉਂਦੇ ਹਨ ਕਿ ਮਰੀਜ਼ ਦੇ ਹੀਮੋਗਲੋਬਿਨ ਦਾ ਪੱਧਰ ਇੱਕ ਸੁਰੱਖਿਅਤ, ਸਿਹਤਮੰਦ ਖੇਤਰ ਵਿੱਚ ਰਹੇ।",
    "Where do transfusions happen?": "ਟ੍ਰਾਂਸਫਿਊਜ਼ਨ ਕਿੱਥੇ ਹੁੰਦੇ ਹਨ?",
    "Why Iron Overload Happens": "ਆਇਰਨ ਓਵਰਲੋਡ ਕਿਉਂ ਹੁੰਦਾ ਹੈ",
    "Why Thalassemia Patients Need the Same Donor to Come Back": "ਥੈਲੇਸੀਮੀਆ ਦੇ ਮਰੀਜ਼ਾਂ ਨੂੰ ਉਸੇ ਦਾਤਾ ਨੂੰ ਵਾਪਸ ਆਉਣ ਦੀ ਲੋੜ ਕਿਉਂ ਪੈਂਦੀ ਹੈ",
