    "Without": "ਬਿਨਾ",
    "World Thalassemia Day Blood Drive": "ਵਿਸ਼ਵ ਥੈਲੇਸੀਮੀਆ ਦਿਵਸ ਬਲੱਡ ਡਰਾਈਵ",
    "XGBoost": "XGBoost",
    "Yes": "ਹਾਂ",
    "You are not just a blood type. You are someone's lifeline.": "ਤੁਸੀਂ ਸਿਰਫ਼ ਇੱਕ ਖੂਨ ਦਾ ਗਰੁੱਪ ਨਹੀਂ ਹੋ। ਤੁਸੀਂ ਕਿਸੇ ਦੀ ਜੀਵਨ ਰੇਖਾ ਹੋ।",
    "You donate once. Raksha makes sure you never stop mattering.": "ਤੁਸੀਂ ਇੱਕ ਵਾਰ ਦਾਨ ਕਰਦੇ ਹੋ। ਰਕਸ਼ਾ ਇਹ ਯਕੀਨੀ ਬਣਾਉਂਦਾ ਹੈ ਕਿ ਤੁਹਾਡਾ ਯੋਗਦਾਨ ਹਮੇਸ਼ਾ ਕੀਮਤੀ ਰਹੇ।",
    "You give blood once. Raksha AI turns that into a relationship. We remind you when you're eligible again, match you with patients who need your blood type, and show you the impact you're making — not in abstract numbers, but in real lives.": "ਤੁਸੀਂ ਇੱਕ ਵਾਰ ਖੂਨ ਦਾਨ ਕਰਦੇ ਹੋ। ਰਕਸ਼ਾ AI ਉਸਨੂੰ ਇੱਕ ਰਿਸ਼ਤੇ ਵਿੱਚ ਬਦਲ ਦਿੰਦਾ ਹੈ। ਜਦੋਂ ਤੁਸੀਂ ਦੁਬਾਰਾ ਯੋਗ ਹੁੰਦੇ ਹੋ ਤਾਂ ਅਸੀਂ ਤੁਹਾਨੂੰ ਯਾਦ ਦਿਵਾਉਂਦੇ ਹਾਂ, ਤੁਹਾਡੇ ਖੂਨ ਦੇ ਗਰੁੱਪ ਦੀ ਲੋੜ ਵਾਲੇ ਮਰੀਜ਼ਾਂ ਨਾਲ ਤੁਹਾਨੂੰ ਮਿਲਾਉਂਦੇ ਹਾਂ, ਅਤੇ ਤੁਹਾਡੇ ਦੁਆਰਾ ਪਾਏ ਗਏ ਪ੍ਰਭਾਵ ਨੂੰ ਦਿਖਾਉਂਦੇ ਹਾਂ — ਅਮੂਰਤ ਨੰਬਰਾਂ ਵਿੱਚ ਨਹੀਂ, ਬਲਕਿ ਅਸਲ ਜ਼ਿੰਦਗੀ ਵਿੱਚ।",
    "You Save a Life": "ਤੁਸੀਂ ਇੱਕ ਜੀਵਨ ਬਚਾਉਂਦੇ ਹੋ",
    "You will feel a quick pinch when the needle is inserted, which lasts only a second. During the actual donation, which takes about 8 to 10 minutes, you should feel no pain. Our trained medical staff monitor you throughout the process to ensure you are comfortable.": "ਜਦੋਂ ਸੂਈ ਪਾਈ ਜਾਂਦੀ ਹੈ ਤਾਂ ਤੁਹਾਨੂੰ ਇੱਕ ਤੇਜ਼ ਚੁੱਭਣ ਮਹਿਸੂਸ ਹੋਵੇਗੀ, ਜੋ ਸਿਰਫ਼ ਇੱਕ ਸਕਿੰਟ ਰਹਿੰਦੀ ਹੈ। ਅਸਲ ਦਾਨ ਦੌਰਾਨ, ਜਿਸ ਵਿੱਚ ਲਗਭਗ 8 ਤੋਂ 10 ਮਿੰਟ ਲੱਗਦੇ ਹਨ, ਤੁਹਾਨੂੰ ਕੋਈ ਦਰਦ ਮਹਿਸੂਸ ਨਹੀਂ ਹੋਣਾ ਚਾਹੀਦਾ। ਸਾਡਾ ਸਿਖਲਾਈ ਪ੍ਰਾਪਤ ਮੈਡੀਕਲ ਸਟਾਫ ਇਹ ਯਕੀਨੀ ਬਣਾਉਣ ਲਈ ਕਿ ਤੁਸੀਂ ਆਰਾਮਦਾਇਕ ਹੋ, ਸਾਰੀ ਪ੍ਰਕਿਰਿਆ ਦੌਰਾਨ ਤੁਹਾਡੀ ਨਿਗਰਾਨੀ ਕਰਦਾ ਹੈ।",
    "You're now a Raksha Donor.": "ਤੁਸੀਂ ਹੁਣ ਰਕਸ਼ਾ ਦਾਨੀ ਹੋ।",
    "You're registered,": "ਤੁਸੀਂ ਰਜਿਸਟਰਡ ਹੋ,",
    "You're subscribed.": "ਤੁਸੀਂ ਸਬਸਕ੍ਰਾਈਬ ਕਰ ਲਿਆ ਹੈ।",
    "You've been fighting this alone. You don't have to anymore.": "ਤੁਸੀਂ ਇਕੱਲੇ ਇਸ ਨਾਲ ਲੜ ਰਹੇ ਹੋ। ਹੁਣ ਤੁਹਾਨੂੰ ਇਕੱਲੇ ਲੜਨ ਦੀ ਲੋੜ ਨਹੀਂ ਹੈ।",
    "You've spent years managing transfusion schedules, calling donors, and hoping someone answers. Raksha AI takes that burden off your shoulders. We predict when your child needs blood, find compatible donors, and coordinate everything — so you can focus on being a parent, not a logistics manager.": "ਤੁਸੀਂ ਖੂਨ ਚੜ੍ਹਾਉਣ ਦੇ ਸ਼ਡਿਊਲ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰਨ, ਦਾਨੀਆਂ ਨੂੰ ਕਾਲਾਂ ਕਰਨ ਅਤੇ ਕਿਸੇ ਦੇ ਜਵਾਬ ਦੇਣ ਦੀ ਉਮੀਦ ਕਰਨ ਵਿੱਚ ਸਾਲ ਬਿਤਾਏ ਹਨ। ਰਕਸ਼ਾ AI ਉਸ ਬੋਝ ਨੂੰ ਤੁਹਾਡੇ ਮੋਢਿਆਂ ਤੋਂ ਲਾਹ ਦਿੰਦਾ ਹੈ। ਅਸੀਂ ਅੰਦਾਜ਼ਾ ਲਗਾਉਂਦੇ ਹਾਂ ਕਿ ਤੁਹਾਡੇ ਬੱਚੇ ਨੂੰ ਕਦੋਂ ਖੂਨ ਦੀ ਲੋੜ ਹੈ, ਅਨੁਕੂਲ ਦਾਨੀ ਲੱਭਦੇ ਹਾਂ, ਅਤੇ ਹਰ ਚੀਜ਼ ਦਾ ਤਾਲਮੇਲ ਕਰਦੇ ਹਾਂ — ਤਾਂ ਜੋ ਤੁਸੀਂ ਲੌਜਿਸਟਿਕਸ ਮੈਨੇਜਰ ਦੀ ਬਜਾਏ ਮਾਤਾ-ਪਿਤਾ ਬਣਨ 'ਤੇ ਧਿਆਨ ਕੇਂਦਰਿਤ ਕਰ ਸਕੋ।",
