    "Your child's next transfusion is already being arranged.": "ਤੁਹਾਡੇ ਬੱਚੇ ਦੇ ਅਗਲੇ ਖੂਨ ਚੜ੍ਹਾਉਣ ਦਾ ਪ੍ਰਬੰਧ ਪਹਿਲਾਂ ਹੀ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ।",
    "Your child's next transfusion is already scheduled. Not because you spent all night calling numbers, but because Raksha AI coordinates the schedule. We build a donor circle of 5 committed donors specifically matched to your child.": "ਤੁਹਾਡੇ ਬੱਚੇ ਦਾ ਅਗਲਾ ਖੂਨ ਚੜ੍ਹਾਉਣਾ ਪਹਿਲਾਂ ਹੀ ਨਿਰਧਾਰਤ ਕੀਤਾ ਗਿਆ ਹੈ। ਇਸ ਲਈ ਨਹੀਂ ਕਿ ਤੁਸੀਂ ਸਾਰੀ ਰਾਤ ਨੰਬਰਾਂ 'ਤੇ ਕਾਲਾਂ ਕਰਨ ਵਿੱਚ ਬਿਤਾਈ, ਬਲਕਿ ਇਸ ਲਈ ਕਿ ਰਕਸ਼ਾ AI ਸ਼ਡਿਊਲ ਦਾ ਤਾਲਮੇਲ ਕਰਦਾ ਹੈ। ਅਸੀਂ ਵਿਸ਼ੇਸ਼ ਤੌਰ 'ਤੇ ਤੁਹਾਡੇ ਬੱਚੇ ਲਈ ਅਨੁਕੂਲ 5 ਵਚਨਬੱਧ ਦਾਨੀਆਂ ਦਾ ਇੱਕ ਦਾਨੀ ਚੱਕਰ ਬਣਾਉਂਦੇ ਹਾਂ।",
    "your child&apos;s circle": "ਤੁਹਾਡੇ ਬੱਚੇ ਦਾ ਸਰਕਲ",
    "Your circle of donors and caregivers will receive coordinated alerts — so nobody misses a critical transfusion.": "ਤੁਹਾਡੇ ਦਾਨੀ ਅਤੇ ਦੇਖਭਾਲ ਕਰਨ ਵਾਲਿਆਂ ਦੇ ਚੱਕਰ ਨੂੰ ਤਾਲਮੇਲ ਵਾਲੀਆਂ ਚੇਤਾਵਨੀਆਂ ਪ੍ਰਾਪਤ ਹੋਣਗੀਆਂ — ਤਾਂ ਜੋ ਕੋਈ ਵੀ ਨਾਜ਼ੁਕ ਖੂਨ ਚੜ੍ਹਾਉਣ ਤੋਂ ਖੁੰਝ ਨਾ ਜਾਵੇ।",
    "your circle.": "ਤੁਹਾਡਾ ਸਰਕਲ।",
