    "At risk (>80% window used)": "ಅಪಾಯದಲ್ಲಿದೆ (>80% ವಿಂಡೋ ಬಳಸಲಾಗಿದೆ)",
    "At the start of the school year, parents should meet with teachers and the school nurse. Explain Thalassemia in simple terms, detail the transfusion schedule, and discuss signs of low hemoglobin (such as pale skin, extreme fatigue, or shortness of breath). Provide emergency contact details and letters from your child's hematologist.": "ಶಾಲಾ ವರ್ಷದ ಆರಂಭದಲ್ಲಿ, ಪೋಷಕರು ಶಿಕ್ಷಕರನ್ನು ಮತ್ತು ಶಾಲಾ ದಾದಿಯನ್ನು ಭೇಟಿ ಮಾಡಬೇಕು. ಥಲಸೇಮಿಯಾವನ್ನು ಸರಳ ಪದಗಳಲ್ಲಿ ವಿವರಿಸಿ, ರಕ್ತ ವರ್ಗಾವಣೆ (ಟ್ರಾನ್ಸ್‌ಫ್ಯೂಷನ್) ವೇಳಾಪಟ್ಟಿಯನ್ನು ವಿವರಿಸಿ ಮತ್ತು ಕಡಿಮೆ ಹಿಮೋಗ್ಲೋಬಿನ್‌ನ ಲಕ್ಷಣಗಳನ್ನು (ಬಿಳಿಚಿಕೊಂಡ ಚರ್ಮ, ಅತಿಯಾದ ಆಯಾಸ ಅಥವಾ ಉಸಿರಾಟದ ತೊಂದರೆಯಂತಹ) ಚರ್ಚಿಸಿ. ತುರ್ತು ಸಂಪರ್ಕ ವಿವರಗಳನ್ನು ಮತ್ತು ನಿಮ್ಮ ಮಗುವಿನ ಹೆಮಟಾಲಜಿಸ್ಟ್‌ನಿಂದ ಪತ್ರಗಳನ್ನು ಒದಗಿಸಿ.",
