    "Blood compatibility goes far beyond the basic A, B, AB, and O blood groups. For patients who receive chronic transfusions, understanding extended typing is a life-saving necessity.": "ರಕ್ತದ ಹೊಂದಾಣಿಕೆಯು ಮೂಲಭೂತ A, B, AB ಮತ್ತು O ರಕ್ತದ ಗುಂಪುಗಳಿಗಿಂತ ಹೆಚ್ಚಿನದಾಗಿದೆ. ದೀರ್ಘಕಾಲದ ರಕ್ತ ವರ್ಗಾವಣೆ (ಟ್ರಾನ್ಸ್‌ಫ್ಯೂಷನ್) ಪಡೆಯುವ ರೋಗಿಗಳಿಗೆ, ವಿಸ್ತೃತ ಟೈಪಿಂಗ್ ಅನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವುದು ಜೀವ ರಕ್ಷಕ ಅಗತ್ಯವಾಗಿದೆ.",
