    "BLOOD WARRIORS × RAKSHA AI": "ಬ್ಲಡ್ ವಾರಿಯರ್ಸ್ × ರಕ್ಷಾ AI",
    "Blood Warriors Foundation": "ಬ್ಲಡ್ ವಾರಿಯರ್ಸ್ ಫೌಂಡೇಶನ್",
    "Blood Warriors Foundation has spent years building a donor community and Blood Bridge network across India. But the matching is manual. The engagement fades. The coordination is fragile.": "ಬ್ಲಡ್ ವಾರಿಯರ್ಸ್ ಫೌಂಡೇಶನ್ ಭಾರತದಾದ್ಯಂತ ದಾನಿಗಳ ಸಮುದಾಯ ಮತ್ತು ಬ್ಲಡ್ ಬ್ರಿಡ್ಜ್ ನೆಟ್‌ವರ್ಕ್ ಅನ್ನು ನಿರ್ಮಿಸಲು ವರ್ಷಗಳ ಕಾಲ ಶ್ರಮಿಸಿದೆ. ಆದರೆ ಹೊಂದಾಣಿಕೆಯು ಕೈಯಿಂದಲೇ ಮಾಡಲ್ಪಡುತ್ತದೆ. ತೊಡಗಿಸಿಕೊಳ್ಳುವಿಕೆ ಮರೆಯಾಗುತ್ತದೆ. ಸಮನ್ವಯತೆಯು ದುರ್ಬಲವಾಗಿದೆ.",
