    "BROWSE BY TOPIC": "ವಿಷಯದ ಮೂಲಕ ಬ್ರೌಸ್ ಮಾಡಿ",
    "Build your care network": "ನಿಮ್ಮ ಕೇರ್ ನೆಟ್‌ವರ್ಕ್ ಅನ್ನು ನಿರ್ಮಿಸಿ",
    "By pairing a patient with a small, dedicated pool of recurring donors who have matching minor antigens (Rh phenotype, Kell, etc.), we can minimize the variety of foreign antigens the patient's immune system encounters. This dramatically reduces the risk of alloimmunization, ensures the longevity of transfused cells, and protects the patient from life-threatening immune responses.": "ಸರಿಹೊಂದುವ ಮೈನರ್ ಆಂಟಿಜೆನ್‌ಗಳನ್ನು (Rh ಫೆನೋಟೈಪ್, ಕೆಲ್ ಇತ್ಯಾದಿ) ಹೊಂದಿರುವ ನಿಯಮಿತ ರಕ್ತದಾನಿಗಳ ಸಣ್ಣ ಗುಂಪಿನೊಂದಿಗೆ ರೋಗಿಯನ್ನು ಜೋಡಿಸುವ ಮೂಲಕ, ರೋಗಿಯ ರೋಗನಿರೋಧಕ ವ್ಯವಸ್ಥೆಯು ಎದುರಿಸುವ ಹೊರಗಿನ ಆಂಟಿಜೆನ್‌ಗಳ ವೈವಿಧ್ಯತೆಯನ್ನು ನಾವು ಕಡಿಮೆ ಮಾಡಬಹುದು. ಇದು ಅಲೋಇಮ್ಯುನೈಸೇಶನ್ ಅಪಾಯವನ್ನು ಗಣನೀಯವಾಗಿ ಕಡಿಮೆ ಮಾಡುತ್ತದೆ, ವರ್ಗಾಯಿಸಿದ ಜೀವಕೋಶಗಳ ದೀರ್ಘಾಯುಷ್ಯವನ್ನು ಖಚಿತಪಡಿಸುತ್ತದೆ ಮತ್ತು ಜೀವಕ್ಕೆ ಅಪಾಯಕಾರಿಯಾದ ರೋಗನಿರೋಧಕ ಪ್ರತಿಕ್ರಿಯೆಗಳಿಂದ ರೋಗಿಯನ್ನು ರಕ್ಷಿಸುತ್ತದೆ.",
    "By the time she is 18, she will need 210 more transfusions.": "ಅವಳಿಗೆ 18 ವರ್ಷ ತುಂಬುವ ಹೊತ್ತಿಗೆ ಇನ್ನೂ 210 ರಕ್ತ ವರ್ಗಾವಣೆಗಳು ಬೇಕಾಗುತ್ತವೆ.",
    "Calendar": "ಕ್ಯಾಲೆಂಡರ್",
    "Calling Inactive Lists (~120 mins)": "ನಿಷ್ಕ್ರಿಯ ಪಟ್ಟಿಗಳಿಗೆ ಕರೆ ಮಾಡಲಾಗುತ್ತಿದೆ (~120 ನಿಮಿಷಗಳು)",
    "Can cause fever, chills, jaundice, renal failure, and severe chest or back pain.": "ಜ್ವರ, ಚಳಿ, ಕಾಮಾಲೆ, ಮೂತ್ರಪಿಂಡ ವೈಫಲ್ಯ ಮತ್ತು ತೀವ್ರವಾದ ಎದೆ ಅಥವಾ ಬೆನ್ನು ನೋವಿಗೆ ಕಾರಣವಾಗಬಹುದು.",
    "Cancel": "ರದ್ದುಮಾಡಿ",
    "Cardiac complications": "ಹೃದಯ ಸಂಬಂಧಿ ತೊಡಕುಗಳು",
    "Care Memory": "ಕೇರ್ ಮೆಮೊರಿ",
    "CARE MEMORY": "ಕೇರ್ ಮೆಮೊರಿ",
    "Careers": "ವೃತ್ತಿಜೀವನ",
    "Channel:": "ಚಾನೆಲ್:",
    "Chat Sessions Table": "ಚಾಟ್ ಸೆಷನ್‌ಗಳ ಕೋಷ್ಟಕ",
    "chat_sessions": "chat_sessions",
    "Chelation therapy uses specialized medications (chelators) that bind to free iron in the bloodstream and tissues, allowing it to be excreted safely through urine or stool. The three commonly used chelators are Deferasirox (oral tablets), Deferiprone (oral liquid or tablets), and Desferrioxamine (subcutaneous infusion via a pump).": "ಕಿಲೇಷನ್ ಥೆರಪಿಯು ರಕ್ತಪ್ರವಾಹ ಮತ್ತು ಅಂಗಾಂಶಗಳಲ್ಲಿನ ಮುಕ್ತ ಕಬ್ಬಿಣದ ಅಂಶಕ್ಕೆ ಬಂಧಿಸುವ ವಿಶೇಷ ಔಷಧಿಗಳನ್ನು (ಕಿಲೇಟರ್‌ಗಳು) ಬಳಸುತ್ತದೆ, ಇದು ಮೂತ್ರ ಅಥವಾ ಮಲದ ಮೂಲಕ ಸುರಕ್ಷಿತವಾಗಿ ವಿಸರ್ಜನೆಯಾಗಲು ಅನುವು ಮಾಡಿಕೊಡುತ್ತದೆ. ಸಾಮಾನ್ಯವಾಗಿ ಬಳಸುವ ಮೂರು ಕಿಲೇಟರ್‌ಗಳೆಂದರೆ ಡೆಫೆರಾಸಿರೋಕ್ಸ್ (ಮೌಖಿಕ ಮಾತ್ರೆಗಳು), ಡೆಫೆರಿಪ್ರೋನ್ (ಮೌಖಿಕ ದ್ರವ ಅಥವಾ ಮಾತ್ರೆಗಳು), ಮತ್ತು ಡೆಸ್ಫೆರಿಯೊಕ್ಸಮೈನ್ (ಪಂಪ್ ಮೂಲಕ ಚರ್ಮದ ಕೆಳಗೆ ನೀಡುವ ಇನ್ಫ್ಯೂಷನ್).",
    "Children with Thalassemia can participate in physical education, but teachers should allow them to rest when fatigued. Because their oxygen-carrying capacity is lower, especially in the week leading up to a transfusion, they may need frequent breaks. Proper hydration during school hours is also essential to manage fatigue.": "ಥಲಸೇಮಿಯಾ ಇರುವ ಮಕ್ಕಳು ದೈಹಿಕ ಶಿಕ್ಷಣದಲ್ಲಿ ಭಾಗವಹಿಸಬಹುದು, ಆದರೆ ಅವರು ದಣಿದಾಗ ಶಿಕ್ಷಕರು ಅವರಿಗೆ ವಿಶ್ರಾಂತಿ ಪಡೆಯಲು ಅವಕಾಶ ನೀಡಬೇಕು. ಅವರ ಆಮ್ಲಜನಕ ಸಾಗಿಸುವ ಸಾಮರ್ಥ್ಯವು ಕಡಿಮೆ ಇರುವುದರಿಂದ, ವಿಶೇಷವಾಗಿ ರಕ್ತ ವರ್ಗಾವಣೆಗೆ ಮುನ್ನ ವಾರದಲ್ಲಿ, ಅವರಿಗೆ ಆಗಾಗ್ಗೆ ವಿರಾಮಗಳು ಬೇಕಾಗಬಹುದು. ಆಯಾಸವನ್ನು ನಿರ್ವಹಿಸಲು ಶಾಲೆಯ ಸಮಯದಲ್ಲಿ ಸರಿಯಾದ ಜಲಸಂಚಯನ (hydration) ಕೂಡ ಅವಶ್ಯಕವಾಗಿದೆ.",
    "Children with Transfusion-Dependent Thalassemia can and should participate fully in school life. Simple adjustments, open communication, and supportive peer environments make all the difference.": "ರಕ್ತ ವರ್ಗಾವಣೆ ಅವಲಂಬಿತ ಥಲಸೇಮಿಯಾ ಹೊಂದಿರುವ ಮಕ್ಕಳು ಶಾಲಾ ಜೀವನದಲ್ಲಿ ಸಂಪೂರ್ಣವಾಗಿ ಭಾಗವಹಿಸಬಹುದು ಮತ್ತು ಭಾಗವಹಿಸಬೇಕು. ಸಣ್ಣ ಹೊಂದಾಣಿಕೆಗಳು, ಮುಕ್ತ ಸಂವಹನ ಮತ್ತು ಪೂರಕ ಗೆಳೆಯರ ವಾತಾವರಣವು ದೊಡ್ಡ ಬದಲಾವಣೆಯನ್ನು ತರುತ್ತದೆ.",
    "Chronic blood transfusions introduce massive amounts of iron into the patient’s body. Because the human body lacks a natural mechanism to excrete excess iron, it accumulates in vital organs, requiring proactive chelation therapy.": "ದೀರ್ಘಕಾಲದ ರಕ್ತ ವರ್ಗಾವಣೆಗಳು ರೋಗಿಯ ದೇಹಕ್ಕೆ ಹೆಚ್ಚಿನ ಪ್ರಮಾಣದ ಕಬ್ಬಿಣದ ಅಂಶವನ್ನು ಸೇರಿಸುತ್ತವೆ. ಹೆಚ್ಚುವರಿ ಕಬ್ಬಿಣವನ್ನು ಹೊರಹಾಕಲು ಮಾನವ ದೇಹದಲ್ಲಿ ನೈಸರ್ಗಿಕ ಕಾರ್ಯವಿಧಾನವಿಲ್ಲದ ಕಾರಣ, ಅದು ಪ್ರಮುಖ ಅಂಗಗಳಲ್ಲಿ ಸಂಗ್ರಹವಾಗುತ್ತದೆ, ಇದಕ್ಕೆ ಪೂರ್ವಭಾವಿ ಕಿಲೇಷನ್ ಥೆರಪಿ ಅಗತ್ಯವಿರುತ್ತದೆ.",
