    "Donors who are currently eligible (exceeded the 90-day donation interval) and ready for matching.": "ಪ್ರಸ್ತುತ ಅರ್ಹರಾಗಿರುವ (90-ದಿನಗಳ ದೇಣಿಗೆ ಅಂತರವನ್ನು ಮೀರಿದ) ಮತ್ತು ಹೊಂದಾಣಿಕೆಗೆ ಸಿದ್ಧವಾಗಿರುವ ದೇಣಿಗೆದಾರರು.",
    "DPDP Act compliant": "DPDP ಕಾಯಿದೆಗೆ ಬದ್ಧವಾಗಿದೆ",
    "e.g. +919999999999": "ಉದಾ. +919999999999",
