    "e.g. controlled hypertension, diabetes...": "ಉದಾ. ನಿಯಂತ್ರಿತ ಅಧಿಕ ರಕ್ತದೊತ್ತಡ, ಮಧುಮೇಹ...",
    "e.g. Hyderabad": "ಉದಾ. ಹೈದರಾಬಾದ್",
    "e.g. Nizam": "ಉದಾ. ನಿಜಾಮ್",
    "Each time a patient receives blood with incompatible minor antigens, their immune system builds resistance. Over hundreds of transfusions, this becomes life-threatening.": "ಪ್ರತಿ ಬಾರಿ ರೋಗಿಯು ಅಸಮಂಜಸವಾದ ಸಣ್ಣ ಆಂಟಿಜೆನ್‌ಗಳನ್ನು ಹೊಂದಿರುವ ರಕ್ತವನ್ನು ಪಡೆದಾಗ, ಅವರ ಪ್ರತಿರಕ್ಷಣಾ ವ್ಯವಸ್ಥೆಯು ಪ್ರತಿರೋಧವನ್ನು ಬೆಳೆಸಿಕೊಳ್ಳುತ್ತದೆ. ನೂರಾರು ರಕ್ತ ವರ್ಗಾವಣೆಯ ನಂತರ, ಇದು ಜೀವಕ್ಕೆ ಅಪಾಯಕಾರಿಯಾಗುತ್ತದೆ.",
    "Each unit of transfused red blood cells contains approximately 200 mg of iron. Over a year of monthly transfusions, this amounts to a significant iron burden. If left untreated, the excess iron deposits in the liver, heart, and endocrine glands, leading to organ failure, heart disease, diabetes, and stunted growth.": "ರಕ್ತ ವರ್ಗಾವಣೆ ಮಾಡಿದ ಕೆಂಪು ರಕ್ತ ಕಣಗಳ ಪ್ರತಿಯೊಂದು ಘಟಕದಲ್ಲಿ ಸುಮಾರು 200 ಮಿಲಿಗ್ರಾಂ ಕಬ್ಬಿಣಾಂಶವಿರುತ್ತದೆ. ಒಂದು ವರ್ಷದ ಮಾಸಿಕ ರಕ್ತ ವರ್ಗಾವಣೆಯ ನಂತರ, ಇದು ಗಮನಾರ್ಹವಾದ ಕಬ್ಬಿಣದ ಹೊರೆಯನ್ನು ಉಂಟುಮಾಡುತ್ತದೆ. ಚಿಕಿತ್ಸೆ ನೀಡದಿದ್ದರೆ, ಹೆಚ್ಚುವರಿ ಕಬ್ಬಿಣವು ಯಕೃತ್ತು, ಹೃದಯ ಮತ್ತು ಅಂತಃಸ್ರಾವಕ ಗ್ರಂಥಿಗಳಲ್ಲಿ ಶೇಖರಣೆಯಾಗಿ, ಅಂಗಗಳ ವೈಫಲ್ಯ, ಹೃದಯ ಕಾಯಿಲೆ, ಮಧುಮೇಹ ಮತ್ತು ಬೆಳವಣಿಗೆಯ ಕುಂಠಿತಕ್ಕೆ ಕಾರಣವಾಗುತ್ತದೆ.",
