    "Guardian Mobile *": "ಪಾಲಕರ ಮೊಬೈಲ್ *",
    "Have questions about blood donation? We've compiled the most common questions from first-time and recurring donors to help you understand the process and your impact.": "ರಕ್ತದಾನದ ಬಗ್ಗೆ ಪ್ರಶ್ನೆಗಳಿವೆಯೇ? ಮೊದಲ ಬಾರಿಗೆ ಮತ್ತು ನಿಯಮಿತವಾಗಿ ರಕ್ತದಾನ ಮಾಡುವವರಿಂದ ಸಾಮಾನ್ಯವಾಗಿ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳನ್ನು ನಾವು ಸಂಗ್ರಹಿಸಿದ್ದೇವೆ, ಇದು ನಿಮಗೆ ಪ್ರಕ್ರಿಯೆ ಮತ್ತು ನಿಮ್ಮ ಪ್ರಭಾವವನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
    "Hb After": "Hb ನಂತರ",
    "Hb Before": "Hb ಮೊದಲು",
