    "Health Tracker": "ಆರೋಗ್ಯ ಟ್ರ್ಯಾಕರ್",
    "Healthy male donors can donate whole blood every 90 days (3 months), and female donors can donate every 120 days (4 months). This interval ensures that your body has fully replenished its red blood cells and iron stores before your next donation.": "ಆರೋಗ್ಯವಂತ ಪುರುಷ ದಾನಿಗಳು ಪ್ರತಿ 90 ದಿನಗಳಿಗೊಮ್ಮೆ (3 ತಿಂಗಳು) ಮತ್ತು ಮಹಿಳಾ ದಾನಿಗಳು ಪ್ರತಿ 120 ದಿನಗಳಿಗೊಮ್ಮೆ (4 ತಿಂಗಳು) ರಕ್ತದಾನ ಮಾಡಬಹುದು. ಈ ಅಂತರವು ನಿಮ್ಮ ಮುಂದಿನ ರಕ್ತದಾನಕ್ಕೆ ಮೊದಲು ನಿಮ್ಮ ದೇಹದ ಕೆಂಪು ರಕ್ತ ಕಣಗಳು ಮತ್ತು ಕಬ್ಬಿಣದ ಅಂಶಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಭರ್ತಿ ಮಾಡಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
    "Help us ensure you're eligible and understand when you can donate.": "ನೀವು ಅರ್ಹರೆಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು ಮತ್ತು ನೀವು ಯಾವಾಗ ದಾನ ಮಾಡಬಹುದು ಎಂಬುದನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ನಮಗೆ ಸಹಾಯ ಮಾಡಿ.",
    "help@raksha.ai": "help@raksha.ai",
