    "How BMT Works": "BMT ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ",
    "How did you hear about Raksha AI?": "Raksha AI ಬಗ್ಗೆ ನಿಮಗೆ ಹೇಗೆ ತಿಳಿಯಿತು?",
    "How It Works": "ಇದು ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ",
    "How It Works | Raksha AI": "ಇದು ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ | Raksha AI",
    "How often can I donate blood?": "ನಾನು ಎಷ್ಟು ಬಾರಿ ರಕ್ತದಾನ ಮಾಡಬಹುದು?",
    "How often?": "ಎಷ್ಟು ಬಾರಿ?",
    "How Raksha AI Bridges the Gap": "Raksha AI ಅಂತರವನ್ನು ಹೇಗೆ ಕಡಿಮೆ ಮಾಡುತ್ತದೆ",
    "HOW WE PARTNER": "ನಾವು ಹೇಗೆ ಪಾಲುದಾರರಾಗುತ್ತೇವೆ",
    "Hyperhemolysis Syndrome:": "ಹೈಪರ್ಹೆಮೋಲಿಸಿಸ್ ಸಿಂಡ್ರೋಮ್:",
    "I am the patient, parent, or legal guardian authorised to provide this information.": "ನಾನು ಈ ಮಾಹಿತಿಯನ್ನು ಒದಗಿಸಲು ಅಧಿಕಾರ ಹೊಂದಿರುವ ರೋಗಿ, ಪೋಷಕ ಅಥವಾ ಕಾನೂನುಬದ್ಧ ರಕ್ಷಕನಾಗಿದ್ದೇನೆ.",
    "I consent to Raksha AI storing and processing this patient": "ಈ ರೋಗಿಯ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸಲು ಮತ್ತು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲು ನಾನು Raksha AI ಗೆ ಸಮ್ಮತಿಸುತ್ತೇನೆ",
    "I consent to Raksha AI storing and using this information to coordinate blood donation.": "ರಕ್ತದಾನವನ್ನು ಸಂಘಟಿಸಲು ರಕ್ಷಾ AI ಈ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸಲು ಮತ್ತು ಬಳಸಲು ನಾನು ಒಪ್ಪುತ್ತೇನೆ.",
    "I Want to Donate Blood": "ನಾನು ರಕ್ತದಾನ ಮಾಡಲು ಬಯಸುತ್ತೇನೆ",
    "Identify inactive donors or deferred status updates that require care coordinator intervention.": "ਕੇರ್ ಕೋಆರ್ಡಿನೇಟರ್ ಹಸ್ತಕ್ಷೇಪದ ಅಗತ್ಯವಿರುವ ನಿಷ್ಕ್ರಿಯ ದಾನಿಗಳು ಅಥವಾ ಮುಂದೂಡಲಾದ ಸ್ಥಿತಿಯ ನವೀಕರಣಗಳನ್ನು ಗುರುತಿಸಿ.",
    "If you receive mutated genes from both parents, you have thalassemia major (Transfusion-Dependent Thalassemia). Symptoms usually appear within the first two years of life, causing severe anemia, fatigue, pale skin, and slow growth.": "ನೀವು ಎರಡೂ ಪೋಷಕರಿಂದ ರೂಪಾಂತರಿತ ಜೀನ್‌ಗಳನ್ನು ಪಡೆದರೆ, ನಿಮಗೆ ಥಲಸೆಮಿಯಾ ಮೇಜರ್ (ರಕ್ತ ವರ್ಗಾವಣೆ-ಆಶ್ರಿತ ಥಲಸೆಮಿಯಾ) ಇರುತ್ತದೆ. ಲಕ್ಷಣಗಳು ಸಾಮಾನ್ಯವಾಗಿ ಜೀವನದ ಮೊದಲ ಎರಡು ವರ್ಷಗಳಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ, ಇದು ತೀವ್ರ ರಕ್ತಹೀನತೆ, ಆಯಾಸ, ಮങ്ങിയ ಚರ್ಮ ಮತ್ತು ನಿಧಾನ ಬೆಳವಣಿಗೆಗೆ ಕಾರಣವಾಗುತ್ತದೆ.",
    "If you receive only one mutated gene from one parent, you have thalassemia minor. Carriers usually have no symptoms or very mild anemia and do not require treatment.": "ನೀವು ಒಬ್ಬ ಪೋಷಕರಿಂದ ಕೇವಲ ಒಂದು ರೂಪಾಂತರಿತ ಜೀನ್ ಅನ್ನು ಪಡೆದರೆ, ನಿಮಗೆ ಥಲಸೆಮಿಯಾ ಮೈನರ್ ಇರುತ್ತದೆ. ವಾಹಕರು ಸಾಮಾನ್ಯವಾಗಿ ಯಾವುದೇ ಲಕ್ಷಣಗಳನ್ನು ಹೊಂದಿರುವುದಿಲ್ಲ ಅಥವಾ ತೀವ್ರವಾದ ರಕ್ತಹೀನತೆಯನ್ನು ಹೊಂದಿರುತ್ತಾರೆ ಮತ್ತು ಚಿಕಿತ್ಸೆಯ ಅಗತ್ಯವಿರುವುದಿಲ್ಲ.",
    "Impact": "ಪರಿಣಾಮ",
    "Impact Dashboard": "ಪರಿಣಾಮ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್",
    "Impact So Far": "ಇದುವರೆಗಿನ ಪ್ರಭಾವ",
    "Impact Stories": "ಪರಿಣಾಮದ ಕಥೆಗಳು",
    "In India alone, over 1 lakh children are born with Thalassemia Major every year. Each patient needs 500-700 transfusions over their lifetime. That's not just 500 blood bags — it's 500 moments of uncertainty, coordination, and hope.": "ಭಾರತವೊಂದರಲ್ಲೇ ಪ್ರತಿ ವರ್ಷ 1 ಲಕ್ಷಕ್ಕೂ ಹೆಚ್ಚು ಮಕ್ಕಳು ಥಲಸೇಮಿಯಾ ಮೇಜರ್‌ನೊಂದಿಗೆ ಹುಟ್ಟುತ್ತಾರೆ. ಪ್ರತಿ ರೋಗಿಗೂ ಅವರ ಜೀವಿತಾವಧಿಯಲ್ಲಿ 500-700 ರಕ್ತ ವರ್ಗಾವಣೆಗಳು ಬೇಕಾಗುತ್ತವೆ. ಅದು ಕೇವಲ 500 ರಕ್ತದ ಚೀಲಗಳಲ್ಲ — ಅದು ಅನಿಶ್ಚಿತೆ, ಸಮನ್ವಯ ಮತ್ತು ಭರವಸೆಯ 500 ಕ್ಷಣಗಳು.",
    "In Your Language, On Your Device": "ನಿಮ್ಮ ಭಾಷೆಯಲ್ಲಿ, ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ",
