    "It wasn't a statistic. It was a name. A face. A mother who spent 6 hours on the phone.": "ಅದು ಕೇವಲ ಅಂಕಿಅಂಶವಾಗಿರಲಿಲ್ಲ. ಅದು ಒಂದು ಹೆಸರು. ಒಂದು ಮುಖ. ಫೋನ್‌ನಲ್ಲಿ 6 ಗಂಟೆ ಕಳೆದ ತಾಯಿ.",
