    "Maintaining Target Hemoglobin Levels": "ಗುರಿಯ ಹಿಮೋಗ್ಲೋಬಿನ್ ಮಟ್ಟವನ್ನು ಕಾಯ್ದುಕೊಳ್ಳುವುದು",
    "Male": "ಪುರುಷ",
    "Managing Absenteeism": "ಗೈರುಹಾಜರಿಯ ನಿರ್ವಹಣೆ",
    "Managing TDT requires a multi-specialty medical team, including hematologists, cardiologists, and endocrinologists. Through Raksha AI, patient profiles are synchronized with compatible donor groups to ensure that every transfusion is matched for major and minor antigens, protecting patients from immunization risks over their lifetime.": "TDT ನಿರ್ವಹಣೆಗೆ ಹೆಮಟಾಲಜಿಸ್ಟ್‌ಗಳು, ಕಾರ್ಡಿಯಾಲಜಿಸ್ಟ್‌ಗಳು ಮತ್ತು ಎಂಡೋಕ್ರೈನಾಲಜಿಸ್ಟ್‌ಗಳನ್ನು ಒಳಗೊಂಡ ಬಹು-ವಿಶೇಷ ವೈದ್ಯಕೀಯ ತಂಡದ ಅಗತ್ಯವಿದೆ. ರಕ್ಷಾ AI ಮೂಲಕ, ಪ್ರತಿಯೊಂದು ರಕ್ತ ವರ್ಗಾವಣೆಯು ಪ್ರಮುಖ ಮತ್ತು ಸಣ್ಣ ಪ್ರತಿಜನಕಗಳಿಗೆ ಹೊಂದಿಕೆಯಾಗುವುದನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು ರೋಗಿಯ ಪ್ರೊಫೈಲ್‌ಗಳನ್ನು ಹೊಂದಾಣಿಕೆಯಾಗುವ ದಾನಿ ಗುಂಪುಗಳೊಂದಿಗೆ ಸಿಂಕ್ರೊನೈಸ್ ಮಾಡಲಾಗುತ್ತದೆ, ಇದು ರೋಗಿಗಳನ್ನು ಜೀವಿತಾವಧಿಯ ಇಮ್ಯುನೈಸೇಶನ್ ಅಪಾಯಗಳಿಂದ ರಕ್ಷಿಸುತ್ತದೆ.",
    "Managing transfusion-dependent thalassemia requires meticulous planning, emotional resilience, and active coordination. This guide helps parents navigate the schedule and support their child effectively.": "ರಕ್ತ ವರ್ಗಾವಣೆ-ಅವಲಂಬಿತ ಥಲಸೇಮಿಯಾವನ್ನು ನಿರ್ವಹಿಸಲು ಸೂಕ್ಷ್ಮ ಯೋಜನೆ, ಭಾವನಾತ್ಮಕ ಸ್ಥಿತಿಸ್ಥಾಪಕತ್ವ ಮತ್ತು ಸಕ್ರಿಯ ಸಮನ್ವಯ ಅಗತ್ಯವಿರುತ್ತದೆ. ಈ ಮಾರ್ಗದರ್ಶಿಯು ಪೋಷಕರಿಗೆ ವೇಳಾಪಟ್ಟಿಯನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ತಮ್ಮ ಮಗುವಿಗೆ ಪರಿಣಾಮಕಾರಿಯಾಗಿ ಬೆಂಬಲ ನೀಡಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
    "Manual confirmation, check-in delays, and coordination gaps at the bedside.": "ಬೆಡ್‌ಸೈಡ್‌ನಲ್ಲಿ ಮ್ಯಾನುವಲ್ ದೃಢೀಕರಣ, ಚೆಕ್-ಇನ್ ವಿಳಂಬಗಳು ಮತ್ತು ಸಮನ್ವಯದ ಕೊರತೆಗಳು.",
    "Manual Coordination": "ಮ್ಯಾನುವಲ್ ಸಮನ್ವಯ",
    "Manually trigger SMS alerts to matching donor circles via Amazon SNS": "Amazon SNS ಮೂಲಕ ಹೊಂದಾಣಿಕೆಯಾಗುವ ದಾನಿ ವೃತ್ತಗಳಿಗೆ ಮ್ಯಾನುವಲ್ ಆಗಿ SMS ಎಚ್ಚರಿಕೆಗಳನ್ನು ಕಳುಹಿಸಿ",
