    "Most blood donation platforms treat every donation as a one-time transaction. For Thalassemia patients, that model is dangerous. Here's why recurring, compatible donation is a medical necessity.": "ಹೆಚ್ಚಿನ ರಕ್ತದಾನ ವೇದಿಕೆಗಳು ಪ್ರತಿ ದಾನವನ್ನು ಒಂದು-ಬಾರಿ ವಹಿವಾಟು ಎಂದು ಪರಿಗಣಿಸುತ್ತವೆ. ಥಲಮೀವಿಯಾ ರೋಗಿಗಳಿಗೆ, ಆ ಮಾದರಿಯು ಅಪಾಯಕಾರಿ. ಪುನರಾವರ್ತಿತ, ಹೊಂದಿಕೆಯಾಗುವ ದಾನವು ಏಕೆ ವೈದ್ಯಕೀಯ ಅಗತ್ಯವಾಗಿದೆ ಎಂಬುದಕ್ಕೆ ಇಲ್ಲಿ ಕಾರಣ ನೀಡಲಾಗಿದೆ.",
    "Most donors feel fine after donation. Some may experience mild lightheadedness, which quickly resolves after resting for 10-15 minutes and having a light snack and water. We recommend avoiding strenuous physical activity or heavy lifting for the rest of the day.": "ಹೆಚ್ಚಿನ ದಾನಿಗಳು ದಾನದ ನಂತರ ಉತ್ತಮವಾಗಿರುತ್ತಾರೆ. ಕೆಲವರು ಲಘುವಾದ ತಲೆತಿರುಗುವಿಕೆಯನ್ನು ಅನುಭವಿಸಬಹುದು, ಇದು 10-15 ನಿಮಿಷಗಳ ಕಾಲ ವಿಶ್ರಾಂತಿ ಪಡೆದ ನಂತರ ಮತ್ತು ಲಘು ತಿಂಡಿ ಹಾಗೂ ನೀರು ಕುಡಿದ ನಂತರ ಶೀಘ್ರವಾಗಿ ನಿವಾರಣೆಯಾಗುತ್ತದೆ. ದಿನದ ಉಳಿದ ಸಮಯಕ್ಕೆ ಕಠಿಣ ದೈಹಿಕ ಚಟುವಟಿಕೆ ಅಥವಾ ಭಾರವಾದ ವಸ್ತುಗಳನ್ನು ಎತ್ತುವುದನ್ನು ತಪ್ಪಿಸಲು ನಾವು ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ.",
