    "No more sporadic donations. No more wondering if your blood made a difference. Become a recurring hero for someone who needs you every 21 days.": "ಇನ್ನು ಮುಂದೆ ಸಾಂದರ್ಭಿಕ ರಕ್ತದಾನಗಳ ಅಗತ್ಯವಿಲ್ಲ. ನಿಮ್ಮ ರಕ್ತದಿಂದ ಪ್ರಯೋಜನವಾಯಿತೇ ಎಂದು ಯೋಚಿಸುವ ಅಗತ್ಯವಿಲ್ಲ. ಪ್ರತಿ 21 ದಿನಗಳಿಗೊಮ್ಮೆ ನಿಮ್ಮ ಅಗತ್ಯವಿರುವ ಯಾರಿಗಾದರೂ ಮರುಕಳಿಸುವ ನಾಯಕರಾಗಿ.",
