    "Patients with Thalassemia Major require lifelong medical care, including regular blood transfusions (every few weeks) to maintain healthy hemoglobin levels, combined with iron chelation therapy to remove excess iron from the body. For some patients, a bone marrow transplant can offer a permanent cure.": "ಥಲಮಿಸೀಮಿಯಾ ಮೇಜರ್ ಹೊಂದಿರುವ ರೋಗಿಗಳಿಗೆ ಜೀವಮಾನದ ವೈದ್ಯಕೀಯ ಆರೈಕೆ ಅಗತ್ಯವಿದೆ, ಇದರಲ್ಲಿ ಆರೋಗ್ಯಕರ ಹಿಮೋಗ್ಲೋಬಿನ್ ಮಟ್ಟವನ್ನು ನಿರ್ವಹಿಸಲು ನಿಯಮಿತ ರಕ್ತ ವರ್ಗಾವಣೆಗಳು (ಪ್ರತಿ ಕೆಲವು ವಾರಗಳಿಗೊಮ್ಮೆ) ಮತ್ತು ದೇಹದಿಂದ ಹೆಚ್ಚುವರಿ ಕಬ್ಬಿಣವನ್ನು ತೆಗೆದುಹಾಕಲು ಕಬ್ಬಿಣದ ಚೀಲೇಷನ್ ಚಿಕಿತ್ಸೆಯು ಸೇರಿವೆ. ಕೆಲವು ರೋಗಿಗಳಿಗೆ, ಮೂಳೆ ಮಜ್ಜೆ ಕಸಿ ಶಾಶ್ವತ ಪರಿಹಾರವನ್ನು ನೀಡಬಹುದು.",
    "Persistent context recall": "ಪರ್ಸಿಸ್ಟೆಂಟ್ ಕಾಂಟೆಕ್ಸ್ಟ್ ರೀಕಾಲ್",
