    "Primary caregiver": "ಪ್ರಾಥಮಿಕ ಆರೈಕೆದಾರ",
    "Primary Donor:": "ಪ್ರಾಥಮಿಕ ದಾನಿ:",
    "PRIMARY PATIENT": "ಪ್ರಾಥಮಿಕ ರೋಗಿ",
    "Privacy": "ಗೌಪ್ಯತೆ",
    "Privacy Policy": "ಗೌಪ್ಯತಾ ನೀತಿ",
    "Profile Review": "ಪ್ರೊಫೈಲ್ ವಿಮರ್ಶೆ",
    "Profile verified": "ಪ್ರೊಫೈಲ್ ಪರಿಶೀಲಿಸಲಾಗಿದೆ",
    "Protecting lives, one match at a time.": "ಜೀವಗಳನ್ನು ರಕ್ಷಿಸುವುದು, ಒಂದು ಸಮಯದಲ್ಲಿ ಒಂದು ಹೋಲಿಕೆ.",
    "Protecting lives, one match at a time. Raksha AI is transforming blood donation in India through intelligent matching and care coordination.": "ಜೀವ ಉಳಿಸುವುದು, ಒಂದು ಬಾರಿಗೆ ಒಂದು ಹೊಂದಾಣಿಕೆ. ರಕ್ಷಾ AI ಬುದ್ಧಿವಂತ ಹೊಂದಾಣಿಕೆ ಮತ್ತು ಕಾಳಜಿ ಸಮನ್ವಯದ ಮೂಲಕ ಭಾರತದಲ್ಲಿ ರಕ್ತದಾನವನ್ನು ಪರಿವರ್ತಿಸುತ್ತಿದೆ.",
    "protects.": "ರಕ್ಷಿಸುತ್ತದೆ.",
    "Proximity:": "ಸಾಮೀಪ್ಯ:",
    "Questions? We're here to help.": "ಪ್ರಶ್ನೆಗಳಿವೆಯೇ? ನಾವು ಸಹಾಯ ಮಾಡಲು ಇಲ್ಲಿದ್ದೇವೆ.",
    "Radical Transparency": "ಆಮೂಲಾಗ್ರ ಪಾರದರ್ಶಕತೆ",
    "Raksha": "ರಕ್ಷಾ",
    "Raksha AI": "ರಕ್ಷಾ AI",
    "Raksha AI — Blood Intelligence & Care Coordination for Thalassemia Patients": "Raksha AI — ಥಲಮಿಯಾ ರೋಗಿಗಳಿಗೆ ರಕ್ತ ಬುದ್ಧಿವಂತಿಕೆ ಮತ್ತು ಆರೈಕೆ ಸಂಯೋಜನೆ",
    "RAKSHA AI — DONOR INTELLIGENCE": "ರಕ್ಷಾ AI — ಡೋನರ್ ಇಂಟೆಲಿಜೆನ್ಸ್",
    "Raksha AI builds a dedicated donor circle around your patient. Smart reminders, compatibility matching, and predictive scheduling.": "ರಕ್ಷಾ AI ನಿಮ್ಮ ರೋಗಿಯ ಸುತ್ತ ಮೀಸಲಾದ ದಾನಿ ವಲಯವನ್ನು ನಿರ್ಮಿಸುತ್ತದೆ. ಸ್ಮಾರ್ಟ್ ಜ್ಞಾಪನೆಗಳು, ಹೊಂದಾಣಿಕೆಯ ಹೊಂದಾಣಿಕೆ ಮತ್ತು ಮುನ್ಸೂಚಕ ವೇಳಾಪಟ್ಟಿ.",
    "Raksha AI builds a permanent support system around your patient.": "ರಕ್ಷಾ AI ನಿಮ್ಮ ರೋಗಿಯ ಸುತ್ತ ಶಾಶ್ವತ ಬೆಂಬಲ ವ್ಯವಸ್ಥೆಯನ್ನು ನಿರ್ಮಿಸುತ್ತದೆ.",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "ರಕ್ಷಾ AI ನೋಂದಾಯಿತ ದಾನಿಗಳ ವಿಸ್ತೃತ ಫಿನೋಟೈಪಿಕಲ್ ಪ್ರೊಫೈಲ್‌ಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡುತ್ತದೆ ಮತ್ತು ಅವುಗಳನ್ನು ರೋಗಿಯ ಪ್ರೊಫೈಲ್‌ಗಳೊಂದಿಗೆ ಹೋಲಿಸುತ್ತದೆ. ಸ್ಥಳೀಯ ಡೇಟಾಬೇಸ್‌ಗಳಲ್ಲಿ ನಿಖರವಾದ ಅಥವಾ ಹೆಚ್ಚು ಹೊಂದಾಣಿಕೆಯಾಗುವ ಪ್ರತಿಜನಕ ಹೋಲಿಕೆಗಳನ್ನು ಕಂಡುಹಿಡಿಯುವ ಮೂಲಕ, ಪ್ರತಿರಕ್ಷಣಾ ಪ್ರತಿಕ್ರಿಯೆಗಳು ಪ್ರಾರಂಭವಾಗುವ ಮೊದಲೇ ನಾವು ಅವುಗಳನ್ನು ತಡೆಗಟ್ಟುತ್ತೇವೆ, ಸುರಕ್ಷಿತ, ಪರಿಣಾಮಕಾರಿ ಮತ್ತು ಸುಸ್ಥಿರ ರಕ್ತ ವರ್ಗಾವಣೆಯನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುತ್ತೇವೆ.",
    "Raksha AI communicates via app, SMS, and WhatsApp — in Hindi, Tamil, Marathi, Bengali, Telugu, and more.": "ರಕ್ಷಾ AI ಆಪ್, SMS ಮತ್ತು ವಾಟ್ಸಾಪ್ ಮೂಲಕ ಹಿಂದಿ, ತಮಿಳು, ಮರಾಠಿ, ಬಂಗಾಳಿ, ತೆಲುಗು ಮತ್ತು ಹೆಚ್ಚಿನ ಭಾಷೆಗಳಲ್ಲಿ ಸಂವಹನ ನಡೆಸುತ್ತದೆ.",
    "Raksha AI compression: 85% time saved": "ರಕ್ಷಾ AI ಕಂಪ್ರೆಷನ್: 85% ಸಮಯ ಉಳಿತಾಯ",
    "Raksha AI connects voluntary blood donors with Thalassemia patients across India — through intelligent matching, automated scheduling, and care that never stops.": "ರಕ್ಷಾ AI ಭಾರತದಾದ್ಯಂತ ಥಲಸೇಮಿಯಾ ರೋಗಿಗಳನ್ನು ಸ್ವಯಂಪ್ರೇರಿತ ರಕ್ತದಾನಿಗಳೊಂದಿಗೆ ಸಂಪರ್ಕಿಸುತ್ತದೆ — ಬುದ್ಧಿವಂತ ಹೊಂದಾಣಿಕೆ, ಸ್ವಯಂಚಾಲಿತ ವೇಳಾಪಟ್ಟಿ ಮತ್ತು ನಿರಂತರ ಕಾಳಜಿಯ ಮೂಲಕ.",
    "Raksha AI considers ABO compatibility, Rh phenotype, Kell antigen status, and alloimmunization history.": "ರಕ್ಷಾ AI ಎಬಿಒ ಹೊಂದಾಣಿಕೆ, Rh ಫಿನೋಟೈಪ್, ಕೆಲ್ ಆಂಟಿಜೆನ್ ಸ್ಥಿತಿ ಮತ್ತು ಅಲೋಇಮ್ಯುನೈಸೇಶನ್ ಇತಿಹಾಸವನ್ನು ಪರಿಗಣಿಸುತ್ತದೆ.",
    "Raksha AI matches you to a specific patient based on blood compatibility, location, and availability.": "ರಕ್ತದ ಹೊಂದಾಣಿಕೆ, ಸ್ಥಳ ಮತ್ತು ಲಭ್ಯತೆಯ ಆಧಾರದ ಮೇಲೆ ರಕ್ಷಾ AI ನಿಮ್ಮನ್ನು ನಿರ್ದಿಷ್ಟ ರೋಗಿಗೆ ಹೊಂದಿಸುತ್ತದೆ.",
    "Raksha AI v0.1 Launches": "ರಕ್ಷಾ AI v0.1 ಬಿಡುಗಡೆ",
    "Raksha AI was built to be the infrastructure Blood Warriors never had — an intelligent, adaptive, multilingual platform that matches donors to patients.": "ಬ್ಲಡ್ ವಾರಿಯರ್ಸ್ ಎಂದಿಗೂ ಹೊಂದಿರದ ಮೂಲಸೌಕರ್ಯವಾಗಿರಲು ರಕ್ಷಾ AI ಅನ್ನು ನಿರ್ಮಿಸಲಾಗಿದೆ — ಇದು ದಾನಿಗಳನ್ನು ರೋಗಿಗಳಿಗೆ ಹೊಂದಿಸುವ ಬುದ್ಧಿವಂತ, ಹೊಂದಿಕೊಳ್ಳಬಲ್ಲ, ಬಹುಭಾಷಾ ವೇದಿಕೆಯಾಗಿದೆ.",
    "Raksha AI was built to eliminate that uncertainty. We match patients with committed donors, predict transfusion needs, and ensure no patient ever faces a shortage alone.": "ಆ ಅನಿಶ್ಚಿತತೆಯನ್ನು ನಿವಾರಿಸಲು ರಕ್ಷಾ AI ಅನ್ನು ನಿರ್ಮಿಸಲಾಗಿದೆ. ನಾವು ರೋಗಿಗಳನ್ನು ಬದ್ಧತೆಯುಳ್ಳ ದಾನಿಗಳಿಗೆ ಹೊಂದಿಸುತ್ತೇವೆ, ರಕ್ತ ವರ್ಗಾವಣೆಯ ಅಗತ್ಯಗಳನ್ನು ಮುನ್ಸೂಚಿಸುತ್ತೇವೆ ಮತ್ತು ಯಾವುದೇ ರೋಗಿಯೂ ಎಂದಿಗೂ ಕೊರತೆಯನ್ನು ಏಕಾಂಗಿಯಾಗಿ ಎದುರಿಸದಂತೆ ನೋಡಿಕೊಳ್ಳುತ್ತೇವೆ.",
