    "Subscribe to Library Updates →": "ಗ್ರಂಥಾಲಯ ನವೀಕರಣಗಳಿಗೆ ಚಂದಾದಾರರಾಗಿ →",
    "Success!": "ಯಶಸ್ಸು!",
    "Successful donor-patient matches": "ಯಶಸ್ವಿ ದಾನಿ-ರೋಗಿ ಹೊಂದಾಣಿಕೆಗಳು",
