    "Total Transfusions": "ಒಟ್ಟು ರಕ್ತ ವರ್ಗಾವಣೆಗಳು",
    "Track & Coordinate": "ಟ್ರ್ಯಾಕ್ ಮಾಡಿ ಮತ್ತು ಸಂಯೋಜಿಸಿ",
    "Trained on:": "ಇದರ ಮೇಲೆ ತರಬೇತಿ ಪಡೆದಿದೆ:",
    "Transfusion": "ರಕ್ತ ವರ್ಗಾವಣೆ",
    "Transfusion Calendar": "ರಕ್ತ ವರ್ಗಾವಣೆ ಕ್ಯಾಲೆಂಡರ್",
